from (values
(396147,44017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie sich auf die Terrasse setzten, ... jemand den Tisch schon mit Tellern gedeckt.'::text,'hatte'::text,'hat'::text,'deckt'::text,'Als sie sich auf die Terrasse setzten, hatte jemand den Tisch schon mit Tellern gedeckt.'::text),
(396151,44017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони сіли на терасі, хтось уже ... стіл тарілками.'::text,'накрив'::text,'накрив'::text,'накриває'::text,'Коли вони сіли на терасі, хтось уже накрив стіл тарілками.'::text),
(396150,44017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se sentaron en la terraza, alguien ya ... la mesa con platos.'::text,'había puesto'::text,'ha puesto'::text,'pone'::text,'Para cuando se sentaron en la terraza, alguien ya había puesto la mesa con platos.'::text),
(396149,44017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils se sont assis sur la terrasse, quelqu''un ... la table avec des assiettes.'::text,'avait mis'::text,'a mis'::text,'met'::text,'Quand ils se sont assis sur la terrasse, quelqu''un avait mis la table avec des assiettes.'::text),
(396152,44017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terasa oturduklarında biri masayı çoktan tabaklarla ...'::text,'kurmuştu'::text,'kurmuş'::text,'kuruyor'::text,'Terasa oturduklarında biri masayı çoktan tabaklarla kurmuştu.'::text),
(396153,44017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire leültek a teraszon, valaki már ... az asztalt tányérokkal.'::text,'megterítette'::text,'megterítette'::text,'teríti'::text,'Mire leültek a teraszon, valaki már megterítette az asztalt tányérokkal.'::text),
(396156,44018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Sonne weiter scheint, ... sie morgen wieder auf der Terrasse Mittag essen.'::text,'werden'::text,'würden'::text,'aßen'::text,'Wenn die Sonne weiter scheint, werden sie morgen wieder auf der Terrasse Mittag essen.'::text),
(396160,44018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо сонце не сховається, завтра вони знову ... на терасі.'::text,'обідатимуть'::text,'обідали б'::text,'обідали'::text,'Якщо сонце не сховається, завтра вони знову обідатимуть на терасі.'::text),
(396159,44018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sigue haciendo sol, mañana ... otra vez en la terraza.'::text,'comerán'::text,'comerían'::text,'comieron'::text,'Si sigue haciendo sol, mañana comerán otra vez en la terraza.'::text),
(396158,44018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il fait toujours soleil, ils ... encore sur la terrasse demain.'::text,'déjeuneront'::text,'déjeuneraient'::text,'déjeunaient'::text,'S''il fait toujours soleil, ils déjeuneront encore sur la terrasse demain.'::text),
(396161,44018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş açık kalırsa, yarın yine terasta öğle yemeği ...'::text,'yiyecekler'::text,'yerlerdi'::text,'yediler'::text,'Güneş açık kalırsa, yarın yine terasta öğle yemeği yiyecekler.'::text),
(396162,44018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kint marad a nap, holnap megint a teraszon ...'::text,'ebédelnek'::text,'ebédelnének'::text,'ebédeltek'::text,'Ha kint marad a nap, holnap megint a teraszon ebédelnek.'::text),
(396165,44019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie eine größere Terrasse, ... sie mehr Freunde zum Mittagessen einladen.'::text,'würden'::text,'werden'::text,'laden'::text,'Hätten sie eine größere Terrasse, würden sie mehr Freunde zum Mittagessen einladen.'::text),
(396169,44019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в них була більша тераса, вони ... більше друзів на обід.'::text,'запросили б'::text,'запросять'::text,'запрошують'::text,'Якби в них була більша тераса, вони запросили б більше друзів на обід.'::text),
(396168,44019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuvieran una terraza más grande, ... a más amigos a comer.'::text,'invitarían'::text,'invitarán'::text,'invitan'::text,'Si tuvieran una terraza más grande, invitarían a más amigos a comer.'::text),
(396167,44019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils avaient une plus grande terrasse, ils ... plus d''amis à déjeuner.'::text,'inviteraient'::text,'inviteront'::text,'invitent'::text,'S''ils avaient une plus grande terrasse, ils inviteraient plus d''amis à déjeuner.'::text),
(396170,44019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha büyük bir terasları olsa, öğle yemeğine daha çok arkadaş ...'::text,'çağırırlardı'::text,'çağıracaklar'::text,'çağırıyorlar'::text,'Daha büyük bir terasları olsa, öğle yemeğine daha çok arkadaş çağırırlardı.'::text),
(396171,44019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nagyobb teraszuk lenne, ... több barátot ebédre.'::text,'meghívnának'::text,'meg fognak hívni'::text,'meghívnak'::text,'Ha nagyobb teraszuk lenne, meghívnának több barátot ebédre.'::text),
(396174,44020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absoluter Albtraum! Der Schattenplatz auf der Terrasse ..., bevor sie überhaupt da war!'::text,'war besetzt'::text,'ist besetzt'::text,'besetzte'::text,'Absoluter Albtraum! Der Schattenplatz auf der Terrasse war besetzt, bevor sie überhaupt da war!'::text),
(396178,44020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повний жах! Місце в тіні на терасі ... ще до того, як вона взагалі прийшла!'::text,'було зайняте'::text,'зайняте'::text,'зайняло'::text,'Повний жах! Місце в тіні на терасі було зайняте ще до того, як вона взагалі прийшла!'::text),
(396177,44020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una pesadilla total! ¡El sitio a la sombra de la terraza ... antes de que ella llegara siquiera!'::text,'estaba ocupado'::text,'está ocupado'::text,'ocupó'::text,'¡Una pesadilla total! ¡El sitio a la sombra de la terraza estaba ocupado antes de que ella llegara siquiera!'::text),
(396176,44020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar absolu ! La place à l''ombre sur la terrasse ... avant même qu''elle arrive !'::text,'était prise'::text,'est prise'::text,'a pris'::text,'Cauchemar absolu ! La place à l''ombre sur la terrasse était prise avant même qu''elle arrive !'::text),
(396179,44020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir kâbus! Terastaki gölge yer, o daha gelmeden ...!'::text,'kapılmıştı'::text,'kapılıyor'::text,'kaptı'::text,'Tam bir kâbus! Terastaki gölge yer, o daha gelmeden kapılmıştı!'::text),
(396180,44020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totális rémálom! Az árnyékos hely a teraszon ..., mielőtt ő egyáltalán megérkezett volna!'::text,'foglalt volt'::text,'foglalt'::text,'elfoglalta'::text,'Totális rémálom! Az árnyékos hely a teraszon foglalt volt, mielőtt ő egyáltalán megérkezett volna!'::text),
(396183,44021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den letzten Tropfen Saft in ihr Glas auf der Terrasse! Der Krug ist komplett leer!'::text,'goss'::text,'wurde gegossen'::text,'gießend'::text,'Er goss den letzten Tropfen Saft in ihr Glas auf der Terrasse! Der Krug ist komplett leer!'::text),
(396187,44021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... останню краплю соку в її келих на терасі! Глечик абсолютно порожній!'::text,'налив'::text,'був налитий'::text,'наливаючи'::text,'Він налив останню краплю соку в її келих на терасі! Глечик абсолютно порожній!'::text),
(396186,44021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... la última gota de zumo en su copa en la terraza! ¡La jarra está completamente vacía!'::text,'sirvió'::text,'fue servido'::text,'sirviendo'::text,'¡Él sirvió la última gota de zumo en su copa en la terraza! ¡La jarra está completamente vacía!'::text),
(396185,44021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la dernière goutte de jus dans son verre sur la terrasse ! La carafe est complètement vide !'::text,'a versé'::text,'a été versé'::text,'versant'::text,'Il a versé la dernière goutte de jus dans son verre sur la terrasse ! La carafe est complètement vide !'::text),
(396188,44021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terasta onun bardağına meyve suyunun son damlasını ...! Sürahi tamamen boş!'::text,'döktü'::text,'döküldü'::text,'dökerek'::text,'Terasta onun bardağına meyve suyunun son damlasını döktü! Sürahi tamamen boş!'::text),
(396189,44021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A teraszon ... az utolsó csepp gyümölcslevet a poharába! A kancsó teljesen üres!'::text,'töltötte'::text,'töltődött'::text,'töltve'::text,'A teraszon töltötte az utolsó csepp gyümölcslevet a poharába! A kancsó teljesen üres!'::text),
(396192,44022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gläser hoch auf der Terrasse! Das ... der glücklichste Tag ihres Lebens sein!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Gläser hoch auf der Terrasse! Das muss der glücklichste Tag ihres Lebens sein!'::text),
(396196,44022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Келихи вгору на терасі! Це ... бути найщасливішим днем у їхньому житті!'::text,'мусить'::text,'не може'::text,'має'::text,'Келихи вгору на терасі! Це мусить бути найщасливішим днем у їхньому житті!'::text),
(396195,44022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Copas arriba en la terraza! ¡Este ... ser el día más feliz de sus vidas!'::text,'tiene que'::text,'no puede'::text,'debería'::text,'¡Copas arriba en la terraza! ¡Este tiene que ser el día más feliz de sus vidas!'::text),
(396194,44022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Levez vos verres sur la terrasse ! Ça ... être le plus beau jour de leur vie !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Levez vos verres sur la terrasse ! Ça doit être le plus beau jour de leur vie !'::text),
(396197,44022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terasta kadehler havaya! Bu, hayatlarının en mutlu günü ...!'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Terasta kadehler havaya! Bu, hayatlarının en mutlu günü olmalı!'::text),
(396198,44022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Poharakat fel a teraszon! Ez ... életük legboldogabb napja!'::text,'biztos'::text,'nem lehet'::text,'kellene hogy legyen'::text,'Poharakat fel a teraszon! Ez biztos életük legboldogabb napja!'::text),
(396210,44024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, dass sie am Tag davor auch auf der Terrasse zu Mittag ...'::text,'gegessen hatten'::text,'gegessen haben'::text,'isst'::text,'Hör zu, sie hat gesagt, dass sie am Tag davor auch auf der Terrasse zu Mittag gegessen hatten.'::text),
(396214,44024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що вони й напередодні ... на тій терасі.'::text,'обідали'::text,'обідали'::text,'обідає'::text,'Слухай, вона сказала, що вони й напередодні обідали на тій терасі.'::text),
(396213,44024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, dijo que el día anterior también ... en esa terraza.'::text,'habían comido'::text,'han comido'::text,'come'::text,'Escucha, dijo que el día anterior también habían comido en esa terraza.'::text),
(396212,44024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit qu''ils ... aussi sur cette terrasse la veille.'::text,'avaient déjeuné'::text,'ont déjeuné'::text,'déjeune'::text,'Écoute, elle a dit qu''ils avaient déjeuné aussi sur cette terrasse la veille.'::text),
(396215,44024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o terasta bir gün önce de öğle yemeği ... söyledi.'::text,'yemiş olduklarını'::text,'yediklerini'::text,'yediğini'::text,'Dinle, o terasta bir gün önce de öğle yemeği yemiş olduklarını söyledi.'::text),
(396216,44024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy előző nap is azon a teraszon ...'::text,'ebédeltek'::text,'ebédeltek'::text,'ebédel'::text,'Figyelj, azt mondta, hogy előző nap is azon a teraszon ebédeltek.'::text),
(396219,44025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... einen winzigen Balkon, bevor sie diese Terrasse bekommen haben.'::text,'hatten sie früher'::text,'hatten sie immer'::text,'waren sie gewohnt'::text,'Okay, also angeblich hatten sie früher einen winzigen Balkon, bevor sie diese Terrasse bekommen haben.'::text),
(396223,44025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, у них ... крихітний балкон, поки не з''явилася ця тераса.'::text,'колись був'::text,'бувало, був'::text,'були звиклі мати'::text,'Коротше, кажуть, у них колись був крихітний балкон, поки не з''явилася ця тераса.'::text),
(396222,44025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues parece que ... un balcón diminuto antes de tener esta terraza.'::text,'solían tener'::text,'tenían'::text,'estaban acostumbrados a tener'::text,'Vale, pues parece que solían tener un balcón diminuto antes de tener esta terraza.'::text),
(396221,44025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment ils ... un minuscule balcon avant d''avoir cette terrasse.'::text,'avaient'::text,'avaient'::text,'étaient habitués à avoir'::text,'Bon, apparemment ils avaient un minuscule balcon avant d''avoir cette terrasse.'::text),
(396224,44025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, görünüşe göre bu terası almadan önce minicik bir balkonları ...'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Tamam, görünüşe göre bu terası almadan önce minicik bir balkonları vardı.'::text),
(396225,44025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag egy pici erkélyük ..., mielőtt megkapták ezt a teraszt.'::text,'régen volt'::text,'volt'::text,'hozzá voltak szokva'::text,'Szóval állítólag egy pici erkélyük régen volt, mielőtt megkapták ezt a teraszt.'::text),
(396228,44026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie du das ... auf deiner sonnigen Terrasse genießt, ist echt charmant.'::text,'Anstoßen'::text,'anzustoßen'::text,'anstoßen'::text,'Wie du das Anstoßen auf deiner sonnigen Terrasse genießt, ist echt charmant.'::text),
(396232,44026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Те, як ти обожнюєш ... тости на своїй сонячній терасі, — це чарівно.'::text,'виголошувати'::text,'виголошувати'::text,'виголошувати'::text,'Те, як ти обожнюєш виголошувати тости на своїй сонячній терасі, — це чарівно.'::text),
(396231,44026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lo mucho que disfrutas ... brindis en tu terraza soleada es encantador.'::text,'haciendo'::text,'hacer'::text,'hacer'::text,'Lo mucho que disfrutas haciendo brindis en tu terraza soleada es encantador.'::text),
(396230,44026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ta façon d''adorer ... des toasts sur ta terrasse ensoleillée, c''est craquant.'::text,'porter'::text,'porter'::text,'porter'::text,'Ta façon d''adorer porter des toasts sur ta terrasse ensoleillée, c''est craquant.'::text),
(396233,44026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneşli terasında kadeh ... bu kadar sevmen çok tatlı.'::text,'kaldırmayı'::text,'kaldırmak'::text,'kaldır'::text,'Güneşli terasında kadeh kaldırmayı bu kadar sevmen çok tatlı.'::text),
(396234,44026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy élvezed a ... a napos teraszodon, az nagyon bájos.'::text,'koccintást'::text,'koccintani'::text,'koccint'::text,'Ahogy élvezed a koccintást a napos teraszodon, az nagyon bájos.'::text),
(389964,43330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit der Mond aufgegangen ist, ... die Küste in blauem Licht.'::text,'funkelt'::text,'funkelt'::text,'funkelt'::text,'Seit der Mond aufgegangen ist, funkelt die Küste in blauem Licht.'::text),
(389968,43330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Узбережжя ... блакитним світлом, відколи зійшов місяць.'::text,'виблискує'::text,'виблискує'::text,'виблискує'::text,'Узбережжя виблискує блакитним світлом, відколи зійшов місяць.'::text),
(389967,43330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La orilla ... con luz azul desde que salió la luna.'::text,'ha estado centelleando'::text,'está centelleando'::text,'centellea'::text,'La orilla ha estado centelleando con luz azul desde que salió la luna.'::text),
(389966,43330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rivage ... de lumière bleue depuis que la lune s''est levée.'::text,'scintille'::text,'scintille'::text,'scintille'::text,'Le rivage scintille de lumière bleue depuis que la lune s''est levée.'::text),
(389969,43330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay doğduğundan beri kıyı mavi ışıkla ...'::text,'parıldıyor'::text,'parıldıyor'::text,'parıldar'::text,'Ay doğduğundan beri kıyı mavi ışıkla parıldıyor.'::text),
(389970,43330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amióta felkelt a hold, a part kék fényben ...'::text,'szikrázik'::text,'szikrázik'::text,'szikrázik'::text,'Amióta felkelt a hold, a part kék fényben szikrázik.'::text),
(389973,43331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Sand hat blau gefunkelt, sobald du ihn ..., ehrlich unreal.'::text,'berührt hast'::text,'gerade berührtest'::text,'berührt hast'::text,'Der Sand hat blau gefunkelt, sobald du ihn berührt hast, ehrlich unreal.'::text),
(389977,43331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пісок заблищав синім тієї ж миті, як ти ... до нього, чесно, нереально.'::text,'торкнулася'::text,'торкалася'::text,'торкнулася'::text,'Пісок заблищав синім тієї ж миті, як ти торкнулася до нього, чесно, нереально.'::text),
(389976,43331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La arena brilló en azul en cuanto la ..., sinceramente irreal.'::text,'tocaste'::text,'estabas tocando'::text,'has tocado'::text,'La arena brilló en azul en cuanto la tocaste, sinceramente irreal.'::text),
(389975,43331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sable a scintillé en bleu dès que tu ..., franchement irréel.'::text,'l''as touché'::text,'le touchais'::text,'l''as touché'::text,'Le sable a scintillé en bleu dès que tu l''as touché, franchement irréel.'::text),
(389978,43331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ona ... anda kum maviye parladı, cidden gerçeküstü.'::text,'dokunduğun'::text,'dokunmakta olduğun'::text,'dokunmuş olduğun'::text,'Ona dokunduğun anda kum maviye parladı, cidden gerçeküstü.'::text),
(389979,43331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A homok kéken szikrázott, amint ..., őszintén, valószerűtlen.'::text,'hozzáértél'::text,'éppen hozzáértél'::text,'hozzáértél'::text,'A homok kéken szikrázott, amint hozzáértél, őszintén, valószerűtlen.'::text),
(389982,43332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... drei perfekte Spiralen gezeichnet, und jede davon hat gefunkelt.'::text,'hast'::text,'hast'::text,'zeichnest'::text,'Respekt, du hast drei perfekte Spiralen gezeichnet, und jede davon hat gefunkelt.'::text),
(389986,43332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... три ідеальні спіралі, і кожна з них виблискувала.'::text,'намалювала'::text,'малювала'::text,'малюєш'::text,'Респект, ти намалювала три ідеальні спіралі, і кожна з них виблискувала.'::text),
(389985,43332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ... tres espirales perfectas y todas brillaron.'::text,'has dibujado'::text,'has estado dibujando'::text,'estás dibujando'::text,'Respeto, has dibujado tres espirales perfectas y todas brillaron.'::text),
(389984,43332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... trois spirales parfaites, et chacune a scintillé.'::text,'as dessiné'::text,'as dessiné'::text,'dessines'::text,'Respect, tu as dessiné trois spirales parfaites, et chacune a scintillé.'::text),
(389987,43332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, üç kusursuz spiral ... ve her biri parıldadı.'::text,'çizdin'::text,'çiziyordun'::text,'çiziyorsun'::text,'Helal, üç kusursuz spiral çizdin ve her biri parıldadı.'::text),
(389988,43332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, három tökéletes spirált ..., és mindegyik szikrázott.'::text,'rajzoltál'::text,'rajzolgattál'::text,'rajzolsz'::text,'Respekt, három tökéletes spirált rajzoltál, és mindegyik szikrázott.'::text),
(389991,43333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie aufstand, ... ihre leuchtende Spirale schon aufgehört zu funkeln. Nicht ideal.'::text,'hatte'::text,'hat'::text,'hört'::text,'Als sie aufstand, hatte ihre leuchtende Spirale schon aufgehört zu funkeln. Nicht ideal.'::text),
(389995,43333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона встала, її сяйлива спіраль уже ... виблискувати. Не ідеально.'::text,'перестала'::text,'перестала'::text,'перестає'::text,'Поки вона встала, її сяйлива спіраль уже перестала виблискувати. Не ідеально.'::text),
(389994,43333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se levantó, su espiral brillante ya ... de centellear. No es lo ideal.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Para cuando se levantó, su espiral brillante ya había dejado de centellear. No es lo ideal.'::text),
(389993,43333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''elle se relève, sa spirale lumineuse ... de scintiller. Pas idéal.'::text,'avait cessé'::text,'a cessé'::text,'cesse'::text,'Le temps qu''elle se relève, sa spirale lumineuse avait cessé de scintiller. Pas idéal.'::text),
(389996,43333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ayağa kalktığında parlayan spirali çoktan parıldamayı ..., pek ideal değil.'::text,'bırakmıştı'::text,'bıraktı'::text,'bırakıyor'::text,'O ayağa kalktığında parlayan spirali çoktan parıldamayı bırakmıştı, pek ideal değil.'::text),
(389997,43333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felállt, a világító spirálja már ... a szikrázást. Nem ideális.'::text,'abbahagyta'::text,'abbahagyta'::text,'abbahagyja'::text,'Mire felállt, a világító spirálja már abbahagyta a szikrázást. Nem ideális.'::text),
(390000,43334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Wellen wieder blau. Ein eher mittelmäßiger Strand.'::text,'funkeln'::text,'funkeln'::text,'funkeln'::text,'Morgen um diese Zeit funkeln die Wellen wieder blau. Ein eher mittelmäßiger Strand.'::text),
(390004,43334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час хвилі знову ... синім. Такий собі посередній пляж.'::text,'виблискуватимуть'::text,'заблищать'::text,'блищать'::text,'Завтра в цей час хвилі знову виблискуватимуть синім. Такий собі посередній пляж.'::text),
(390003,43334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, las olas ... de azul otra vez. Una playa ligeramente normalita.'::text,'estarán brillando'::text,'brillarán'::text,'brillan'::text,'Mañana a esta hora, las olas estarán brillando de azul otra vez. Una playa ligeramente normalita.'::text),
(390002,43334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, les vagues ... de nouveau en bleu. Une plage vaguement banale.'::text,'seront en train de scintiller'::text,'scintilleront'::text,'scintillent'::text,'Demain à cette heure-ci, les vagues seront en train de scintiller de nouveau en bleu. Une plage vaguement banale.'::text),
(390005,43334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde dalgalar yine mavi ...; hafif sıradan bir plaj işte.'::text,'parlıyor olacak'::text,'parlayacak'::text,'parlar'::text,'Yarın bu saatlerde dalgalar yine mavi parlıyor olacak; hafif sıradan bir plaj işte.'::text),
(390006,43334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a hullámok újra ... kéken. Egy enyhén átlagos strand.'::text,'szikrázni fognak'::text,'szikrázni fognak'::text,'szikráznak'::text,'Holnap ilyenkor a hullámok újra szikrázni fognak kéken. Egy enyhén átlagos strand.'::text),
(390009,43335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche dir, der Sand ..., sobald du ihn berührst. Eindeutig ein sehr langweiliger Strand.'::text,'wird funkeln'::text,'wird gerade funkeln'::text,'funkelt gerade'::text,'Ich verspreche dir, der Sand wird funkeln, sobald du ihn berührst. Eindeutig ein sehr langweiliger Strand.'::text),
(390013,43335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, пісок ..., щойно ти до нього торкнешся. Явно дуже нудний пляж.'::text,'заблищить'::text,'виблискуватиме'::text,'виблискує'::text,'Обіцяю, пісок заблищить, щойно ти до нього торкнешся. Явно дуже нудний пляж.'::text),
(390012,43335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te prometo que la arena ... en cuanto la toques. Claramente una playa aburridísima.'::text,'brillará'::text,'estará brillando'::text,'está brillando'::text,'Te prometo que la arena brillará en cuanto la toques. Claramente una playa aburridísima.'::text),
(390011,43335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je te promets que le sable ... dès que tu le toucheras. Clairement une plage très ennuyeuse.'::text,'scintillera'::text,'sera en train de scintiller'::text,'est en train de scintiller'::text,'Je te promets que le sable scintillera dès que tu le toucheras. Clairement une plage très ennuyeuse.'::text),
(390014,43335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, kum dokunduğun an ...; belli ki çok sıkıcı bir plaj.'::text,'parlayacak'::text,'parlıyor olacak'::text,'parlıyor'::text,'Söz veriyorum, kum dokunduğun an parlayacak; belli ki çok sıkıcı bir plaj.'::text),
(390015,43335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ígérem, a homok ..., amint hozzáérsz. Egyértelműen nagyon unalmas strand.'::text,'szikrázni fog'::text,'szikrázni fog'::text,'szikrázik'::text,'Ígérem, a homok szikrázni fog, amint hozzáérsz. Egyértelműen nagyon unalmas strand.'::text),
(390018,43336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn nachts irgendetwas diesen Sand berührt, ... er buchstäblich wie tausend Sterne!'::text,'funkelt'::text,'funkelt'::text,'funkelte'::text,'Wenn nachts irgendetwas diesen Sand berührt, funkelt er buchstäblich wie tausend Sterne!'::text),
(390022,43336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо щось торкнеться цього піску вночі, він буквально ... як тисяча зірок!'::text,'виблискує'::text,'заблищить'::text,'виблискував'::text,'Якщо щось торкнеться цього піску вночі, він буквально виблискує як тисяча зірок!'::text),
(390021,43336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si algo toca esta arena de noche, literalmente ... como mil estrellas!'::text,'brilla'::text,'brillará'::text,'brilló'::text,'¡Si algo toca esta arena de noche, literalmente brilla como mil estrellas!'::text),
(390020,43336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelque chose touche ce sable la nuit, il ... littéralement comme mille étoiles !'::text,'scintille'::text,'scintillera'::text,'scintillait'::text,'Si quelque chose touche ce sable la nuit, il scintille littéralement comme mille étoiles !'::text),
(390023,43336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece bu kuma bir şey dokunursa, resmen bin yıldız gibi ...!'::text,'parlar'::text,'parlayacak'::text,'parladı'::text,'Gece bu kuma bir şey dokunursa, resmen bin yıldız gibi parlar!'::text),
(390024,43336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha éjjel bármi hozzáér ehhez a homokhoz, szó szerint ..., mint ezer csillag!'::text,'szikrázik'::text,'szikrázni fog'::text,'szikrázott'::text,'Ha éjjel bármi hozzáér ehhez a homokhoz, szó szerint szikrázik, mint ezer csillag!'::text),
(390027,43337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Welle ans Ufer schlägt, ... der ganze Strand blau! Absolut unglaublich!'::text,'funkelt'::text,'funkelte'::text,'funkelte'::text,'Wenn die Welle ans Ufer schlägt, funkelt der ganze Strand blau! Absolut unglaublich!'::text),
(390031,43337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хвиля вдарить об берег, увесь пляж ... синім! Абсолютно неймовірно!'::text,'заблищить'::text,'заблищав би'::text,'заблищав'::text,'Якщо хвиля вдарить об берег, увесь пляж заблищить синім! Абсолютно неймовірно!'::text),
(390030,43337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la ola golpea la orilla, toda la playa ... de azul! ¡Absolutamente increíble!'::text,'brillará'::text,'brillaría'::text,'brilló'::text,'¡Si la ola golpea la orilla, toda la playa brillará de azul! ¡Absolutamente increíble!'::text),
(390029,43337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la vague touche le rivage, toute la plage ... en bleu ! Absolument incroyable !'::text,'scintillera'::text,'scintillerait'::text,'a scintillé'::text,'Si la vague touche le rivage, toute la plage scintillera en bleu ! Absolument incroyable !'::text),
(390032,43337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalga kıyıya vurursa, bütün plaj mavi ...! İnanılmaz ötesi!'::text,'parlayacak'::text,'parlardı'::text,'parladı'::text,'Dalga kıyıya vurursa, bütün plaj mavi parlayacak! İnanılmaz ötesi!'::text),
(390033,43337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hullám partot ér, az egész strand kéken ...! Teljesen hihetetlen!'::text,'fog szikrázni'::text,'szikrázna'::text,'szikrázott'::text,'Ha a hullám partot ér, az egész strand kéken fog szikrázni! Teljesen hihetetlen!'::text),
(390036,43338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Strand jede Nacht so funkeln würde, ... sie jeden Abend her.'::text,'käme'::text,'kommt'::text,'kommt'::text,'Wenn der Strand jede Nacht so funkeln würde, käme sie jeden Abend her.'::text),
(390040,43338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пляж так виблискував щоночі, вона ... сюди щовечора.'::text,'приходила б'::text,'прийде'::text,'приходить'::text,'Якби пляж так виблискував щоночі, вона приходила б сюди щовечора.'::text),
(390039,43338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la playa brillara así cada noche, ... aquí todas las tardes.'::text,'vendría'::text,'vendrá'::text,'viene'::text,'Si la playa brillara así cada noche, vendría aquí todas las tardes.'::text),
(390038,43338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la plage scintillait comme ça chaque nuit, elle ... ici tous les soirs.'::text,'viendrait'::text,'viendra'::text,'vient'::text,'Si la plage scintillait comme ça chaque nuit, elle viendrait ici tous les soirs.'::text),
(390041,43338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plaj her gece böyle parıldasa, her akşam buraya ...'::text,'gelirdi'::text,'gelecek'::text,'geliyor'::text,'Plaj her gece böyle parıldasa, her akşam buraya gelirdi.'::text),
(390042,43338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a strand minden éjjel így szikrázna, minden este ... ide.'::text,'eljönne'::text,'el fog jönni'::text,'eljön'::text,'Ha a strand minden éjjel így szikrázna, minden este eljönne ide.'::text),
(332184,36910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat sie dem Assistenten versprochen, dass sie ihre Macht klug ...'::text,'einsetzen wird'::text,'einsetzen wird'::text,'gerade einsetzt'::text,'Hör zu, angeblich hat sie dem Assistenten versprochen, dass sie ihre Macht klug einsetzen wird.'::text),
(332188,36910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона пообіцяла помічникові, що ... свою владу мудро.'::text,'використає'::text,'використовуватиме'::text,'використовує'::text,'Слухай, кажуть, вона пообіцяла помічникові, що використає свою владу мудро.'::text),
(332187,36910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, parece que le prometió al asistente que ... su autoridad con cabeza.'::text,'usará'::text,'estará usando'::text,'está usando'::text,'Escucha, parece que le prometió al asistente que usará su autoridad con cabeza.'::text),
(332186,36910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle a promis à l''assistant qu''elle ... son autorité avec sagesse.'::text,'utilisera'::text,'sera en train d''utiliser'::text,'utilise'::text,'Écoute, apparemment elle a promis à l''assistant qu''elle utilisera son autorité avec sagesse.'::text),
(332189,36910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya yardımcısına yetkisini akıllıca ... söz vermiş.'::text,'kullanacağına'::text,'kullanıyor olacağına'::text,'kullandığına'::text,'Dinle, güya yardımcısına yetkisini akıllıca kullanacağına söz vermiş.'::text),
(332190,36910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag megígérte a segédjének, hogy bölcsen ... a hatalmával.'::text,'fog élni'::text,'élni fog'::text,'él'::text,'Figyelj, állítólag megígérte a segédjének, hogy bölcsen fog élni a hatalmával.'::text),
(332202,36912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich jetzt, du gibst Befehle mit echter Autorität, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Ehrlich jetzt, du gibst Befehle mit echter Autorität, oder?'::text),
(332206,36912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти віддаєш накази зі справжньою владою, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Не буду брехати, ти віддаєш накази зі справжньою владою, правда?'::text),
(332205,36912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, das órdenes con auténtica autoridad, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'No te voy a mentir, das órdenes con auténtica autoridad, ¿verdad?'::text),
(332204,36912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu donnes des ordres avec une vraie autorité, ... ?'::text,'non'::text,'non'::text,'non'::text,'Sans mentir, tu donnes des ordres avec une vraie autorité, non ?'::text),
(332207,36912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, gerçek bir yetkiyle emir veriyorsun, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Yalan yok, gerçek bir yetkiyle emir veriyorsun, değil mi?'::text),
(332208,36912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, igazi hatalommal adsz parancsokat, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nem fogok hazudni, igazi hatalommal adsz parancsokat, ugye?'::text),
(332211,36913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat hier die totale Macht, und ... ihr Stempel. Eindeutig.'::text,'genauso'::text,'genauso'::text,'genauso wenig'::text,'Sie hat hier die totale Macht, und genauso ihr Stempel. Eindeutig.'::text),
(332215,36913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона має тут повну владу, і ... її печатка. Очевидно.'::text,'так само й'::text,'так само й'::text,'ані'::text,'Вона має тут повну владу, і так само й її печатка. Очевидно.'::text),
(332214,36913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella tiene autoridad total aquí, y ... su sello de goma. Claramente.'::text,'también'::text,'también'::text,'tampoco'::text,'Ella tiene autoridad total aquí, y también su sello de goma. Claramente.'::text),
(332213,36913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a une autorité totale ici, ... son tampon. Évidemment.'::text,'tout comme'::text,'tout comme'::text,'pas plus que'::text,'Elle a une autorité totale ici, tout comme son tampon. Évidemment.'::text),
(332216,36913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun burada tam yetkisi var, lastik damgasının ... var. Belli.'::text,'da'::text,'da'::text,'da'::text,'Onun burada tam yetkisi var, lastik damgasının da var. Belli.'::text),
(332217,36913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki itt teljes hatalma van, és ... a gumibélyegzőjének. Egyértelmű.'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy nem'::text,'Neki itt teljes hatalma van, és ugyanígy a gumibélyegzőjének. Egyértelmű.'::text),
(332220,36914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird sie ihre Autorität auf 50 weitere Dokumente ... – eindeutig ein entspannter Tag.'::text,'gestempelt haben'::text,'stempeln'::text,'stempeln'::text,'Bis Mittag wird sie ihre Autorität auf 50 weitere Dokumente gestempelt haben – eindeutig ein entspannter Tag.'::text),
(332224,36914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду вона ... ще 50 документів своєю владою. Явно розслаблений день.'::text,'проштампує'::text,'проштампує'::text,'штампуватиме'::text,'До обіду вона проштампує ще 50 документів своєю владою. Явно розслаблений день.'::text),
(332223,36914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, ... su autoridad en 50 documentos más. Claramente un día relajado.'::text,'habrá sellado'::text,'sellará'::text,'estará sellando'::text,'Para la hora de comer, habrá sellado su autoridad en 50 documentos más. Claramente un día relajado.'::text),
(332222,36914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le déjeuner, elle ... son autorité sur 50 documents de plus. Clairement une journée tranquille.'::text,'aura tamponné'::text,'tamponnera'::text,'sera en train de tamponner'::text,'D''ici le déjeuner, elle aura tamponné son autorité sur 50 documents de plus. Clairement une journée tranquille.'::text),
(332225,36914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar yetkisiyle 50 belgeyi daha ...; belli ki pek rahat bir gün.'::text,'damgalamış olacak'::text,'damgalayacak'::text,'damgalıyor olacak'::text,'Öğlene kadar yetkisiyle 50 belgeyi daha damgalamış olacak; belli ki pek rahat bir gün.'::text),
(332226,36914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédig még 50 dokumentumra ... a hatalmát. Egyértelműen laza nap.'::text,'rápecsételi'::text,'rá fogja pecsételni'::text,'pecsételni fogja'::text,'Ebédig még 50 dokumentumra rápecsételi a hatalmát. Egyértelműen laza nap.'::text),
(332229,36915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn sie die Befugnis nicht gehabt hätte, ... sie das Dokument nicht abgestempelt, echt jetzt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Bro, wenn sie die Befugnis nicht gehabt hätte, hätte sie das Dokument nicht abgestempelt, echt jetzt.'::text),
(332233,36915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби в неї не було повноважень, вона ... той документ, реально.'::text,'не проштампувала б'::text,'не проштампує'::text,'не проштампувала'::text,'Бро, якби в неї не було повноважень, вона не проштампувала б той документ, реально.'::text),
(332232,36915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si no hubiera tenido la autoridad, ... ese documento, en serio.'::text,'no habría sellado'::text,'no sellará'::text,'no selló'::text,'Tío, si no hubiera tenido la autoridad, no habría sellado ese documento, en serio.'::text),
(332231,36915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si elle n''avait pas eu l''autorité, elle ... ce doc, sérieux.'::text,'n''aurait pas tamponné'::text,'ne tamponnera pas'::text,'n''a pas tamponné'::text,'Frère, si elle n''avait pas eu l''autorité, elle n''aurait pas tamponné ce doc, sérieux.'::text),
(332234,36915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yetkisi olmasaydı o belgeyi ..., cidden.'::text,'damgalamazdı'::text,'damgalamayacak'::text,'damgalamadı'::text,'Kanka, o yetkisi olmasaydı o belgeyi damgalamazdı, cidden.'::text),
(332235,36915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem lett volna meg a jogköre, ... azt a papírt, komolyan.'::text,'nem pecsételte volna le'::text,'nem fogja lepecsételni'::text,'nem pecsételte le'::text,'Tesó, ha nem lett volna meg a jogköre, nem pecsételte volna le azt a papírt, komolyan.'::text),
(332247,36917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Befugnis gehabt haben, das Dokument zu stempeln, sonst hätte der Assistent sie aufgehalten.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie muss die Befugnis gehabt haben, das Dokument zu stempeln, sonst hätte der Assistent sie aufgehalten.'::text),
(332251,36917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї ... повноваження проштампувати той документ, інакше помічник би її зупинив.'::text,'напевно, були'::text,'не могли бути'::text,'мали б бути'::text,'У неї напевно, були повноваження проштампувати той документ, інакше помічник би її зупинив.'::text),
(332250,36917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... tenido la autoridad para sellar ese documento, o el asistente la habría detenido.'::text,'debe de haber'::text,'no puede haber'::text,'debería haber'::text,'Ella debe de haber tenido la autoridad para sellar ese documento, o el asistente la habría detenido.'::text),
(332249,36917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''autorité de tamponner ce document, sinon l''assistant l''aurait arrêtée.'::text,'a dû avoir'::text,'n''a pas pu avoir'::text,'aurait dû avoir'::text,'Elle a dû avoir l''autorité de tamponner ce document, sinon l''assistant l''aurait arrêtée.'::text),
(332252,36917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O belgeyi damgalama yetkisi ..., yoksa yardımcısı onu durdururdu.'::text,'olmalı'::text,'olamaz'::text,'olmalıydı'::text,'O belgeyi damgalama yetkisi olmalı, yoksa yardımcısı onu durdururdu.'::text),
(332253,36917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... jogköre lepecsételni azt a dokumentumot, különben a segédje megállította volna.'::text,'biztosan volt'::text,'nem lehetett'::text,'lennie kellett volna'::text,'Neki biztosan volt jogköre lepecsételni azt a dokumentumot, különben a segédje megállította volna.'::text),
(332256,36918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit ihrer Befugnis lässt sie ihren Assistenten Pins auf der Karte ...'::text,'platzieren'::text,'zu platzieren'::text,'platziert'::text,'Mit ihrer Befugnis lässt sie ihren Assistenten Pins auf der Karte platzieren.'::text),
(332260,36918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Користуючись своєю владою, вона змушує помічника ... шпильки на мапі.'::text,'розставляти'::text,'розставляти'::text,'розставлені'::text,'Користуючись своєю владою, вона змушує помічника розставляти шпильки на мапі.'::text),
(332259,36918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Usando su autoridad, hace que su asistente ... chinchetas en el mapa.'::text,'ponga'::text,'poner'::text,'puesto'::text,'Usando su autoridad, hace que su asistente ponga chinchetas en el mapa.'::text),
(332258,36918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Usant de son autorité, elle fait ... des épingles sur la carte à son assistant.'::text,'placer'::text,'de placer'::text,'placé'::text,'Usant de son autorité, elle fait placer des épingles sur la carte à son assistant.'::text),
(332261,36918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetkisini kullanarak yardımcısına haritaya raptiyeler ...'::text,'taktırıyor'::text,'takmayı'::text,'takılmış'::text,'Yetkisini kullanarak yardımcısına haritaya raptiyeler taktırıyor.'::text),
(332262,36918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hatalmával élve a segédjével ... a gombostűket a térképre.'::text,'tűzeti fel'::text,'feltűzni'::text,'feltűzött'::text,'A hatalmával élve a segédjével tűzeti fel a gombostűket a térképre.'::text),
(332265,36919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Assistent wünscht sich, er ... ihre Befugnis, Dokumente zu unterschreiben.'::text,'hätte'::text,'würde haben'::text,'hat'::text,'Der Assistent wünscht sich, er hätte ihre Befugnis, Dokumente zu unterschreiben.'::text),
(332269,36919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помічник хотів би, щоб у нього ... її повноваження підписувати документи.'::text,'були'::text,'були б'::text,'є'::text,'Помічник хотів би, щоб у нього були її повноваження підписувати документи.'::text),
(332268,36919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El asistente desea ... su autoridad para firmar documentos.'::text,'tener'::text,'tener'::text,'tiene'::text,'El asistente desea tener su autoridad para firmar documentos.'::text),
(332267,36919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''assistant aimerait ... son autorité pour signer des documents.'::text,'avoir'::text,'avoir'::text,'a'::text,'L''assistant aimerait avoir son autorité pour signer des documents.'::text),
(332270,36919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yardımcı, keşke belge imzalamak için onun yetkisine ... diye düşünüyor.'::text,'sahip olsa'::text,'sahip olsa'::text,'sahip'::text,'Yardımcı, keşke belge imzalamak için onun yetkisine sahip olsa diye düşünüyor.'::text),
(332271,36919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A segéd azt szeretné, ha ... neki a nő jogköre a dokumentumok aláírásához.'::text,'meglenne'::text,'meglenne'::text,'megvan'::text,'A segéd azt szeretné, ha meglenne neki a nő jogköre a dokumentumok aláírásához.'::text),
(332274,36920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat die Frau, ... Büro diese riesige Karte hat, hier die ganze Macht.'::text,'deren'::text,'die'::text,'welche'::text,'Mädel, angeblich hat die Frau, deren Büro diese riesige Karte hat, hier die ganze Macht.'::text),
(332278,36920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, жінка, ... кабінеті висить та величезна мапа, має тут усю владу.'::text,'у чиєму'::text,'яка'::text,'що'::text,'Подруго, кажуть, жінка, у чиєму кабінеті висить та величезна мапа, має тут усю владу.'::text),
(332277,36920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que la mujer ... despacho tiene ese mapa enorme tiene aquí toda la autoridad.'::text,'cuyo'::text,'que'::text,'la cual'::text,'Tía, parece que la mujer cuyo despacho tiene ese mapa enorme tiene aquí toda la autoridad.'::text),
(332276,36920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la femme ... le bureau a cette carte géante a toute l''autorité ici.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Meuf, apparemment la femme dont le bureau a cette carte géante a toute l''autorité ici.'::text),
(332279,36920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ofisinde o dev harita ... kadın buradaki bütün yetkiye sahip.'::text,'olan'::text,'olan'::text,'olan'::text,'Kızım, güya ofisinde o dev harita olan kadın buradaki bütün yetkiye sahip.'::text),
(332280,36920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a nő, ... irodájában az a hatalmas térkép van, itt minden hatalom az övé.'::text,'akinek az'::text,'aki'::text,'amelyik'::text,'Csajszi, állítólag az a nő, akinek az irodájában az a hatalmas térkép van, itt minden hatalom az övé.'::text),
(374673,41631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kind ... eine junge Blume, als eine erwachsene Hand das Exemplar stabilisierte.'::text,'pflanzte gerade'::text,'pflanzte'::text,'hat gepflanzt'::text,'Das Kind pflanzte gerade eine junge Blume, als eine erwachsene Hand das Exemplar stabilisierte.'::text),
(374677,41631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дитина ... молоду квітку, коли доросла рука підтримала екземпляр.'::text,'садила'::text,'посадила'::text,'посадила'::text,'Дитина садила молоду квітку, коли доросла рука підтримала екземпляр.'::text),
(374676,41631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El niño ... una flor joven cuando una mano adulta estabilizó el espécimen.'::text,'estaba plantando'::text,'plantó'::text,'ha plantado'::text,'El niño estaba plantando una flor joven cuando una mano adulta estabilizó el espécimen.'::text),
(374675,41631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''enfant ... une jeune fleur quand une main adulte a stabilisé le spécimen.'::text,'plantait'::text,'a planté'::text,'a planté'::text,'L''enfant plantait une jeune fleur quand une main adulte a stabilisé le spécimen.'::text),
(374678,41631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin bir el örneği sabitlediğinde çocuk genç bir çiçek ...'::text,'dikiyordu'::text,'dikti'::text,'dikmiş'::text,'Yetişkin bir el örneği sabitlediğinde çocuk genç bir çiçek dikiyordu.'::text),
(374679,41631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyerek éppen egy fiatal virágot ..., amikor egy felnőtt kéz megtartotta a példányt.'::text,'ültetett'::text,'elültetett'::text,'elültetett'::text,'A gyerek éppen egy fiatal virágot ültetett, amikor egy felnőtt kéz megtartotta a példányt.'::text),
(374682,41632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Familie ... seit dem Frühstück Blumen, und ihre Knie sind total im Eimer!'::text,'pflanzt'::text,'pflanzt'::text,'pflanzt'::text,'Die ganze Familie pflanzt seit dem Frühstück Blumen, und ihre Knie sind total im Eimer!'::text),
(374686,41632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся родина ... квіти від самого сніданку, і їхні коліна повністю вбиті!'::text,'садить'::text,'садить'::text,'садить'::text,'Уся родина садить квіти від самого сніданку, і їхні коліна повністю вбиті!'::text),
(374685,41632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la familia ... flores desde el desayuno y sus rodillas están totalmente destrozadas!'::text,'lleva plantando'::text,'está plantando'::text,'planta'::text,'¡Toda la familia lleva plantando flores desde el desayuno y sus rodillas están totalmente destrozadas!'::text),
(374684,41632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la famille ... des fleurs depuis le petit-déj, et leurs genoux sont complètement détruits !'::text,'plante'::text,'plante'::text,'plante'::text,'Toute la famille plante des fleurs depuis le petit-déj, et leurs genoux sont complètement détruits !'::text),
(374687,41632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün aile kahvaltıdan beri çiçek ... ve dizleri tamamen mahvoldu!'::text,'dikiyor'::text,'dikiyor'::text,'diker'::text,'Bütün aile kahvaltıdan beri çiçek dikiyor ve dizleri tamamen mahvoldu!'::text),
(374688,41632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész család reggeli óta virágokat ..., és a térdük teljesen tönkrement!'::text,'ültet'::text,'ültet'::text,'ültet'::text,'Az egész család reggeli óta virágokat ültet, és a térdük teljesen tönkrement!'::text),
(374691,41633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Während Opa die Rosen ..., hat sich das kleine Mädchen fast ins Teeservice gedreht!'::text,'pflanzte'::text,'pflanzte'::text,'gepflanzt hat'::text,'Katastrophe! Während Opa die Rosen pflanzte, hat sich das kleine Mädchen fast ins Teeservice gedreht!'::text),
(374695,41633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Поки дідусь ... троянди, маленька дівчинка мало не закружляла прямо в чайний сервіз!'::text,'садив'::text,'посадив'::text,'посадив'::text,'Катастрофа! Поки дідусь садив троянди, маленька дівчинка мало не закружляла прямо в чайний сервіз!'::text),
(374694,41633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Mientras el abuelo ... las rosas, la niña casi se estrella girando contra el juego de té!'::text,'estaba plantando'::text,'plantó'::text,'ha plantado'::text,'¡Desastre! ¡Mientras el abuelo estaba plantando las rosas, la niña casi se estrella girando contra el juego de té!'::text),
(374693,41633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Pendant que papi ... les roses, la petite a failli tourbillonner dans le service à thé !'::text,'plantait'::text,'a planté'::text,'a planté'::text,'Catastrophe ! Pendant que papi plantait les roses, la petite a failli tourbillonner dans le service à thé !'::text),
(374696,41633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Dede gülleri ..., küçük kız dönerken az kalsın çay takımına dalıyordu!'::text,'dikerken'::text,'diktiğinde'::text,'dikmişken'::text,'Felaket! Dede gülleri dikerken, küçük kız dönerken az kalsın çay takımına dalıyordu!'::text),
(374697,41633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Miközben nagypapa a rózsákat ..., a kislány majdnem beleforgott a teáskészletbe!'::text,'ültette'::text,'elültette'::text,'elültette'::text,'Katasztrófa! Miközben nagypapa a rózsákat ültette, a kislány majdnem beleforgott a teáskészletbe!'::text),
(374709,41635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie die Blumen pflanzten, ... sich das Mädchen im Wohnzimmer immer wieder im Kreis gedreht.'::text,'hatte'::text,'hat'::text,'dreht'::text,'Bevor sie die Blumen pflanzten, hatte sich das Mädchen im Wohnzimmer immer wieder im Kreis gedreht.'::text),
(374713,41635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж вони посадили квіти, дівчинка ... по колу у вітальні.'::text,'кружляла'::text,'кружляла'::text,'кружляє'::text,'Перш ніж вони посадили квіти, дівчинка кружляла по колу у вітальні.'::text),
(374712,41635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de plantar las flores, la niña ... vueltas y vueltas en el salón.'::text,'había dado'::text,'ha dado'::text,'da'::text,'Antes de plantar las flores, la niña había dado vueltas y vueltas en el salón.'::text),
(374711,41635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''ils plantent les fleurs, la petite ... sur elle-même dans le salon.'::text,'avait tourné'::text,'a tourné'::text,'tourne'::text,'Avant qu''ils plantent les fleurs, la petite avait tourné sur elle-même dans le salon.'::text),
(374714,41635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekleri dikmeden önce kız oturma odasında fırıl fırıl ...'::text,'dönmüştü'::text,'döndü'::text,'dönüyor'::text,'Çiçekleri dikmeden önce kız oturma odasında fırıl fırıl dönmüştü.'::text),
(374715,41635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt elültették a virágokat, a kislány körbe-körbe ... a nappaliban.'::text,'forgott'::text,'forgott'::text,'forog'::text,'Mielőtt elültették a virágokat, a kislány körbe-körbe forgott a nappaliban.'::text),
(374718,41636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Blumen heute pflanzen, ... das Beet bis zum Sommer bunt.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie die Blumen heute pflanzen, ist das Beet bis zum Sommer bunt.'::text),
(374722,41636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони посадять квіти сьогодні, клумба до літа ... барвистою.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вони посадять квіти сьогодні, клумба до літа буде барвистою.'::text),
(374721,41636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si plantan las flores hoy, el parterre ... lleno de color para el verano.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si plantan las flores hoy, el parterre estará lleno de color para el verano.'::text),
(374720,41636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils plantent les fleurs aujourd''hui, le massif ... coloré d''ici l''été.'::text,'sera'::text,'serait'::text,'était'::text,'S''ils plantent les fleurs aujourd''hui, le massif sera coloré d''ici l''été.'::text),
(374723,41636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekleri bugün dikerlerse, tarh yaza kadar rengârenk ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Çiçekleri bugün dikerlerse, tarh yaza kadar rengârenk olacak.'::text),
(374724,41636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma elültetik a virágokat, az ágyás nyárra színes ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha ma elültetik a virágokat, az ágyás nyárra színes lesz.'::text),
(374727,41637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie pflanzten die Blumen ... des heißen Wetters.'::text,'trotz'::text,'obwohl'::text,'außer wenn'::text,'Sie pflanzten die Blumen trotz des heißen Wetters.'::text),
(374731,41637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони посадили квіти ... спеку.'::text,'попри'::text,'хоча'::text,'якщо не'::text,'Вони посадили квіти попри спеку.'::text),
(374730,41637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plantaron las flores ... el calor.'::text,'a pesar de'::text,'aunque'::text,'a menos que'::text,'Plantaron las flores a pesar de el calor.'::text),
(374729,41637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont planté les fleurs ... la chaleur.'::text,'malgré'::text,'bien que'::text,'à moins que'::text,'Ils ont planté les fleurs malgré la chaleur.'::text),
(374732,41637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak havaya ... çiçekleri diktiler.'::text,'rağmen'::text,'olsa da'::text,'olmadıkça'::text,'Sıcak havaya rağmen çiçekleri diktiler.'::text),
(374733,41637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hőség ... elültették a virágokat.'::text,'ellenére'::text,'bár'::text,'hacsak nem'::text,'A hőség ellenére elültették a virágokat.'::text),
(374736,41638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, das Mädchen wusste, dass sie an dem Tag ihre eigene Blume ..., sie war so gehypt.'::text,'pflanzen würde'::text,'pflanzen wird'::text,'pflanzt'::text,'Alter, das Mädchen wusste, dass sie an dem Tag ihre eigene Blume pflanzen würde, sie war so gehypt.'::text),
(374740,41638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, дівчинка знала, що того дня ... власну квітку, вона була вся на емоціях.'::text,'посадить'::text,'посадить'::text,'садить'::text,'Бро, дівчинка знала, що того дня посадить власну квітку, вона була вся на емоціях.'::text),
(374739,41638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la niña sabía que ese día ... su propia flor, estaba superemocionada.'::text,'plantaría'::text,'plantará'::text,'planta'::text,'Tío, la niña sabía que ese día plantaría su propia flor, estaba superemocionada.'::text),
(374738,41638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la petite savait qu''elle ... sa propre fleur ce jour-là, elle était trop hypée.'::text,'planterait'::text,'plantera'::text,'plante'::text,'Frérot, la petite savait qu''elle planterait sa propre fleur ce jour-là, elle était trop hypée.'::text),
(374741,41638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kız o gün kendi çiçeğini ... biliyordu, çok gazlıydı.'::text,'dikeceğini'::text,'dikeceğini'::text,'diktiğini'::text,'Kanka, kız o gün kendi çiçeğini dikeceğini biliyordu, çok gazlıydı.'::text),
(374742,41638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kislány tudta, hogy aznap ... a saját virágát, nagyon be volt pörögve.'::text,'elülteti'::text,'el fogja ültetni'::text,'ülteti'::text,'Tesó, a kislány tudta, hogy aznap elülteti a saját virágát, nagyon be volt pörögve.'::text),
(374754,41640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... die Familie jede Pflanze im Beet gepflanzt, deutlich vor dem Ziel.'::text,'hatte'::text,'hat'::text,'pflanzte'::text,'Bis Mittag hatte die Familie jede Pflanze im Beet gepflanzt, deutlich vor dem Ziel.'::text),
(374758,41640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня родина ... кожну рослину на клумбі, значно випередивши план.'::text,'посадила'::text,'посадила'::text,'садила'::text,'До полудня родина посадила кожну рослину на клумбі, значно випередивши план.'::text),
(374757,41640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, la familia ... todas las plantas del parterre, muy por delante del objetivo.'::text,'había plantado'::text,'ha plantado'::text,'estaba plantando'::text,'Para el mediodía, la familia había plantado todas las plantas del parterre, muy por delante del objetivo.'::text),
(374756,41640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, la famille ... chaque plante du massif, bien avant l''objectif.'::text,'avait planté'::text,'a planté'::text,'plantait'::text,'À midi, la famille avait planté chaque plante du massif, bien avant l''objectif.'::text),
(374759,41640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar aile tarhtaki her bitkiyi ..., hedefin çok önünde.'::text,'dikmişti'::text,'dikti'::text,'dikiyordu'::text,'Öğlene kadar aile tarhtaki her bitkiyi dikmişti, hedefin çok önünde.'::text),
(374760,41640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a család ... az ágyás minden növényét, jóval a cél előtt.'::text,'elültette'::text,'elültette'::text,'ültette'::text,'Délre a család elültette az ágyás minden növényét, jóval a cél előtt.'::text),
(374763,41641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächsten Frühling um diese Zeit ... das Mädchen wieder Blumen in diesem Garten.'::text,'pflanzt'::text,'pflanzt'::text,'pflanzt'::text,'Nächsten Frühling um diese Zeit pflanzt das Mädchen wieder Blumen in diesem Garten.'::text),
(374767,41641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступної весни в цей час дівчинка знову ... квіти в цьому саду.'::text,'садитиме'::text,'посадить'::text,'садить'::text,'Наступної весни в цей час дівчинка знову садитиме квіти в цьому саду.'::text),
(374766,41641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La próxima primavera a esta hora, la niña ... flores en este jardín otra vez.'::text,'estará plantando'::text,'plantará'::text,'planta'::text,'La próxima primavera a esta hora, la niña estará plantando flores en este jardín otra vez.'::text),
(374765,41641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au printemps prochain à la même époque, la petite ... des fleurs dans ce jardin, encore une fois.'::text,'sera en train de planter'::text,'plantera'::text,'plante'::text,'Au printemps prochain à la même époque, la petite sera en train de planter des fleurs dans ce jardin, encore une fois.'::text),
(374768,41641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek bahar bu zamanlar kız yine bu bahçede çiçek ...'::text,'dikiyor olacak'::text,'dikecek'::text,'diker'::text,'Gelecek bahar bu zamanlar kız yine bu bahçede çiçek dikiyor olacak.'::text),
(374769,41641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő tavasszal ilyenkor a kislány újra virágokat ... ebben a kertben.'::text,'ültetni fog'::text,'el fog ültetni'::text,'ültet'::text,'Jövő tavasszal ilyenkor a kislány újra virágokat ültetni fog ebben a kertben.'::text),
(383214,42580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Endlich! Nach einer Woche absoluten Chaos ... das Dach des Vogelhäuschens glatt geschliffen!'::text,'wurde'::text,'wird'::text,'schliff'::text,'Endlich! Nach einer Woche absoluten Chaos wurde das Dach des Vogelhäuschens glatt geschliffen!'::text),
(383218,42580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нарешті! Після тижня повного хаосу дах шпаківні ... до гладкості!'::text,'було відшліфовано'::text,'шліфується'::text,'відшліфував'::text,'Нарешті! Після тижня повного хаосу дах шпаківні було відшліфовано до гладкості!'::text),
(383217,42580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Por fin! ¡Tras una semana de caos absoluto, el tejado de la casita para pájaros ... hasta quedar liso!'::text,'fue lijado'::text,'es lijado'::text,'lijó'::text,'¡Por fin! ¡Tras una semana de caos absoluto, el tejado de la casita para pájaros fue lijado hasta quedar liso!'::text),
(383216,42580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfin ! Après une semaine de chaos absolu, le toit du nichoir ... bien lisse !'::text,'a été poncé'::text,'est poncé'::text,'a poncé'::text,'Enfin ! Après une semaine de chaos absolu, le toit du nichoir a été poncé bien lisse !'::text),
(383219,42580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda! Tam bir haftalık kaosun ardından kuş evinin çatısı pürüzsüz ...!'::text,'zımparalandı'::text,'zımparalanıyor'::text,'zımparaladı'::text,'Sonunda! Tam bir haftalık kaosun ardından kuş evinin çatısı pürüzsüz zımparalandı!'::text),
(383220,42580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Végre! Egy hétnyi totális káosz után a madárház teteje simára ...!'::text,'lett csiszolva'::text,'van csiszolva'::text,'csiszolt'::text,'Végre! Egy hétnyi totális káosz után a madárház teteje simára lett csiszolva!'::text),
(383223,42581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Dach buchstäblich so lange, dass die Kinder dachten, es hört nie auf!'::text,'schliff'::text,'wurde geschliffen'::text,'schleifend'::text,'Er schliff das Dach buchstäblich so lange, dass die Kinder dachten, es hört nie auf!'::text),
(383227,42581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він буквально ... той дах так довго, що діти думали, це ніколи не закінчиться!'::text,'шліфував'::text,'був відшліфований'::text,'шліфуючи'::text,'Він буквально шліфував той дах так довго, що діти думали, це ніколи не закінчиться!'::text),
(383226,42581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Literalmente ... ese tejado tanto tiempo que los niños pensaron que nunca acabaría!'::text,'lijó'::text,'fue lijado'::text,'lijando'::text,'¡Literalmente lijó ese tejado tanto tiempo que los niños pensaron que nunca acabaría!'::text),
(383225,42581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... littéralement ce toit si longtemps que les enfants ont cru que ça ne finirait jamais !'::text,'a poncé'::text,'a été poncé'::text,'ponçant'::text,'Il a poncé littéralement ce toit si longtemps que les enfants ont cru que ça ne finirait jamais !'::text),
(383228,42581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çatıyı resmen o kadar uzun süre ... ki çocuklar hiç bitmeyecek sandı!'::text,'zımparaladı'::text,'zımparalandı'::text,'zımparalayarak'::text,'O çatıyı resmen o kadar uzun süre zımparaladı ki çocuklar hiç bitmeyecek sandı!'::text),
(383229,42581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szó szerint olyan sokáig ... azt a tetőt, hogy a gyerekek azt hitték, sosem lesz vége!'::text,'csiszolta'::text,'csiszolva lett'::text,'csiszolva'::text,'Szó szerint olyan sokáig csiszolta azt a tetőt, hogy a gyerekek azt hitték, sosem lesz vége!'::text),
(383232,42582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... die Kinder das nächste Vogelhäuschen selbst schleifen, aber noch weiß es keiner.'::text,'könnten'::text,'müssen'::text,'sollten'::text,'Hör zu, angeblich könnten die Kinder das nächste Vogelhäuschen selbst schleifen, aber noch weiß es keiner.'::text),
(383236,42582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, діти ... самі шліфувати наступну шпаківню, але ще ніхто не знає.'::text,'можуть'::text,'мусять'::text,'мали б'::text,'Слухай, кажуть, діти можуть самі шліфувати наступну шпаківню, але ще ніхто не знає.'::text),
(383235,42582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, parece que los niños ... lijar ellos mismos la próxima casita, pero nadie lo sabe todavía.'::text,'podrían'::text,'deben'::text,'deberían'::text,'Escucha, parece que los niños podrían lijar ellos mismos la próxima casita, pero nadie lo sabe todavía.'::text),
(383234,42582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment les enfants ... poncer eux-mêmes le prochain nichoir, mais personne ne sait encore.'::text,'pourraient'::text,'doivent'::text,'devraient'::text,'Écoute, apparemment les enfants pourraient poncer eux-mêmes le prochain nichoir, mais personne ne sait encore.'::text),
(383237,42582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya çocuklar bir sonraki kuş evini kendileri ..., ama henüz kimse bilmiyor.'::text,'zımparalayabilir'::text,'zımparalamalı'::text,'zımparalasa iyi olur'::text,'Dinle, güya çocuklar bir sonraki kuş evini kendileri zımparalayabilir, ama henüz kimse bilmiyor.'::text),
(383238,42582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a gyerekek maguk ... a következő madárházat, de még senki sem tudja.'::text,'csiszolhatják'::text,'csiszolniuk kell'::text,'csiszolniuk kellene'::text,'Figyelj, állítólag a gyerekek maguk csiszolhatják a következő madárházat, de még senki sem tudja.'::text),
(383250,42584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann sagte den Kindern, dass sie das Dach ..., bevor sie es streichen.'::text,'schleifen mussten'::text,'schleifen müssen'::text,'schleifen muss'::text,'Der Mann sagte den Kindern, dass sie das Dach schleifen mussten, bevor sie es streichen.'::text),
(383254,42584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік сказав дітям, що вони ... дах, перш ніж його фарбувати.'::text,'мали відшліфувати'::text,'мають відшліфувати'::text,'має відшліфувати'::text,'Чоловік сказав дітям, що вони мали відшліфувати дах, перш ніж його фарбувати.'::text),
(383253,42584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre les dijo a los niños que ... el tejado antes de pintarlo.'::text,'tenían que lijar'::text,'tienen que lijar'::text,'tiene que lijar'::text,'El hombre les dijo a los niños que tenían que lijar el tejado antes de pintarlo.'::text),
(383252,42584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a dit aux enfants qu''ils ... le toit avant de le peindre.'::text,'devaient poncer'::text,'doivent poncer'::text,'doit poncer'::text,'L''homme a dit aux enfants qu''ils devaient poncer le toit avant de le peindre.'::text),
(383255,42584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam çocuklara çatıyı boyamadan önce ... söyledi.'::text,'zımparalamaları gerektiğini'::text,'zımparalamaları gerektiğini'::text,'zımparalaması gerektiğini'::text,'Adam çocuklara çatıyı boyamadan önce zımparalamaları gerektiğini söyledi.'::text),
(383256,42584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi azt mondta a gyerekeknek, hogy ... a tetőt, mielőtt lefestik.'::text,'le kell csiszolniuk'::text,'le kell csiszolniuk'::text,'le kell csiszolnia'::text,'A férfi azt mondta a gyerekeknek, hogy le kell csiszolniuk a tetőt, mielőtt lefestik.'::text),
(383259,42585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er jung war, ... er jeden Sommer mit seinem eigenen Opa Vogelhäuschen.'::text,'schliff'::text,'schliff'::text,'war es gewohnt zu schleifen'::text,'Als er jung war, schliff er jeden Sommer mit seinem eigenen Opa Vogelhäuschen.'::text),
(383263,42585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він був молодим, він ... шпаківні зі своїм дідусем щоліта.'::text,'шліфував'::text,'шліфував'::text,'звик шліфувати'::text,'Коли він був молодим, він шліфував шпаківні зі своїм дідусем щоліта.'::text),
(383262,42585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De joven, ... casitas para pájaros con su propio abuelo cada verano.'::text,'lijaba'::text,'solía lijar'::text,'estaba acostumbrado a lijar'::text,'De joven, lijaba casitas para pájaros con su propio abuelo cada verano.'::text),
(383261,42585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il était jeune, il ... des nichoirs avec son propre grand-père chaque été.'::text,'ponçait'::text,'ponçait'::text,'avait l''habitude de poncer'::text,'Quand il était jeune, il ponçait des nichoirs avec son propre grand-père chaque été.'::text),
(383264,42585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gençken her yaz kendi dedesiyle kuş evleri ...'::text,'zımparalardı'::text,'zımparalardı'::text,'zımparalamaya alışkındı'::text,'Gençken her yaz kendi dedesiyle kuş evleri zımparalardı.'::text),
(383265,42585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fiatalkorában minden nyáron a saját nagyapjával ... madárházakat.'::text,'csiszolt'::text,'csiszolgatott'::text,'hozzá volt szokva csiszolni'::text,'Fiatalkorában minden nyáron a saját nagyapjával csiszolt madárházakat.'::text),
(383268,42586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Kleine hat das Häuschen gehalten, während Opa mit dem ... des Dachs fertig wurde, irgendwie voll süß.'::text,'Schleifen'::text,'Schleifen'::text,'Schleifen'::text,'Bro, der Kleine hat das Häuschen gehalten, während Opa mit dem Schleifen des Dachs fertig wurde, irgendwie voll süß.'::text),
(383272,42586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, малий тримав шпаківню, поки дід закінчував ... дах, якось аж мило.'::text,'шліфувати'::text,'шліфувати'::text,'шліфувати'::text,'Бро, малий тримав шпаківню, поки дід закінчував шліфувати дах, якось аж мило.'::text),
(383271,42586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el crío sujetaba la casita mientras el abuelo terminaba de ... el tejado, en plan tierno.'::text,'lijar'::text,'lijar'::text,'lijar'::text,'Tío, el crío sujetaba la casita mientras el abuelo terminaba de lijar el tejado, en plan tierno.'::text),
(383270,42586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le petit tenait la boîte pendant que papi finissait de ... le toit, trop mignon en vrai.'::text,'poncer'::text,'poncer'::text,'poncer'::text,'Frère, le petit tenait la boîte pendant que papi finissait de poncer le toit, trop mignon en vrai.'::text),
(383273,42586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dede çatıyı ... bitirirken ufaklık kutuyu tuttu, bayağı tatlı.'::text,'zımparalamayı'::text,'zımparalamayı'::text,'zımparala'::text,'Kanka, dede çatıyı zımparalamayı bitirirken ufaklık kutuyu tuttu, bayağı tatlı.'::text),
(383274,42586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kicsi tartotta a dobozt, amíg a nagyapa befejezte a tető ..., tök cuki.'::text,'csiszolását'::text,'csiszolását'::text,'csiszolását'::text,'Tesó, a kicsi tartotta a dobozt, amíg a nagyapa befejezte a tető csiszolását, tök cuki.'::text),
(383277,42587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat das ganze Dach von Hand geschliffen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Er hat das ganze Dach von Hand geschliffen, oder?'::text),
(383281,42587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відшліфував увесь дах вручну, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Він відшліфував увесь дах вручну, правда?'::text),
(383280,42587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lijó todo el tejado a mano, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Lijó todo el tejado a mano, ¿verdad?'::text),
(383279,42587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a poncé tout le toit à la main, ... ?'::text,'non'::text,'non'::text,'non'::text,'Il a poncé tout le toit à la main, non ?'::text),
(383282,42587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün çatıyı elle zımparaladı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bütün çatıyı elle zımparaladı, değil mi?'::text),
(383283,42587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész tetőt kézzel csiszolta le, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Az egész tetőt kézzel csiszolta le, ugye?'::text),
(383286,42588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schleifpapier ist zum Schleifen da, also mag der Mann es, und ...'::text,'die Kinder auch'::text,'die Kinder auch'::text,'die Kinder auch'::text,'Schleifpapier ist zum Schleifen da, also mag der Mann es, und die Kinder auch.'::text),
(383290,42588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наждачний папір — для шліфування, тож чоловікові він подобається, і ...'::text,'дітям теж'::text,'дітям теж'::text,'дітям теж'::text,'Наждачний папір — для шліфування, тож чоловікові він подобається, і дітям теж.'::text),
(383289,42588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El papel de lija es para lijar, así que al hombre le gusta, y ...'::text,'a los niños también'::text,'a los niños también'::text,'a los niños también'::text,'El papel de lija es para lijar, así que al hombre le gusta, y a los niños también.'::text),
(383288,42588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le papier de verre, c''est pour poncer, donc l''homme l''aime bien, et ...'::text,'les enfants aussi'::text,'les enfants aussi'::text,'les enfants aussi'::text,'Le papier de verre, c''est pour poncer, donc l''homme l''aime bien, et les enfants aussi.'::text),
(383291,42588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zımpara kâğıdı zımparalamak içindir, bu yüzden adam onu seviyor, ve ...'::text,'çocuklar da'::text,'çocuklar da'::text,'çocuklar da'::text,'Zımpara kâğıdı zımparalamak içindir, bu yüzden adam onu seviyor, ve çocuklar da.'::text),
(383292,42588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csiszolópapír csiszolásra való, ezért a férfi szereti, és ...'::text,'a gyerekek is'::text,'a gyerekek is'::text,'a gyerekek is'::text,'A csiszolópapír csiszolásra való, ezért a férfi szereti, és a gyerekek is.'::text),
(383304,42590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird er jedes Vogelhäuschen in der Werkstatt ..., sonst ist es das Ende!'::text,'geschliffen haben'::text,'schleifen'::text,'schleifen'::text,'Bis heute Abend wird er jedes Vogelhäuschen in der Werkstatt geschliffen haben, sonst ist es das Ende!'::text),
(383308,42590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... кожну шпаківню в майстерні, інакше це кінець!'::text,'відшліфує'::text,'відшліфує'::text,'шліфуватиме'::text,'До вечора він відшліфує кожну шпаківню в майстерні, інакше це кінець!'::text),
(383307,42590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche ... todas las casitas del taller, o será el fin!'::text,'habrá lijado'::text,'lijará'::text,'estará lijando'::text,'¡Para esta noche habrá lijado todas las casitas del taller, o será el fin!'::text),
(383306,42590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... tous les nichoirs de l''atelier, sinon c''est la fin !'::text,'aura poncé'::text,'poncera'::text,'sera en train de poncer'::text,'D''ici ce soir, il aura poncé tous les nichoirs de l''atelier, sinon c''est la fin !'::text),
(383309,42590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar atölyedeki her kuş evini ..., yoksa her şey biter!'::text,'zımparalamış olacak'::text,'zımparalayacak'::text,'zımparalıyor olacak'::text,'Bu akşama kadar atölyedeki her kuş evini zımparalamış olacak, yoksa her şey biter!'::text),
(383310,42590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ... a műhely összes madárházát, különben vége mindennek!'::text,'lecsiszolja'::text,'le fogja csiszolni'::text,'csiszolni fogja'::text,'Estére lecsiszolja a műhely összes madárházát, különben vége mindennek!'::text),
(333264,37030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Junge die Karten ..., versammelte sich seine Familie im Garten.'::text,'ausbalancierte'::text,'ausbalancierte'::text,'ausbalanciert hat'::text,'Während der Junge die Karten ausbalancierte, versammelte sich seine Familie im Garten.'::text),
(333268,37030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки хлопчик ... карти, його родина збиралася в саду.'::text,'врівноважував'::text,'врівноважив'::text,'врівноважив'::text,'Поки хлопчик врівноважував карти, його родина збиралася в саду.'::text),
(333267,37030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el niño ... las cartas, su familia se reunía en el jardín.'::text,'equilibraba'::text,'equilibró'::text,'ha equilibrado'::text,'Mientras el niño equilibraba las cartas, su familia se reunía en el jardín.'::text),
(333266,37030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le garçon ... les cartes, sa famille se réunissait dans le jardin.'::text,'équilibrait'::text,'a équilibré'::text,'a équilibré'::text,'Pendant que le garçon équilibrait les cartes, sa famille se réunissait dans le jardin.'::text),
(333269,37030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk kartları ..., ailesi bahçede toplanıyordu.'::text,'dengelerken'::text,'dengelediğinde'::text,'dengelemişken'::text,'Çocuk kartları dengelerken, ailesi bahçede toplanıyordu.'::text),
(333270,37030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a fiú ... a kártyákat, a családja a kertben gyülekezett.'::text,'egyensúlyozta'::text,'egyensúlyba hozta'::text,'egyensúlyba hozta'::text,'Miközben a fiú egyensúlyozta a kártyákat, a családja a kertben gyülekezett.'::text),
(333273,37031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... jetzt schon seit zehn Minuten Karten auf dem Gartentisch aus.'::text,'balanciert'::text,'balanciert'::text,'balanciert'::text,'Der Junge balanciert jetzt schon seit zehn Minuten Karten auf dem Gartentisch aus.'::text),
(333277,37031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчик ... карти на садовому столі вже десять хвилин.'::text,'врівноважує'::text,'врівноважує'::text,'врівноважує'::text,'Хлопчик врівноважує карти на садовому столі вже десять хвилин.'::text),
(333276,37031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El niño ... cartas en la mesa del jardín desde hace diez minutos.'::text,'ha estado equilibrando'::text,'está equilibrando'::text,'equilibra'::text,'El niño ha estado equilibrando cartas en la mesa del jardín desde hace diez minutos.'::text),
(333275,37031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... des cartes sur la table du jardin depuis dix minutes.'::text,'équilibre'::text,'équilibre'::text,'équilibre'::text,'Le garçon équilibre des cartes sur la table du jardin depuis dix minutes.'::text),
(333278,37031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk on dakikadır bahçe masasında kartları ...'::text,'dengeliyor'::text,'dengeliyor'::text,'dengeler'::text,'Çocuk on dakikadır bahçe masasında kartları dengeliyor.'::text),
(333279,37031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú már tíz perce ... a kártyákat a kerti asztalon.'::text,'egyensúlyozza'::text,'egyensúlyozza'::text,'egyensúlyozza'::text,'A fiú már tíz perce egyensúlyozza a kártyákat a kerti asztalon.'::text),
(333282,37032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade die zweite Karte aus, als seine Oma ihn rief.'::text,'balancierte'::text,'balancierte'::text,'hat balanciert'::text,'Er balancierte gerade die zweite Karte aus, als seine Oma ihn rief.'::text),
(333286,37032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... другу карту, коли його покликала бабуся.'::text,'врівноважував'::text,'врівноважив'::text,'врівноважив'::text,'Він врівноважував другу карту, коли його покликала бабуся.'::text),
(333285,37032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la segunda carta cuando su abuela lo llamó.'::text,'Estaba equilibrando'::text,'Equilibró'::text,'Ha equilibrado'::text,'Estaba equilibrando la segunda carta cuando su abuela lo llamó.'::text),
(333284,37032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la deuxième carte quand sa grand-mère l''a appelé.'::text,'équilibrait'::text,'a équilibré'::text,'a équilibré'::text,'Il équilibrait la deuxième carte quand sa grand-mère l''a appelé.'::text),
(333287,37032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükannesi onu çağırdığında ikinci kartı ...'::text,'dengeliyordu'::text,'dengeledi'::text,'dengelemiş'::text,'Büyükannesi onu çağırdığında ikinci kartı dengeliyordu.'::text),
(333288,37032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a második kártyát ..., amikor a nagymamája szólt neki.'::text,'egyensúlyozta'::text,'egyensúlyba hozta'::text,'egyensúlyba hozta'::text,'Épp a második kártyát egyensúlyozta, amikor a nagymamája szólt neki.'::text),
(333291,37033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt ... zwei Karten erfolgreich ausbalanciert, und die Struktur steht nun als Dreieck.'::text,'hat'::text,'hat'::text,'balanciert'::text,'Das Subjekt hat zwei Karten erfolgreich ausbalanciert, und die Struktur steht nun als Dreieck.'::text),
(333295,37033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт успішно ... дві карти, і конструкція тепер стоїть трикутником.'::text,'врівноважив'::text,'врівноважував'::text,'врівноважує'::text,'Суб''єкт успішно врівноважив дві карти, і конструкція тепер стоїть трикутником.'::text),
(333294,37033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto ... dos cartas con éxito, y la estructura se sostiene ahora como un triángulo.'::text,'ha equilibrado'::text,'ha estado equilibrando'::text,'está equilibrando'::text,'El sujeto ha equilibrado dos cartas con éxito, y la estructura se sostiene ahora como un triángulo.'::text),
(333293,37033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... deux cartes avec succès, et la structure tient désormais en triangle.'::text,'a équilibré'::text,'a équilibré'::text,'équilibre'::text,'Le sujet a équilibré deux cartes avec succès, et la structure tient désormais en triangle.'::text),
(333296,37033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek iki kartı başarıyla ... ve yapı artık üçgen şeklinde duruyor.'::text,'dengeledi'::text,'dengeliyordu'::text,'dengeliyor'::text,'Denek iki kartı başarıyla dengeledi ve yapı artık üçgen şeklinde duruyor.'::text),
(333297,37033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany sikeresen ... két kártyát, és a szerkezet most háromszögként áll.'::text,'egyensúlyba hozott'::text,'egyensúlyozott'::text,'egyensúlyoz'::text,'Az alany sikeresen egyensúlyba hozott két kártyát, és a szerkezet most háromszögként áll.'::text),
(333300,37034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Mittagessen fertig war, ... er die Karten perfekt ausbalanciert, und keiner wagte zu atmen!'::text,'hatte'::text,'hat'::text,'balanciert'::text,'Als das Mittagessen fertig war, hatte er die Karten perfekt ausbalanciert, und keiner wagte zu atmen!'::text),
(333304,37034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли обід був готовий, він уже ... карти ідеально, і ніхто не смів дихнути!'::text,'врівноважив'::text,'врівноважив'::text,'врівноважує'::text,'Коли обід був готовий, він уже врівноважив карти ідеально, і ніхто не смів дихнути!'::text),
(333303,37034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando la comida estuvo lista, ... las cartas a la perfección y nadie se atrevía a respirar!'::text,'había equilibrado'::text,'ha equilibrado'::text,'equilibra'::text,'¡Para cuando la comida estuvo lista, había equilibrado las cartas a la perfección y nadie se atrevía a respirar!'::text),
(333302,37034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le déjeuner a été prêt, il ... les cartes à la perfection, et personne n''osait respirer !'::text,'avait équilibré'::text,'a équilibré'::text,'équilibre'::text,'Quand le déjeuner a été prêt, il avait équilibré les cartes à la perfection, et personne n''osait respirer !'::text),
(333305,37034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeği hazır olduğunda kartları kusursuzca ... ve kimse nefes almaya cesaret edemiyordu!'::text,'dengelemişti'::text,'dengeledi'::text,'dengeliyor'::text,'Öğle yemeği hazır olduğunda kartları kusursuzca dengelemişti ve kimse nefes almaya cesaret edemiyordu!'::text),
(333306,37034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire kész lett az ebéd, tökéletesen ... a kártyákat, és senki sem mert levegőt venni!'::text,'egyensúlyba hozta'::text,'egyensúlyba hozta'::text,'egyensúlyozza'::text,'Mire kész lett az ebéd, tökéletesen egyensúlyba hozta a kártyákat, és senki sem mert levegőt venni!'::text),
(333318,37036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jetzt Wind wehen würde, ... die Karten, die er ausbalanciert hat, in einer totalen Katastrophe enden!'::text,'würden'::text,'werden'::text,'endeten'::text,'Wenn jetzt Wind wehen würde, würden die Karten, die er ausbalanciert hat, in einer totalen Katastrophe enden!'::text),
(333322,37036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби зараз подув вітер, карти, які він врівноважив, ... повною катастрофою!'::text,'закінчилися б'::text,'закінчаться'::text,'закінчилися'::text,'Якби зараз подув вітер, карти, які він врівноважив, закінчилися б повною катастрофою!'::text),
(333321,37036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si ahora soplara el viento, las cartas que equilibró ... en un desastre total!'::text,'acabarían'::text,'acabarán'::text,'acabaron'::text,'¡Si ahora soplara el viento, las cartas que equilibró acabarían en un desastre total!'::text),
(333320,37036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent soufflait maintenant, les cartes qu''il a équilibrées ... en désastre total !'::text,'finiraient'::text,'finiront'::text,'ont fini'::text,'Si le vent soufflait maintenant, les cartes qu''il a équilibrées finiraient en désastre total !'::text),
(333323,37036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi rüzgâr esse, dengelediği kartlar tam bir felaketle ...!'::text,'biterdi'::text,'bitecek'::text,'bitti'::text,'Şimdi rüzgâr esse, dengelediği kartlar tam bir felaketle biterdi!'::text),
(333324,37036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha most fújna a szél, a kártyák, amiket egyensúlyba hozott, totális katasztrófával ...!'::text,'végződnének'::text,'végződnek majd'::text,'végződtek'::text,'Ha most fújna a szél, a kártyák, amiket egyensúlyba hozott, totális katasztrófával végződnének!'::text),
(333327,37037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte mal, ich hab gehört, die Karten ... vom Jungen selbst ausbalanciert, ganz ohne Hilfe.'::text,'wurden'::text,'balancierten'::text,'werden'::text,'Warte mal, ich hab gehört, die Karten wurden vom Jungen selbst ausbalanciert, ganz ohne Hilfe.'::text),
(333331,37037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, я чула, що карти ... самим хлопчиком, взагалі без допомоги.'::text,'були врівноважені'::text,'врівноважили'::text,'врівноважені'::text,'Стривай, я чула, що карти були врівноважені самим хлопчиком, взагалі без допомоги.'::text),
(333330,37037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, he oído que las cartas ... por el propio niño, sin ninguna ayuda.'::text,'fueron equilibradas'::text,'equilibraron'::text,'son equilibradas'::text,'Espera, he oído que las cartas fueron equilibradas por el propio niño, sin ninguna ayuda.'::text),
(333329,37037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu que les cartes ... par le garçon lui-même, sans aucune aide.'::text,'ont été équilibrées'::text,'ont équilibré'::text,'sont équilibrées'::text,'Attends, j''ai entendu que les cartes ont été équilibrées par le garçon lui-même, sans aucune aide.'::text),
(333332,37037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki kartlar hiç yardım almadan bizzat çocuk tarafından ...'::text,'dengelenmiş'::text,'dengelemiş'::text,'dengeleniyor'::text,'Dur, duydum ki kartlar hiç yardım almadan bizzat çocuk tarafından dengelenmiş.'::text),
(333333,37037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, úgy hallottam, a kártyák maga a fiú által ..., teljesen segítség nélkül.'::text,'lettek egyensúlyba hozva'::text,'hozták egyensúlyba'::text,'vannak egyensúlyba hozva'::text,'Várj, úgy hallottam, a kártyák maga a fiú által lettek egyensúlyba hozva, teljesen segítség nélkül.'::text),
(333336,37038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, dass der Junge beide Karten allein ...'::text,'ausbalanciert hat'::text,'ausbalanciert wurde'::text,'ausbalancierend'::text,'Hör zu, sie hat mir erzählt, dass der Junge beide Karten allein ausbalanciert hat.'::text),
(333340,37038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що хлопчик сам ... обидві карти.'::text,'врівноважив'::text,'був врівноважений'::text,'врівноважуючи'::text,'Слухай, вона сказала мені, що хлопчик сам врівноважив обидві карти.'::text),
(333339,37038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el niño ... las dos cartas él solo.'::text,'equilibró'::text,'fue equilibrado'::text,'equilibrando'::text,'Escucha, me dijo que el niño equilibró las dos cartas él solo.'::text),
(333338,37038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que le garçon ... les deux cartes tout seul.'::text,'a équilibré'::text,'a été équilibré'::text,'équilibrant'::text,'Écoute, elle m''a dit que le garçon a équilibré les deux cartes tout seul.'::text),
(333341,37038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana çocuğun iki kartı da tek başına ... söyledi.'::text,'dengelediğini'::text,'dengelendiğini'::text,'dengeleyerek'::text,'Dinle, bana çocuğun iki kartı da tek başına dengelediğini söyledi.'::text),
(333342,37038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a fiú egyedül ... mindkét kártyát.'::text,'hozta egyensúlyba'::text,'lett egyensúlyba hozva'::text,'egyensúlyozva'::text,'Figyelj, azt mondta, hogy a fiú egyedül hozta egyensúlyba mindkét kártyát.'::text),
(333345,37039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... er viel üben, weil er Karten so leicht ausbalanciert.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Bestie, angeblich muss er viel üben, weil er Karten so leicht ausbalanciert.'::text),
(333349,37039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... багато тренуватися, бо так легко врівноважує карти.'::text,'мусить'::text,'не може'::text,'не мав би'::text,'Подруго, кажуть, він мусить багато тренуватися, бо так легко врівноважує карти.'::text),
(333348,37039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que ... practicar mucho, porque equilibra las cartas con mucha facilidad.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Amiga, parece que debe de practicar mucho, porque equilibra las cartas con mucha facilidad.'::text),
(333347,37039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... beaucoup s''entraîner, parce qu''il équilibre les cartes si facilement.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Ma belle, apparemment il doit beaucoup s''entraîner, parce qu''il équilibre les cartes si facilement.'::text),
(333350,37039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, güya çok ..., çünkü kartları çok kolay dengeliyor.'::text,'çalışıyor olmalı'::text,'çalışıyor olamaz'::text,'çalışmamalı'::text,'Kankam, güya çok çalışıyor olmalı, çünkü kartları çok kolay dengeliyor.'::text),
(333351,37039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag sokat ..., mert olyan könnyen egyensúlyozza a kártyákat.'::text,'gyakorol biztosan'::text,'nem gyakorolhat'::text,'nem kéne gyakorolnia'::text,'Csajszi, állítólag sokat gyakorol biztosan, mert olyan könnyen egyensúlyozza a kártyákat.'::text),
(358968,39886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Bräutigam jetzt weglaufen würde, ... ihm die Braut das niemals verzeihen!'::text,'würde'::text,'wird'::text,NULL::text,'Wenn der Bräutigam jetzt weglaufen würde, würde ihm die Braut das niemals verzeihen!'::text),
(358972,39886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби наречений зараз утік, наречена ... йому ніколи!'::text,'не пробачила б'::text,'не пробачить'::text,'не пробачила'::text,'Якби наречений зараз утік, наречена не пробачила б йому ніколи!'::text),
(358971,39886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el novio huyera ahora, la novia no se lo ... nunca!'::text,'perdonaría'::text,'perdonará'::text,'perdonó'::text,'¡Si el novio huyera ahora, la novia no se lo perdonaría nunca!'::text),
(358970,39886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le marié s''enfuyait maintenant, la mariée ne le lui ... jamais !'::text,'pardonnerait'::text,'pardonnera'::text,'a pardonné'::text,'Si le marié s''enfuyait maintenant, la mariée ne le lui pardonnerait jamais !'::text),
(358973,39886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat şimdi kaçsa, gelin onu asla ...!'::text,'affetmezdi'::text,'affetmeyecek'::text,'affetmedi'::text,'Damat şimdi kaçsa, gelin onu asla affetmezdi!'::text),
(358974,39886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a vőlegény most elszökne, a menyasszony soha ... neki!'::text,'nem bocsátana meg'::text,'nem fog megbocsátani'::text,'nem bocsátott meg'::text,'Ha a vőlegény most elszökne, a menyasszony soha nem bocsátana meg neki!'::text),
(358977,39887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fliege des Bräutigams ... heute Morgen dreimal gerichtet! Totale Katastrophe!'::text,'wurde'::text,'richtete'::text,'richtet'::text,'Die Fliege des Bräutigams wurde heute Morgen dreimal gerichtet! Totale Katastrophe!'::text),
(358981,39887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Метелика нареченого ... тричі сьогодні вранці! Повна катастрофа!'::text,'поправляли'::text,'поправив'::text,'поправляє'::text,'Метелика нареченого поправляли тричі сьогодні вранці! Повна катастрофа!'::text),
(358980,39887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La pajarita del novio ... tres veces esta mañana! ¡Desastre total!'::text,'fue arreglada'::text,'arregló'::text,'está arreglando'::text,'¡La pajarita del novio fue arreglada tres veces esta mañana! ¡Desastre total!'::text),
(358979,39887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le nœud papillon du marié ... trois fois ce matin ! Catastrophe totale !'::text,'a été rajusté'::text,'a rajusté'::text,'rajuste'::text,'Le nœud papillon du marié a été rajusté trois fois ce matin ! Catastrophe totale !'::text),
(358982,39887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damadın papyonu bu sabah üç kez ...! Tam bir felaket!'::text,'düzeltildi'::text,'düzeltti'::text,'düzeltiyor'::text,'Damadın papyonu bu sabah üç kez düzeltildi! Tam bir felaket!'::text),
(358983,39887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vőlegény csokornyakkendőjét ma reggel háromszor ...! Totális katasztrófa!'::text,'megigazították'::text,'megigazította'::text,'igazítja'::text,'A vőlegény csokornyakkendőjét ma reggel háromszor megigazították! Totális katasztrófa!'::text),
(358986,39888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat der Bräutigam seine Fliege vor der Hochzeit fünfmal ...'::text,'zurechtgerückt'::text,'wurde zurechtgerückt'::text,'zurechtrückend'::text,'Mädel, angeblich hat der Bräutigam seine Fliege vor der Hochzeit fünfmal zurechtgerückt.'::text),
(358990,39888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, наречений ... свого метелика п''ять разів перед весіллям.'::text,'поправив'::text,'був поправлений'::text,'поправляючи'::text,'Подруго, кажуть, наречений поправив свого метелика п''ять разів перед весіллям.'::text),
(358989,39888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que el novio se ... la pajarita cinco veces antes de la boda.'::text,'enderezó'::text,'fue enderezado'::text,'enderezando'::text,'Tía, parece que el novio se enderezó la pajarita cinco veces antes de la boda.'::text),
(358988,39888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le marié ... son nœud pap cinq fois avant le mariage.'::text,'a redressé'::text,'a été redressé'::text,'redressant'::text,'Meuf, apparemment le marié a redressé son nœud pap cinq fois avant le mariage.'::text),
(358991,39888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya damat düğünden önce papyonunu beş kez ...'::text,'düzeltmiş'::text,'düzeltilmiş'::text,'düzelterek'::text,'Kızım, güya damat düğünden önce papyonunu beş kez düzeltmiş.'::text),
(358992,39888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a vőlegény ötször ... a csokornyakkendőjét az esküvő előtt.'::text,'megigazította'::text,'meg lett igazítva'::text,'igazítva'::text,'Csajszi, állítólag a vőlegény ötször megigazította a csokornyakkendőjét az esküvő előtt.'::text),
(358995,39889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, der Bräutigam ... nervös sein, er fasst ständig seine Fliege an.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Hör zu, ich hab gehört, der Bräutigam muss nervös sein, er fasst ständig seine Fliege an.'::text),
(358999,39889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що наречений ... нервувати, він весь час чіпає свого метелика.'::text,'мусить'::text,'не може'::text,'має'::text,'Слухай, я чула, що наречений мусить нервувати, він весь час чіпає свого метелика.'::text),
(358998,39889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, he oído que el novio ... estar nervioso, no para de tocarse la pajarita.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Escucha, he oído que el novio debe de estar nervioso, no para de tocarse la pajarita.'::text),
(358997,39889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que le marié ... être nerveux, il n''arrête pas de toucher son nœud pap.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Écoute, j''ai entendu que le marié doit être nerveux, il n''arrête pas de toucher son nœud pap.'::text),
(359000,39889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki damat gergin ..., sürekli papyonuna dokunuyor.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Dinle, duydum ki damat gergin olmalı, sürekli papyonuna dokunuyor.'::text),
(359001,39889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, úgy hallottam, a vőlegény ... ideges, folyton a csokornyakkendőjét piszkálja.'::text,'biztosan'::text,'nem lehet'::text,'kellene hogy legyen'::text,'Figyelj, úgy hallottam, a vőlegény biztosan ideges, folyton a csokornyakkendőjét piszkálja.'::text),
(359004,39890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der Freund, ... den Bräutigam am Spiegel beobachtet hat, hat mir alles erzählt.'::text,'der'::text,'welcher'::text,'dessen'::text,'Mädel, der Freund, der den Bräutigam am Spiegel beobachtet hat, hat mir alles erzählt.'::text),
(359008,39890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, друг, ... спостерігав за нареченим біля дзеркала, розповів мені все.'::text,'який'::text,'котрий'::text,'чий'::text,'Подруго, друг, який спостерігав за нареченим біля дзеркала, розповів мені все.'::text),
(359007,39890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el amigo ... miró al novio en el espejo me lo contó todo.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, el amigo que miró al novio en el espejo me lo contó todo.'::text),
(359006,39890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le pote ... a regardé le marié devant le miroir m''a tout raconté.'::text,'qui'::text,'lequel'::text,'dont'::text,'Meuf, le pote qui a regardé le marié devant le miroir m''a tout raconté.'::text),
(359009,39890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, damadı aynanın önünde ... arkadaş bana her şeyi anlattı.'::text,'izleyen'::text,'izleyen'::text,'izlediği'::text,'Kızım, damadı aynanın önünde izleyen arkadaş bana her şeyi anlattı.'::text),
(359010,39890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a barát, ... a tükörnél nézte a vőlegényt, mindent elmondott.'::text,'aki'::text,'amelyik'::text,'akinek a'::text,'Csajszi, a barát, aki a tükörnél nézte a vőlegényt, mindent elmondott.'::text),
(359013,39891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Bräutigam hast du gesagt, du ... nicht nervös, aber ehrlich, du bist so lässig rausgelaufen.'::text,'wärst'::text,'bist'::text,'warst'::text,'Als Bräutigam hast du gesagt, du wärst nicht nervös, aber ehrlich, du bist so lässig rausgelaufen.'::text),
(359017,39891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як наречений, ти казав, що ... знервований, але чесно, ти вийшов так легко.'::text,'не'::text,'не'::text,'не був'::text,'Як наречений, ти казав, що не знервований, але чесно, ти вийшов так легко.'::text),
(359016,39891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Como novio, dijiste que no ... nervioso, pero la verdad es que saliste con muchísima soltura.'::text,'estabas'::text,'estás'::text,'has estado'::text,'Como novio, dijiste que no estabas nervioso, pero la verdad es que saliste con muchísima soltura.'::text),
(359015,39891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En tant que marié, tu as dit que tu ... pas nerveux, mais franchement tu es sorti avec une telle aisance.'::text,'n''étais'::text,'n''es'::text,'n''as été'::text,'En tant que marié, tu as dit que tu n''étais pas nerveux, mais franchement tu es sorti avec une telle aisance.'::text),
(359018,39891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat olarak gergin ... söyledin ama cidden öyle rahat çıktın ki.'::text,'olmadığını'::text,'olmadığını'::text,'olmadığını'::text,'Damat olarak gergin olmadığını söyledin ama cidden öyle rahat çıktın ki.'::text),
(359019,39891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vőlegényként azt mondtad, hogy nem ... ideges, de őszintén, olyan lazán sétáltál ki.'::text,'vagy'::text,'vagy'::text,'voltál'::text,'Vőlegényként azt mondtad, hogy nem vagy ideges, de őszintén, olyan lazán sétáltál ki.'::text),
(359022,39892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Fliegen gehasst, und jetzt bist du ehrlich gesagt der lässigste Bräutigam hier.'::text,'hast früher'::text,'hast immer'::text,'warst gewohnt'::text,'Du hast früher Fliegen gehasst, und jetzt bist du ehrlich gesagt der lässigste Bräutigam hier.'::text),
(359026,39892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... ненавидів метелики, а тепер ти тут найстильніший наречений, чесно.'::text,'колись'::text,'бувало'::text,'звик'::text,'Ти колись ненавидів метелики, а тепер ти тут найстильніший наречений, чесно.'::text),
(359025,39892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... las pajaritas, y ahora eres el novio con más estilo de aquí, en serio.'::text,'Solías odiar'::text,'Odiabas'::text,'Estabas acostumbrado a odiar'::text,'Solías odiar las pajaritas, y ahora eres el novio con más estilo de aquí, en serio.'::text),
(359024,39892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... les nœuds pap, et maintenant t''es le marié le plus classe ici, franchement.'::text,'détestais'::text,'détestais'::text,'étais habitué à détester'::text,'Avant, tu détestais les nœuds pap, et maintenant t''es le marié le plus classe ici, franchement.'::text),
(359027,39892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden papyonlardan ... ve şimdi buradaki en havalı damatsın, cidden.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Eskiden papyonlardan nefret ederdin ve şimdi buradaki en havalı damatsın, cidden.'::text),
(359028,39892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a csokornyakkendőket, most meg te vagy itt a legmenőbb vőlegény, komolyan.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva utálni'::text,'Régen utáltad a csokornyakkendőket, most meg te vagy itt a legmenőbb vőlegény, komolyan.'::text),
(359040,39894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bräutigam wartet vor ... Rosenbogen im Garten.'::text,'dem größten'::text,'einem größten'::text,'größtem'::text,'Der Bräutigam wartet vor dem größten Rosenbogen im Garten.'::text),
(359044,39894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наречений чекає перед ... трояндовою аркою в саду.'::text,'найбільшою'::text,'найбільшою'::text,'найбільшою'::text,'Наречений чекає перед найбільшою трояндовою аркою в саду.'::text),
(359043,39894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El novio espera ante ... arco de rosas del jardín.'::text,'el mayor'::text,'un mayor'::text,'mayor'::text,'El novio espera ante el mayor arco de rosas del jardín.'::text),
(359042,39894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marié attend devant ... arche de roses du jardin.'::text,'la plus grande'::text,'une plus grande'::text,'plus grande'::text,'Le marié attend devant la plus grande arche de roses du jardin.'::text),
(359045,39894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat bahçedeki ... gül kemerinin önünde bekliyor.'::text,'en büyük'::text,'en büyük'::text,'en büyük'::text,'Damat bahçedeki en büyük gül kemerinin önünde bekliyor.'::text),
(359046,39894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vőlegény a kertben ... rózsaív előtt vár.'::text,'a legnagyobb'::text,'egy legnagyobb'::text,'legnagyobb'::text,'A vőlegény a kertben a legnagyobb rózsaív előtt vár.'::text),
(359049,39895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bräutigam ... jetzt vor dem Blumenbogen.'::text,'wartet'::text,'wartet'::text,'hat gewartet'::text,'Der Bräutigam wartet jetzt vor dem Blumenbogen.'::text),
(359053,39895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наречений зараз ... перед квітковою аркою.'::text,'чекає'::text,'чекає'::text,'чекав'::text,'Наречений зараз чекає перед квітковою аркою.'::text),
(359052,39895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El novio ... ahora delante del arco de flores.'::text,'está esperando'::text,'espera'::text,'ha esperado'::text,'El novio está esperando ahora delante del arco de flores.'::text),
(359051,39895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marié ... maintenant devant l''arche de fleurs.'::text,'attend'::text,'attend'::text,'a attendu'::text,'Le marié attend maintenant devant l''arche de fleurs.'::text),
(359054,39895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat şimdi çiçek kemerinin önünde ...'::text,'bekliyor'::text,'bekler'::text,'bekledi'::text,'Damat şimdi çiçek kemerinin önünde bekliyor.'::text),
(359055,39895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vőlegény most a virágív előtt ...'::text,'vár'::text,'vár'::text,'várt'::text,'A vőlegény most a virágív előtt vár.'::text),
(335856,37318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... den Strauß so vorsichtig, als der Gastgeber die Tür aufgemacht hat.'::text,'hieltest'::text,'hieltest'::text,'hast gehalten'::text,'Ehrlich, du hieltest den Strauß so vorsichtig, als der Gastgeber die Tür aufgemacht hat.'::text),
(335860,37318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... букет так обережно, коли господар відчинив двері.'::text,'тримала'::text,'потримала'::text,'тримала'::text,'Не буду брехати, ти тримала букет так обережно, коли господар відчинив двері.'::text),
(335859,37318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... el ramo con tanto cuidado cuando el anfitrión abrió la puerta.'::text,'sostenías'::text,'sostuviste'::text,'has sostenido'::text,'No te voy a mentir, sostenías el ramo con tanto cuidado cuando el anfitrión abrió la puerta.'::text),
(335858,37318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... le bouquet avec tellement de soin quand l''hôte a ouvert la porte.'::text,'tenais'::text,'as tenu'::text,'as tenu'::text,'Sans mentir, tu tenais le bouquet avec tellement de soin quand l''hôte a ouvert la porte.'::text),
(335861,37318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ev sahibi kapıyı açtığında buketi öyle özenle ...'::text,'tutuyordun'::text,'tuttun'::text,'tutmuşsun'::text,'Yalan yok, ev sahibi kapıyı açtığında buketi öyle özenle tutuyordun.'::text),
(335862,37318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, olyan óvatosan ... a csokrot, amikor a házigazda ajtót nyitott.'::text,'tartottad'::text,'tartottad'::text,'tartottad'::text,'Nem fogok hazudni, olyan óvatosan tartottad a csokrot, amikor a házigazda ajtót nyitott.'::text),
(335865,37319,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gastgeber ... den Strauß jetzt schon seit zehn Minuten. Eine Vase braucht es offensichtlich nicht.'::text,'hält'::text,'hält'::text,'hält'::text,'Der Gastgeber hält den Strauß jetzt schon seit zehn Minuten. Eine Vase braucht es offensichtlich nicht.'::text),
(335869,37319,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господар ... той букет уже десять хвилин. Ваза, очевидно, не потрібна.'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Господар тримає той букет уже десять хвилин. Ваза, очевидно, не потрібна.'::text),
(335868,37319,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anfitrión ... ese ramo desde hace diez minutos. Está claro que no hace falta un jarrón.'::text,'ha estado sosteniendo'::text,'está sosteniendo'::text,'sostiene'::text,'El anfitrión ha estado sosteniendo ese ramo desde hace diez minutos. Está claro que no hace falta un jarrón.'::text),
(335867,37319,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôte ... ce bouquet depuis dix minutes. Clairement, pas besoin de vase.'::text,'tient'::text,'tient'::text,'tient'::text,'L''hôte tient ce bouquet depuis dix minutes. Clairement, pas besoin de vase.'::text),
(335870,37319,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibi on dakikadır o buketi ...; belli ki vazoya gerek yok.'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Ev sahibi on dakikadır o buketi tutuyor; belli ki vazoya gerek yok.'::text),
(335871,37319,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazda már tíz perce ... azt a csokrot. Vázára nyilván nincs szükség.'::text,'tartja'::text,'tartja'::text,'tartja'::text,'A házigazda már tíz perce tartja azt a csokrot. Vázára nyilván nincs szükség.'::text),
(335874,37320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gastgeber ... gerade das Essen, als der Strauß ankam. Perfektes Timing, natürlich.'::text,'servierte'::text,'servierte'::text,'hat serviert'::text,'Der Gastgeber servierte gerade das Essen, als der Strauß ankam. Perfektes Timing, natürlich.'::text),
(335878,37320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господар ... вечерю, коли прибув букет. Ідеальний таймінг, звісно.'::text,'подавав'::text,'подав'::text,'подав'::text,'Господар подавав вечерю, коли прибув букет. Ідеальний таймінг, звісно.'::text),
(335877,37320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anfitrión ... la cena cuando llegó el ramo. Un timing perfecto, obviamente.'::text,'estaba sirviendo'::text,'sirvió'::text,'ha servido'::text,'El anfitrión estaba sirviendo la cena cuando llegó el ramo. Un timing perfecto, obviamente.'::text),
(335876,37320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôte ... le dîner quand le bouquet est arrivé. Timing parfait, évidemment.'::text,'servait'::text,'a servi'::text,'a servi'::text,'L''hôte servait le dîner quand le bouquet est arrivé. Timing parfait, évidemment.'::text),
(335879,37320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buket geldiğinde ev sahibi yemeği ...; mükemmel zamanlama, tabii ki.'::text,'servis ediyordu'::text,'servis etti'::text,'servis etmiş'::text,'Buket geldiğinde ev sahibi yemeği servis ediyordu; mükemmel zamanlama, tabii ki.'::text),
(335880,37320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazda épp ... a vacsorát, amikor megérkezett a csokor. Tökéletes időzítés, nyilván.'::text,'tálalta'::text,'feltálalta'::text,'feltálalta'::text,'A házigazda épp tálalta a vacsorát, amikor megérkezett a csokor. Tökéletes időzítés, nyilván.'::text),
(335883,37321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... diesen Monat schon drei Sträuße zu Dinnern mitgebracht, irgendwie ikonisch.'::text,'hat'::text,'hat'::text,'bringt'::text,'Yo, sie hat diesen Monat schon drei Sträuße zu Dinnern mitgebracht, irgendwie ikonisch.'::text),
(335887,37321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, цього місяця вона ... на вечері три букети, доволі культово.'::text,'принесла'::text,'приносила'::text,'приносить'::text,'Йо, цього місяця вона принесла на вечері три букети, доволі культово.'::text),
(335886,37321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, este mes ... tres ramos a cenas, bastante icónico.'::text,'ha llevado'::text,'ha estado llevando'::text,'lleva'::text,'Ey, este mes ha llevado tres ramos a cenas, bastante icónico.'::text),
(335885,37321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle ... trois bouquets à des dîners ce mois-ci, assez iconique.'::text,'a apporté'::text,'a apporté'::text,'apporte'::text,'Yo, elle a apporté trois bouquets à des dîners ce mois-ci, assez iconique.'::text),
(335888,37321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bu ay yemeklere üç buket ..., bayağı ikonik.'::text,'getirdi'::text,'getirip duruyor'::text,'getiriyor'::text,'Yo, bu ay yemeklere üç buket getirdi, bayağı ikonik.'::text),
(335889,37321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ebben a hónapban három csokrot ... vacsorákra, elég ikonikus.'::text,'vitt'::text,'vitt'::text,'visz'::text,'Figyu, ebben a hónapban három csokrot vitt vacsorákra, elég ikonikus.'::text),
(335892,37322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie mit dem Strauß ankam, ... der Gastgeber den Tisch schon gedeckt.'::text,'hatte'::text,'hat'::text,'deckt'::text,'Als sie mit dem Strauß ankam, hatte der Gastgeber den Tisch schon gedeckt.'::text),
(335896,37322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона прийшла з букетом, господар ... стіл.'::text,'уже накрив'::text,'уже накрив'::text,'уже накриває'::text,'Коли вона прийшла з букетом, господар уже накрив стіл.'::text),
(335895,37322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegó con el ramo, el anfitrión ya ... la mesa.'::text,'había puesto'::text,'ha puesto'::text,'pone'::text,'Cuando llegó con el ramo, el anfitrión ya había puesto la mesa.'::text),
(335894,37322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle est arrivée avec le bouquet, l''hôte ... la table.'::text,'avait déjà mis'::text,'a déjà mis'::text,'met déjà'::text,'Quand elle est arrivée avec le bouquet, l''hôte avait déjà mis la table.'::text),
(335897,37322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O buketle geldiğinde ev sahibi masayı çoktan ...'::text,'kurmuştu'::text,'kurdu'::text,'kuruyor'::text,'O buketle geldiğinde ev sahibi masayı çoktan kurmuştu.'::text),
(335898,37322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor megérkezett a csokorral, a házigazda már ... az asztalt.'::text,'megterítette'::text,'megterítette'::text,'teríti'::text,'Amikor megérkezett a csokorral, a házigazda már megterítette az asztalt.'::text),
(335910,37324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, dass sie den Strauß an dem Morgen auf dem Markt ...'::text,'gekauft hatte'::text,'gekauft hat'::text,'kauft'::text,'Sie sagte, dass sie den Strauß an dem Morgen auf dem Markt gekauft hatte.'::text),
(335914,37324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... букет на ринку того ранку.'::text,'купила'::text,'купила'::text,'купує'::text,'Вона сказала, що купила букет на ринку того ранку.'::text),
(335913,37324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... el ramo en el mercado esa mañana.'::text,'había comprado'::text,'ha comprado'::text,'compra'::text,'Dijo que había comprado el ramo en el mercado esa mañana.'::text),
(335912,37324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... le bouquet au marché ce matin-là.'::text,'avait acheté'::text,'a acheté'::text,'achète'::text,'Elle a dit qu''elle avait acheté le bouquet au marché ce matin-là.'::text),
(335915,37324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buketi o sabah pazardan ... söyledi.'::text,'almış olduğunu'::text,'aldığını'::text,'alıyor olduğunu'::text,'Buketi o sabah pazardan almış olduğunu söyledi.'::text),
(335916,37324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy aznap reggel a piacon ... a csokrot.'::text,'vette'::text,'vette'::text,'veszi'::text,'Azt mondta, hogy aznap reggel a piacon vette a csokrot.'::text),
(335919,37325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie früher Blumen gehasst, und jetzt bringt sie überall einen Strauß mit.'::text,'hat'::text,'hat'::text,'war'::text,'Bestie, angeblich hat sie früher Blumen gehasst, und jetzt bringt sie überall einen Strauß mit.'::text),
(335923,37325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... ненавиділа квіти, а тепер усюди носить букет.'::text,'колись'::text,'бувало'::text,'звикла'::text,'Подруго, кажуть, вона колись ненавиділа квіти, а тепер усюди носить букет.'::text),
(335922,37325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que ... las flores, y ahora lleva un ramo a todas partes.'::text,'solía odiar'::text,'odiaba'::text,'estaba acostumbrada a odiar'::text,'Amiga, parece que solía odiar las flores, y ahora lleva un ramo a todas partes.'::text),
(335921,37325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle ... les fleurs avant, et maintenant elle apporte un bouquet partout.'::text,'détestait'::text,'détestait'::text,'était habituée à détester'::text,'Ma belle, apparemment elle détestait les fleurs avant, et maintenant elle apporte un bouquet partout.'::text),
(335924,37325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, güya eskiden çiçeklerden ..., şimdi her yere buket götürüyor.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Kankam, güya eskiden çiçeklerden nefret ederdi, şimdi her yere buket götürüyor.'::text),
(335925,37325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag régen ... a virágokat, most meg mindenhová csokrot visz.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva utálni'::text,'Csajszi, állítólag régen utálta a virágokat, most meg mindenhová csokrot visz.'::text),
(335928,37326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich hat sie vergessen, eine Karte zum Strauß ...'::text,'dazuzulegen'::text,'Dazulegen'::text,'dazulegen'::text,'Okay, also angeblich hat sie vergessen, eine Karte zum Strauß dazuzulegen.'::text),
(335932,37326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вона забула ... листівку до букета.'::text,'додати'::text,'додавання'::text,'додати'::text,'Коротше, кажуть, вона забула додати листівку до букета.'::text),
(335931,37326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues parece que se le olvidó ... una tarjeta al ramo.'::text,'añadir'::text,'añadiendo'::text,'añadir'::text,'Vale, pues parece que se le olvidó añadir una tarjeta al ramo.'::text),
(335930,37326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle a oublié ... une carte au bouquet.'::text,'d''ajouter'::text,'ajoutant'::text,'ajouter'::text,'Bon, apparemment elle a oublié d''ajouter une carte au bouquet.'::text),
(335933,37326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya buketin yanına kart ... unutmuş.'::text,'eklemeyi'::text,'eklemek'::text,'ekle'::text,'Tamam, güya buketin yanına kart eklemeyi unutmuş.'::text),
(335934,37326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag elfelejtett ... egy kártyát a csokorhoz.'::text,'tűzni'::text,'tűzés'::text,'tűz'::text,'Szóval állítólag elfelejtett tűzni egy kártyát a csokorhoz.'::text),
(335946,37328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bevor du geklingelt hast, ... du schon den schönsten Strauß der Stadt ausgesucht.'::text,'hattest'::text,'hast'::text,'suchst'::text,'Ehrlich, bevor du geklingelt hast, hattest du schon den schönsten Strauß der Stadt ausgesucht.'::text),
(335950,37328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ще до того, як ти подзвонила у двері, ти вже ... найгарніший букет у місті.'::text,'вибрала'::text,'вибрала'::text,'вибираєш'::text,'Чесно, ще до того, як ти подзвонила у двері, ти вже вибрала найгарніший букет у місті.'::text),
(335949,37328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, antes de tocar el timbre, ya ... el ramo más bonito de la ciudad.'::text,'habías elegido'::text,'has elegido'::text,'eliges'::text,'La verdad, antes de tocar el timbre, ya habías elegido el ramo más bonito de la ciudad.'::text),
(335948,37328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avant de sonner, tu ... le plus joli bouquet de la ville.'::text,'avais déjà choisi'::text,'as déjà choisi'::text,'choisis déjà'::text,'Franchement, avant de sonner, tu avais déjà choisi le plus joli bouquet de la ville.'::text),
(335951,37328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, zili çalmadan önce şehrin en güzel buketini çoktan ...'::text,'seçmiştin'::text,'seçtin'::text,'seçiyorsun'::text,'Açıkçası, zili çalmadan önce şehrin en güzel buketini çoktan seçmiştin.'::text),
(335952,37328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mielőtt becsöngettél, már ... a város legszebb csokrát.'::text,'kiválasztottad'::text,'kiválasztottad'::text,'kiválasztod'::text,'Őszintén, mielőtt becsöngettél, már kiválasztottad a város legszebb csokrát.'::text),
(397641,44183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis Sonnenuntergang ... sie sechs Stunden lang durch die blaue Stadt gezogen, die sind dann komplett durch.'::text,'sind'::text,'werden'::text,'sind'::text,'Bro, bis Sonnenuntergang sind sie sechs Stunden lang durch die blaue Stadt gezogen, die sind dann komplett durch.'::text),
(397645,44183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до заходу сонця вони ... блакитне містечко шість годин, будуть геть вижаті.'::text,'оглядатимуть'::text,'оглядатимуть'::text,'оглядають'::text,'Бро, до заходу сонця вони оглядатимуть блакитне містечко шість годин, будуть геть вижаті.'::text),
(397644,44183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para el atardecer ... seis horas recorriendo el pueblo azul, van a acabar reventados.'::text,'habrán estado'::text,'estarán'::text,'han estado'::text,'Tío, para el atardecer habrán estado seis horas recorriendo el pueblo azul, van a acabar reventados.'::text),
(397643,44183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, au coucher du soleil, ça fera six heures qu''ils ... la ville bleue, ils vont être rincés.'::text,'visitent'::text,'visitent'::text,'visitent'::text,'Frère, au coucher du soleil, ça fera six heures qu''ils visitent la ville bleue, ils vont être rincés.'::text),
(397646,44183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gün batımına kadar altı saattir mavi kasabayı ..., bitap düşecekler.'::text,'geziyor olacaklar'::text,'geziyor olacaklar'::text,'geziyorlar'::text,'Kanka, gün batımına kadar altı saattir mavi kasabayı geziyor olacaklar, bitap düşecekler.'::text),
(397647,44183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, naplementére már hat órája ... a kék várost, totál ki lesznek purcanva.'::text,'járják majd'::text,'fogják járni'::text,'járják'::text,'Tesó, naplementére már hat órája járják majd a kék várost, totál ki lesznek purcanva.'::text),
(397659,44185,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide schlug vor, die Altstadt zu Fuß ..., weil die Gassen eng sind.'::text,'zu erkunden'::text,'zu erkunden'::text,'erkundet'::text,'Der Guide schlug vor, die Altstadt zu Fuß zu erkunden, weil die Gassen eng sind.'::text),
(397663,44185,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід запропонував ... старе місто пішки, бо вулички вузькі.'::text,'оглянути'::text,'оглянути'::text,'оглянули'::text,'Гід запропонував оглянути старе місто пішки, бо вулички вузькі.'::text),
(397662,44185,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía sugirió ... el casco antiguo a pie porque las callejuelas son estrechas.'::text,'recorrer'::text,'recorrer'::text,'recorrieron'::text,'El guía sugirió recorrer el casco antiguo a pie porque las callejuelas son estrechas.'::text),
(397661,44185,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide a proposé ... la vieille ville à pied parce que les ruelles sont étroites.'::text,'de visiter'::text,'de visiter'::text,'visité'::text,'Le guide a proposé de visiter la vieille ville à pied parce que les ruelles sont étroites.'::text),
(397664,44185,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber, sokaklar dar olduğu için eski şehri yürüyerek ... önerdi.'::text,'gezmeyi'::text,'gezmeyi'::text,'gezdi'::text,'Rehber, sokaklar dar olduğu için eski şehri yürüyerek gezmeyi önerdi.'::text),
(397665,44185,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető azt javasolta, hogy gyalog ... az óvárost, mert szűkek a sikátorok.'::text,'járják be'::text,'járják be'::text,'bejárták'::text,'Az idegenvezető azt javasolta, hogy gyalog járják be az óvárost, mert szűkek a sikátorok.'::text),
(397668,44186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Stadt ohne Guide erkundet haben, weil die Gassen zu verwirrend sind.'::text,'können nicht'::text,'dürfen nicht'::text,'würden nicht'::text,'Sie können nicht die Stadt ohne Guide erkundet haben, weil die Gassen zu verwirrend sind.'::text),
(397672,44186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... оглянути місто без гіда, бо вулички надто заплутані.'::text,'не могли'::text,'не мусили'::text,'не стали б'::text,'Вони не могли оглянути місто без гіда, бо вулички надто заплутані.'::text),
(397671,44186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... recorrido el pueblo sin guía, porque las callejuelas son demasiado liosas.'::text,'No pueden haber'::text,'No deben de haber'::text,'No habrían'::text,'No pueden haber recorrido el pueblo sin guía, porque las callejuelas son demasiado liosas.'::text),
(397670,44186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... visité la ville sans guide, parce que les ruelles sont trop déroutantes.'::text,'ne peuvent pas avoir'::text,'ne doivent pas avoir'::text,'n''auraient pas'::text,'Ils ne peuvent pas avoir visité la ville sans guide, parce que les ruelles sont trop déroutantes.'::text),
(397673,44186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehbersiz kasabayı ..., çünkü sokaklar fazla kafa karıştırıcı.'::text,'gezmiş olamazlar'::text,'gezmemiş olmalılar'::text,'gezmezlerdi'::text,'Rehbersiz kasabayı gezmiş olamazlar, çünkü sokaklar fazla kafa karıştırıcı.'::text),
(397674,44186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... bejárni a várost idegenvezető nélkül, mert a sikátorok túl zavarosak.'::text,'tudhatták'::text,'szabadott'::text,'akarták volna'::text,'Nem tudhatták bejárni a várost idegenvezető nélkül, mert a sikátorok túl zavarosak.'::text),
(397677,44187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide, ... Gewand gestreift ist, führt die Gruppe durch die blauen Gassen.'::text,'dessen'::text,'der'::text,'welches'::text,'Der Guide, dessen Gewand gestreift ist, führt die Gruppe durch die blauen Gassen.'::text),
(397681,44187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід, ... халат смугастий, водить групу блакитними вуличками.'::text,'чий'::text,'який'::text,'що'::text,'Гід, чий халат смугастий, водить групу блакитними вуличками.'::text),
(397680,44187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía, ... túnica es de rayas, lleva al grupo por las callejuelas azules.'::text,'cuya'::text,'que'::text,'la cual'::text,'El guía, cuya túnica es de rayas, lleva al grupo por las callejuelas azules.'::text),
(397679,44187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide, ... la tunique est rayée, fait visiter les ruelles bleues au groupe.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Le guide, dont la tunique est rayée, fait visiter les ruelles bleues au groupe.'::text),
(397682,44187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cübbesi çizgili ... rehber, grubu mavi sokaklarda gezdiriyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Cübbesi çizgili olan rehber, grubu mavi sokaklarda gezdiriyor.'::text),
(397683,44187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető, ... köpenye csíkos, végigvezeti a csoportot a kék sikátorokon.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az idegenvezető, akinek a köpenye csíkos, végigvezeti a csoportot a kék sikátorokon.'::text),
(397686,44188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erkundeten die blauen Gassen zu Fuß ... der sehr engen Straßen.'::text,'aufgrund'::text,'trotz'::text,'vorausgesetzt'::text,'Sie erkundeten die blauen Gassen zu Fuß aufgrund der sehr engen Straßen.'::text),
(397690,44188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони оглянули блакитні вулички пішки ... дуже вузькі вулиці.'::text,'через'::text,'попри'::text,'за умови що'::text,'Вони оглянули блакитні вулички пішки через дуже вузькі вулиці.'::text),
(397689,44188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Recorrieron las callejuelas azules a pie ... las calles tan estrechas.'::text,'debido a'::text,'a pesar de'::text,'siempre que'::text,'Recorrieron las callejuelas azules a pie debido a las calles tan estrechas.'::text),
(397688,44188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont visité les ruelles bleues à pied ... rues très étroites.'::text,'en raison des'::text,'malgré les'::text,'pourvu que les'::text,'Ils ont visité les ruelles bleues à pied en raison des rues très étroites.'::text),
(397691,44188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok dar sokaklar ... mavi sokakları yürüyerek gezdiler.'::text,'yüzünden'::text,'rağmen'::text,'şartıyla'::text,'Çok dar sokaklar yüzünden mavi sokakları yürüyerek gezdiler.'::text),
(397692,44188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyon szűk utcák ... gyalog járták be a kék sikátorokat.'::text,'miatt'::text,'ellenére'::text,'feltéve'::text,'A nagyon szűk utcák miatt gyalog járták be a kék sikátorokat.'::text),
(397695,44189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, der Guide schwört, er wusste, dass sie die ganze Stadt vor dem Mittagessen ...'::text,'erkunden würden'::text,'erkunden werden'::text,'gerade erkunden'::text,'Warte, der Guide schwört, er wusste, dass sie die ganze Stadt vor dem Mittagessen erkunden würden.'::text),
(397699,44189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, гід присягається, що знав, що вони ... все місто до обіду.'::text,'оглянуть'::text,'оглянуть'::text,'оглядають'::text,'Стривай, гід присягається, що знав, що вони оглянуть все місто до обіду.'::text),
(397698,44189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, el guía jura que sabía que ... todo el pueblo antes de comer.'::text,'recorrerían'::text,'recorrerán'::text,'están recorriendo'::text,'Espera, el guía jura que sabía que recorrerían todo el pueblo antes de comer.'::text),
(397697,44189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, le guide jure qu''il savait qu''ils ... toute la ville avant le déjeuner.'::text,'visiteraient'::text,'visiteront'::text,'visitent'::text,'Attends, le guide jure qu''il savait qu''ils visiteraient toute la ville avant le déjeuner.'::text),
(397700,44189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, rehber öğle yemeğinden önce bütün kasabayı ... bildiğine yemin ediyor.'::text,'gezeceklerini'::text,'gezeceklerini'::text,'geziyor olduklarını'::text,'Dur, rehber öğle yemeğinden önce bütün kasabayı gezeceklerini bildiğine yemin ediyor.'::text),
(397701,44189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, az idegenvezető esküszik, hogy tudta, ebéd előtt ... az egész várost.'::text,'bejárják'::text,'be fogják járni'::text,'éppen bejárják'::text,'Várj, az idegenvezető esküszik, hogy tudta, ebéd előtt bejárják az egész várost.'::text),
(397704,44190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, gerade ... du die blaue Stadt mit dem besten Guide überhaupt.'::text,'erkundest'::text,'erkundest'::text,'hast erkundet'::text,'Respekt, gerade erkundest du die blaue Stadt mit dem besten Guide überhaupt.'::text),
(397708,44190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, просто зараз ти ... блакитне містечко з найкращим гідом у ньому.'::text,'оглядаєш'::text,'оглядаєш'::text,'оглянув'::text,'Респект, просто зараз ти оглядаєш блакитне містечко з найкращим гідом у ньому.'::text),
(397707,44190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ahora mismo ... el pueblo azul con el mejor guía que hay.'::text,'estás recorriendo'::text,'recorres'::text,'has recorrido'::text,'Respeto, ahora mismo estás recorriendo el pueblo azul con el mejor guía que hay.'::text),
(397706,44190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, là tout de suite, tu ... la ville bleue avec le meilleur guide du coin.'::text,'visites'::text,'visites'::text,'as visité'::text,'Respect, là tout de suite, tu visites la ville bleue avec le meilleur guide du coin.'::text),
(397709,44190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, şu an mavi kasabayı en iyi rehberiyle ...'::text,'geziyorsun'::text,'gezersin'::text,'gezdin'::text,'Helal, şu an mavi kasabayı en iyi rehberiyle geziyorsun.'::text),
(397710,44190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, épp most a legjobb idegenvezetővel ... a kék várost.'::text,'járod be'::text,'járod be'::text,'jártad be'::text,'Respekt, épp most a legjobb idegenvezetővel járod be a kék várost.'::text),
(397713,44191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... die Stadt schon vorher erkundet, weil du dich kein einziges Mal verlaufen hast. Beeindruckend.'::text,'hattest'::text,'erkundetest'::text,'hast'::text,'Du hattest die Stadt schon vorher erkundet, weil du dich kein einziges Mal verlaufen hast. Beeindruckend.'::text),
(397717,44191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... це місто раніше, бо жодного разу не заблукав. Вражає.'::text,'оглянув'::text,'оглядав'::text,'оглянув'::text,'Ти оглянув це місто раніше, бо жодного разу не заблукав. Вражає.'::text),
(397716,44191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... este pueblo antes, porque no te perdiste ni una vez. Impresionante.'::text,'Habías recorrido'::text,'Estabas recorriendo'::text,'Has recorrido'::text,'Habías recorrido este pueblo antes, porque no te perdiste ni una vez. Impresionante.'::text),
(397715,44191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... cette ville avant, parce que tu ne t''es pas perdu une seule fois. Impressionnant.'::text,'avais visité'::text,'visitais'::text,'as visité'::text,'Tu avais visité cette ville avant, parce que tu ne t''es pas perdu une seule fois. Impressionnant.'::text),
(397718,44191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kasabayı daha önce ..., çünkü bir kez bile kaybolmadın. Etkileyici.'::text,'gezmiştin'::text,'geziyordun'::text,'gezdin'::text,'Bu kasabayı daha önce gezmiştin, çünkü bir kez bile kaybolmadın. Etkileyici.'::text),
(397719,44191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már korábban ... ezt a várost, mert egyszer sem tévedtél el. Lenyűgöző.'::text,'bejártad'::text,'jártad'::text,'bejártad'::text,'Már korábban bejártad ezt a várost, mert egyszer sem tévedtél el. Lenyűgöző.'::text),
(397722,44192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... sie die ganze Stadt erkundet haben. Eindeutig ein total entspannter Spaziergang mit dem Esel.'::text,'werden'::text,'werden'::text,'erkunden'::text,'Bis Mittag werden sie die ganze Stadt erkundet haben. Eindeutig ein total entspannter Spaziergang mit dem Esel.'::text),
(397726,44192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня вони ... все місто. Явно дуже розслаблена прогулянка з тим віслюком.'::text,'оглянуть'::text,'оглянуть'::text,'оглядають'::text,'До полудня вони оглянуть все місто. Явно дуже розслаблена прогулянка з тим віслюком.'::text),
(397725,44192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía ... todo el pueblo. Claramente un paseo muy relajado con ese burro.'::text,'habrán recorrido'::text,'recorrerán'::text,'recorren'::text,'Para el mediodía habrán recorrido todo el pueblo. Claramente un paseo muy relajado con ese burro.'::text),
(397724,44192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, ils ... toute la ville. Clairement une balade très détendue avec cet âne.'::text,'auront visité'::text,'visiteront'::text,'visitent'::text,'D''ici midi, ils auront visité toute la ville. Clairement une balade très détendue avec cet âne.'::text),
(397727,44192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bütün kasabayı ...; o eşekle belli ki çok rahat bir yürüyüş.'::text,'gezmiş olacaklar'::text,'gezecekler'::text,'geziyorlar'::text,'Öğlene kadar bütün kasabayı gezmiş olacaklar; o eşekle belli ki çok rahat bir yürüyüş.'::text),
(397728,44192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ... az egész várost. Egyértelműen nagyon laza séta azzal a szamárral.'::text,'bejárják'::text,'be fogják járni'::text,'járják'::text,'Délre bejárják az egész várost. Egyértelműen nagyon laza séta azzal a szamárral.'::text),
(348474,38720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um zwölf ... die Kuppel am selben Ort, weil Kuppeln sich nicht bewegen.'::text,'steht'::text,'steht'::text,'steht'::text,'Morgen um zwölf steht die Kuppel am selben Ort, weil Kuppeln sich nicht bewegen.'::text),
(348478,38720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні купол ... на тому самому місці, бо куполи не рухаються.'::text,'стоятиме'::text,'стоятиме'::text,'стоїть'::text,'Завтра опівдні купол стоятиме на тому самому місці, бо куполи не рухаються.'::text),
(348477,38720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía, la cúpula ... en el mismo sitio, porque las cúpulas no se mueven.'::text,'estará'::text,'estará'::text,'está'::text,'Mañana a mediodía, la cúpula estará en el mismo sitio, porque las cúpulas no se mueven.'::text),
(348476,38720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, le dôme ... au même endroit, parce que les dômes ne bougent pas.'::text,'sera'::text,'sera'::text,'est'::text,'Demain à midi, le dôme sera au même endroit, parce que les dômes ne bougent pas.'::text),
(348479,38720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen kubbe aynı yerde ..., çünkü kubbeler hareket etmez.'::text,'duruyor olacak'::text,'duracak'::text,'duruyor'::text,'Yarın öğlen kubbe aynı yerde duruyor olacak, çünkü kubbeler hareket etmez.'::text),
(348480,38720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a kupola ugyanott ..., mert a kupolák nem mozognak.'::text,'fog állni'::text,'fog állni'::text,'áll'::text,'Holnap délben a kupola ugyanott fog állni, mert a kupolák nem mozognak.'::text),
(348483,38721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, er ... ein Foto von der Kuppel, bevor er geht.'::text,'macht'::text,'macht'::text,'macht gerade'::text,'Ich glaube, er macht ein Foto von der Kuppel, bevor er geht.'::text),
(348487,38721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, він ... фото купола, перш ніж піти.'::text,'зробить'::text,'робитиме'::text,'робить'::text,'Думаю, він зробить фото купола, перш ніж піти.'::text),
(348486,38721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que ... una foto de la cúpula antes de irse.'::text,'hará'::text,'estará haciendo'::text,'está haciendo'::text,'Creo que hará una foto de la cúpula antes de irse.'::text),
(348485,38721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense qu''il ... une photo du dôme avant de partir.'::text,'prendra'::text,'sera en train de prendre'::text,'prend'::text,'Je pense qu''il prendra une photo du dôme avant de partir.'::text),
(348488,38721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence gitmeden önce kubbenin fotoğrafını ...'::text,'çekecek'::text,'çekiyor olacak'::text,'çekiyor'::text,'Bence gitmeden önce kubbenin fotoğrafını çekecek.'::text),
(348489,38721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem ... egy fotót a kupoláról, mielőtt elmegy.'::text,'csinál'::text,'csinálni fog'::text,'csinál éppen'::text,'Szerintem csinál egy fotót a kupoláról, mielőtt elmegy.'::text),
(348501,38723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er zur Kirche läuft, ... er die Kuppel aus der Nähe.'::text,'sieht'::text,'sähe'::text,'sah'::text,'Wenn er zur Kirche läuft, sieht er die Kuppel aus der Nähe.'::text),
(348505,38723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він дійде до церкви, то ... купол зблизька.'::text,'побачить'::text,'побачив би'::text,'бачив'::text,'Якщо він дійде до церкви, то побачить купол зблизька.'::text)
