from (values
(348504,38723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si camina hasta la iglesia, ... la cúpula de cerca.'::text,'verá'::text,'vería'::text,'vio'::text,'Si camina hasta la iglesia, verá la cúpula de cerca.'::text),
(348503,38723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il marche jusqu''à l''église, il ... le dôme de près.'::text,'verra'::text,'verrait'::text,'a vu'::text,'S''il marche jusqu''à l''église, il verra le dôme de près.'::text),
(348506,38723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kiliseye yürürse, kubbeyi yakından ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Kiliseye yürürse, kubbeyi yakından görecek.'::text),
(348507,38723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elsétál a templomig, közelről ... a kupolát.'::text,'látja majd'::text,'látná'::text,'látta'::text,'Ha elsétál a templomig, közelről látja majd a kupolát.'::text),
(348510,38724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Kuppel jemals einstürzen würde, ... Rom nie wieder dasselbe sein!'::text,'würde'::text,'wird'::text,'kann'::text,'Wenn diese Kuppel jemals einstürzen würde, würde Rom nie wieder dasselbe sein!'::text),
(348514,38724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби той купол колись обвалився, Рим ... вже ніколи таким, як раніше!'::text,'не був би'::text,'не буде'::text,'не може бути'::text,'Якби той купол колись обвалився, Рим не був би вже ніколи таким, як раніше!'::text),
(348513,38724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si esa cúpula se derrumbara algún día, Roma nunca ... la misma!'::text,'sería'::text,'será'::text,'puede ser'::text,'¡Si esa cúpula se derrumbara algún día, Roma nunca sería la misma!'::text),
(348512,38724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce dôme s''effondrait un jour, Rome ne ... plus jamais la même !'::text,'serait'::text,'sera'::text,'peut être'::text,'Si ce dôme s''effondrait un jour, Rome ne serait plus jamais la même !'::text),
(348515,38724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kubbe bir gün çökse, Roma bir daha asla eskisi gibi ...!'::text,'olmazdı'::text,'olmayacak'::text,'olamaz'::text,'O kubbe bir gün çökse, Roma bir daha asla eskisi gibi olmazdı!'::text),
(348516,38724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az a kupola valaha összeomlana, Róma soha többé ... ugyanaz!'::text,'nem lenne'::text,'nem lesz'::text,'nem lehet'::text,'Ha az a kupola valaha összeomlana, Róma soha többé nem lenne ugyanaz!'::text),
(348519,38725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Kuppel ... vor Jahrhunderten gebaut, und nichts hat sie je zerstört!'::text,'wurde'::text,'baute'::text,'wird'::text,'Diese Kuppel wurde vor Jahrhunderten gebaut, und nichts hat sie je zerstört!'::text),
(348523,38725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той купол ... століття тому, і ніщо ніколи його не зруйнувало!'::text,'був збудований'::text,'збудував'::text,'збудований'::text,'Той купол був збудований століття тому, і ніщо ніколи його не зруйнувало!'::text),
