(348521,38725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce dôme ... il y a des siècles, et rien ne l''a jamais détruit !'::text,'a été construit'::text,'a construit'::text,'est construit'::text,'Ce dôme a été construit il y a des siècles, et rien ne l''a jamais détruit !'::text),
(348524,38725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kubbe yüzyıllar önce ... ve hiçbir şey onu yok edemedi!'::text,'inşa edildi'::text,'inşa etti'::text,'inşa ediliyor'::text,'O kubbe yüzyıllar önce inşa edildi ve hiçbir şey onu yok edemedi!'::text),
(348525,38725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt a kupolát évszázadokkal ezelőtt ..., és soha semmi nem tudta lerombolni!'::text,'építették'::text,'építette'::text,'építik'::text,'Azt a kupolát évszázadokkal ezelőtt építették, és soha semmi nem tudta lerombolni!'::text),
(348528,38726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also er hat mir erzählt, dass er ein Fotobuch nur für diese Kuppel ...'::text,'gemacht hat'::text,'gemacht wurde'::text,'machend'::text,'Okay, also er hat mir erzählt, dass er ein Fotobuch nur für diese Kuppel gemacht hat.'::text),
(348532,38726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що ... фотокнигу спеціально для того купола.'::text,'зробив'::text,'був зроблений'::text,'роблячи'::text,'Коротше, він сказав мені, що зробив фотокнигу спеціально для того купола.'::text),
(348531,38726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que ... un fotolibro solo para esa cúpula.'::text,'hizo'::text,'fue hecho'::text,'haciendo'::text,'Vale, pues me dijo que hizo un fotolibro solo para esa cúpula.'::text),
(348530,38726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il m''a dit qu''il ... un livre photo rien que pour ce dôme.'::text,'a fait'::text,'a été fait'::text,'faisant'::text,'Bon, il m''a dit qu''il a fait un livre photo rien que pour ce dôme.'::text),
(348533,38726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, bana sırf o kubbe için bir fotoğraf kitabı ... söyledi.'::text,'yaptığını'::text,'yapıldığını'::text,'yaparak'::text,'Tamam, bana sırf o kubbe için bir fotoğraf kitabı yaptığını söyledi.'::text),
(348534,38726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy ... egy fotókönyvet csak arról a kupoláról.'::text,'csinált'::text,'készült'::text,'csinálva'::text,'Szóval azt mondta, hogy csinált egy fotókönyvet csak arról a kupoláról.'::text),
(348537,38727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, diese Kuppel ... die aus seinem Buch sein; er vergleicht sie ständig.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Hör zu, ich hab gehört, diese Kuppel muss die aus seinem Buch sein; er vergleicht sie ständig.'::text),
(348541,38727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що той купол ... бути тим самим, що в його книжці; він постійно їх порівнює.'::text,'мусить'::text,'не може'::text,'не мав би'::text,'Слухай, я чула, що той купол мусить бути тим самим, що в його книжці; він постійно їх порівнює.'::text),
(348540,38727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, he oído que esa cúpula ... ser la de su libro; no para de compararlas.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Escucha, he oído que esa cúpula debe de ser la de su libro; no para de compararlas.'::text),
(348539,38727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que ce dôme ... être celui de son livre ; il n''arrête pas de les comparer.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Écoute, j''ai entendu que ce dôme doit être celui de son livre ; il n''arrête pas de les comparer.'::text),
(348542,38727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki o kubbe onun kitabındaki kubbe ...; sürekli onları karşılaştırıyor.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Dinle, duydum ki o kubbe onun kitabındaki kubbe olmalı; sürekli onları karşılaştırıyor.'::text),
(348543,38727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, úgy hallottam, az a kupola ... az, ami a könyvében van; folyton összehasonlítja őket.'::text,'biztosan'::text,'nem lehet'::text,'nem kéne hogy legyen'::text,'Figyelj, úgy hallottam, az a kupola biztosan az, ami a könyvében van; folyton összehasonlítja őket.'::text),
(348546,38728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Kirche, auf ... Kuppel er die ganze Zeit starrt, ist echt ikonisch.'::text,'deren'::text,'die'::text,'welche'::text,'Bro, die Kirche, auf deren Kuppel er die ganze Zeit starrt, ist echt ikonisch.'::text),
(348550,38728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, церква, на ... купол він постійно витріщається, насправді культова.'::text,'чий'::text,'яку'::text,'який'::text,'Бро, церква, на чий купол він постійно витріщається, насправді культова.'::text),
(348549,38728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la iglesia a ... cúpula no para de mirar es bastante icónica.'::text,'cuya'::text,'la cual'::text,'quien'::text,'Tío, la iglesia a cuya cúpula no para de mirar es bastante icónica.'::text),
(348548,38728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''église ... il fixe le dôme en boucle est carrément iconique.'::text,'dont'::text,'qui'::text,'lequel'::text,'Frère, l''église dont il fixe le dôme en boucle est carrément iconique.'::text),
(348551,38728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kubbesine sürekli ... kilise bayağı ikonik.'::text,'baktığı'::text,'baktığı'::text,'bakan'::text,'Kanka, kubbesine sürekli baktığı kilise bayağı ikonik.'::text),
(348552,38728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a templom, ... kupoláját folyton bámulja, elég ikonikus.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'Tesó, a templom, amelynek a kupoláját folyton bámulja, elég ikonikus.'::text),
(348555,38729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er meinte, er ... die Kuppel vorher noch nie in echt gesehen, echt jetzt.'::text,'hatte'::text,'hat'::text,'sieht'::text,'Alter, er meinte, er hatte die Kuppel vorher noch nie in echt gesehen, echt jetzt.'::text),
(348559,38729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він сказав, що ще ніколи ... той купол наживо, реально.'::text,'не бачив'::text,'не бачив'::text,'не бачить'::text,'Чувак, він сказав, що ще ніколи не бачив той купол наживо, реально.'::text),
(348558,38729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que nunca ... esa cúpula en persona, en serio.'::text,'había visto'::text,'ha visto'::text,'ve'::text,'Tío, dijo que nunca había visto esa cúpula en persona, en serio.'::text),
(348557,38729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il a dit qu''il ... ce dôme en vrai avant, sérieux.'::text,'n''avait jamais vu'::text,'n''a jamais vu'::text,'ne voit jamais'::text,'Mec, il a dit qu''il n''avait jamais vu ce dôme en vrai avant, sérieux.'::text),
(348560,38729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kubbeyi daha önce hiç gerçekte ... söyledi, cidden.'::text,'görmediğini'::text,'görmediğini'::text,'görmüyor olduğunu'::text,'Kanka, o kubbeyi daha önce hiç gerçekte görmediğini söyledi, cidden.'::text),
(348561,38729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, azt mondta, hogy még soha ... élőben azt a kupolát, komolyan.'::text,'nem látta'::text,'nem látta'::text,'nem látja'::text,'Haver, azt mondta, hogy még soha nem látta élőben azt a kupolát, komolyan.'::text),
(348564,38730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dieser Reise zur Kuppel ... er ein Reisebudget von 0 Euro.'::text,'hatte früher'::text,'hätte'::text,'war gewohnt'::text,'Vor dieser Reise zur Kuppel hatte früher er ein Reisebudget von 0 Euro.'::text),
(348568,38730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цієї поїздки до купола в нього ... бюджет на подорожі 0 євро.'::text,'колись був'::text,'був би'::text,'звично був'::text,'До цієї поїздки до купола в нього колись був бюджет на подорожі 0 євро.'::text),
(348567,38730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de este viaje a la cúpula, ... un presupuesto de viaje de 0 euros.'::text,'solía tener'::text,'tendría'::text,'estaba acostumbrado a tener'::text,'Antes de este viaje a la cúpula, solía tener un presupuesto de viaje de 0 euros.'::text),
(348566,38730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant ce voyage vers le dôme, il ... un budget voyage de 0 euro.'::text,'avait'::text,'aurait'::text,'était habitué à avoir'::text,'Avant ce voyage vers le dôme, il avait un budget voyage de 0 euro.'::text),
(348569,38730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kubbeye bu geziden önce 0 euroluk bir seyahat bütçesi ...'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Kubbeye bu geziden önce 0 euroluk bir seyahat bütçesi vardı.'::text),
(348570,38730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kupolához tett út előtt 0 eurós utazási kerete ...'::text,'volt'::text,'lett volna'::text,'szokott lenni'::text,'A kupolához tett út előtt 0 eurós utazási kerete volt.'::text),
(336099,37345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zopf läuft direkt über den Scheitel, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Der Zopf läuft direkt über den Scheitel, oder?'::text),
(336103,37345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коса йде прямо через маківку, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Коса йде прямо через маківку, правда?'::text),
(336102,37345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La trenza pasa justo por encima de la cabeza, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La trenza pasa justo por encima de la cabeza, ¿verdad?'::text),
(336101,37345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tresse passe pile sur le dessus de la tête, ... ?'::text,'non'::text,'non'::text,'non'::text,'La tresse passe pile sur le dessus de la tête, non ?'::text),
(336104,37345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örgü tam tepeden geçiyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Örgü tam tepeden geçiyor, değil mi?'::text),
(336105,37345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fonat pont a fejtetőn fut végig, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A fonat pont a fejtetőn fut végig, ugye?'::text),
(336108,37346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stylistin hat sich mit dem Zopf nicht beeilt, und ... die Kundin. Wirklich ein schneller Besuch.'::text,'genauso wenig'::text,'genauso'::text,'genauso wenig'::text,'Die Stylistin hat sich mit dem Zopf nicht beeilt, und genauso wenig die Kundin. Wirklich ein schneller Besuch.'::text),
(336112,37346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перукарка не поспішала з косою, ... клієнтка. Справді швидкий візит.'::text,'як і'::text,'так само як і'::text,'як і'::text,'Перукарка не поспішала з косою, як і клієнтка. Справді швидкий візит.'::text),
(336111,37346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estilista no se ha dado prisa con la trenza, y ... la clienta. Una visita rapidísima, vamos.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'La estilista no se ha dado prisa con la trenza, y tampoco la clienta. Una visita rapidísima, vamos.'::text),
(336110,37346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coiffeuse ne s''est pas pressée pour la tresse, ... la cliente. Vraiment une visite express.'::text,'pas plus que'::text,'tout comme'::text,'pas plus que'::text,'La coiffeuse ne s''est pas pressée pour la tresse, pas plus que la cliente. Vraiment une visite express.'::text),
(336113,37346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaför örgüde acele etmedi, müşteri ... acele etmedi. Gerçekten çok hızlı bir ziyaret.'::text,'de'::text,'de'::text,'de'::text,'Kuaför örgüde acele etmedi, müşteri de acele etmedi. Gerçekten çok hızlı bir ziyaret.'::text),
(336114,37346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fodrász nem sietett a fonattal, és ... az ügyfél. Tényleg villámgyors látogatás.'::text,'ugyanígy nem'::text,'ugyanígy'::text,'ugyanígy nem'::text,'A fodrász nem sietett a fonattal, és ugyanígy nem az ügyfél. Tényleg villámgyors látogatás.'::text),
(336117,37347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stylistin ... schon stundenlang an dem Zopf gearbeitet, bevor die Kundin endlich aufstand. Ein kleines bisschen lang.'::text,'hatte'::text,'hat'::text,'war'::text,'Die Stylistin hatte schon stundenlang an dem Zopf gearbeitet, bevor die Kundin endlich aufstand. Ein kleines bisschen lang.'::text),
(336121,37347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перукарка ... над тією косою годинами, поки клієнтка нарешті не встала. Трішки довгувато.'::text,'працювала'::text,'працює'::text,'працювала'::text,'Перукарка працювала над тією косою годинами, поки клієнтка нарешті не встала. Трішки довгувато.'::text),
(336120,37347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estilista ... en esa trenza durante horas antes de que la clienta por fin se levantara. Un pelín largo.'::text,'había estado trabajando'::text,'ha estado trabajando'::text,'estaba trabajando'::text,'La estilista había estado trabajando en esa trenza durante horas antes de que la clienta por fin se levantara. Un pelín largo.'::text),
(336119,37347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coiffeuse ... sur cette tresse pendant des heures avant que la cliente se lève enfin. Légèrement long.'::text,'avait travaillé'::text,'a travaillé'::text,'travaillait'::text,'La coiffeuse avait travaillé sur cette tresse pendant des heures avant que la cliente se lève enfin. Légèrement long.'::text),
(336122,37347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri sonunda ayağa kalkana kadar kuaför o örgü üzerinde saatlerce ...; birazcık uzun.'::text,'çalışmıştı'::text,'çalıştı'::text,'çalışıyordu'::text,'Müşteri sonunda ayağa kalkana kadar kuaför o örgü üzerinde saatlerce çalışmıştı; birazcık uzun.'::text),
(336123,37347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fodrász órákig ... azon a fonaton, mielőtt az ügyfél végre felállt. Kicsit hosszú.'::text,'dolgozott'::text,'dolgozik'::text,'dolgozott'::text,'A fodrász órákig dolgozott azon a fonaton, mielőtt az ügyfél végre felállt. Kicsit hosszú.'::text),
(336126,37348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis sie ihre Haare schwingt, wird die Stylistin den Zopf ..., ohne Witz.'::text,'fertig gemacht haben'::text,'fertig machen'::text,'fertig machen'::text,'Bro, bis sie ihre Haare schwingt, wird die Stylistin den Zopf fertig gemacht haben, ohne Witz.'::text),
(336130,37348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки вона махне волоссям, перукарка вже ... косу, без жартів.'::text,'закінчить'::text,'закінчить'::text,'закінчуватиме'::text,'Бро, поки вона махне волоссям, перукарка вже закінчить косу, без жартів.'::text),
(336129,37348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando ella mueva el pelo, la estilista ... la trenza, sin mentir.'::text,'habrá terminado'::text,'terminará'::text,'estará terminando'::text,'Tío, para cuando ella mueva el pelo, la estilista habrá terminado la trenza, sin mentir.'::text),
(336128,37348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le temps qu''elle fasse voler ses cheveux, la coiffeuse ... la tresse, sans mentir.'::text,'aura fini'::text,'finira'::text,'sera en train de finir'::text,'Frère, le temps qu''elle fasse voler ses cheveux, la coiffeuse aura fini la tresse, sans mentir.'::text),
(336131,37348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o saçını savurana kadar kuaför örgüyü ..., yalan yok.'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor olacak'::text,'Kanka, o saçını savurana kadar kuaför örgüyü bitirmiş olacak, yalan yok.'::text),
(336132,37348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire meglendíti a haját, a fodrász ... a fonatot, nem kamu.'::text,'befejezi'::text,'be fogja fejezni'::text,'fejezi be éppen'::text,'Tesó, mire meglendíti a haját, a fodrász befejezi a fonatot, nem kamu.'::text),
(336135,37349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis Mittag ... die Stylistin schon so drei Stunden an diesem Zopf geflochten, echt jetzt.'::text,'hat'::text,'wird'::text,'flicht'::text,'Yo, bis Mittag hat die Stylistin schon so drei Stunden an diesem Zopf geflochten, echt jetzt.'::text),
(336139,37349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, до полудня перукарка ... цю косу вже години зо три, реально.'::text,'плестиме'::text,'плестиме'::text,'сплете'::text,'Йо, до полудня перукарка плестиме цю косу вже години зо три, реально.'::text),
(336138,37349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, para el mediodía la estilista ... esta trenza durante como tres horas, en serio.'::text,'habrá estado haciendo'::text,'estará haciendo'::text,'hará'::text,'Ey, para el mediodía la estilista habrá estado haciendo esta trenza durante como tres horas, en serio.'::text),
(336137,37349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, à midi, ça fera genre trois heures que la coiffeuse ... cette tresse, sérieux.'::text,'tresse'::text,'tresse'::text,'tresse'::text,'Yo, à midi, ça fera genre trois heures que la coiffeuse tresse cette tresse, sérieux.'::text),
(336140,37349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, öğlene kadar kuaför bu örgüyü üç saat gibi ..., cidden.'::text,'örüyor olacak'::text,'örüyor olacak'::text,'örecek'::text,'Yo, öğlene kadar kuaför bu örgüyü üç saat gibi örüyor olacak, cidden.'::text),
(336141,37349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, délre a fodrász már vagy három órája ... ezt a fonatot, komolyan.'::text,'fonja'::text,'fonja majd'::text,'be fogja fonni'::text,'Figyu, délre a fodrász már vagy három órája fonja ezt a fonatot, komolyan.'::text),
(336153,37351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Stylistin den Zopf nicht geflochten hätte, ... die langen Haare jetzt offen herunter.'::text,'hingen'::text,'hätten gehangen'::text,'werden hängen'::text,'Wenn die Stylistin den Zopf nicht geflochten hätte, hingen die langen Haare jetzt offen herunter.'::text),
(336157,37351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби перукарка не заплела косу, довге волосся зараз ... розпущеним.'::text,'висіло б'::text,'висіло б'::text,'висітиме'::text,'Якби перукарка не заплела косу, довге волосся зараз висіло б розпущеним.'::text),
(336156,37351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la estilista no hubiera hecho la trenza, el pelo largo ... suelto ahora.'::text,'estaría colgando'::text,'habría colgado'::text,'colgará'::text,'Si la estilista no hubiera hecho la trenza, el pelo largo estaría colgando suelto ahora.'::text),
(336155,37351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la coiffeuse n''avait pas fait la tresse, les longs cheveux ... librement maintenant.'::text,'pendraient'::text,'auraient pendu'::text,'pendront'::text,'Si la coiffeuse n''avait pas fait la tresse, les longs cheveux pendraient librement maintenant.'::text),
(336158,37351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaför örgüyü örmeseydi, uzun saçlar şimdi serbestçe ...'::text,'sarkıyor olurdu'::text,'sarkmış olurdu'::text,'sarkacak'::text,'Kuaför örgüyü örmeseydi, uzun saçlar şimdi serbestçe sarkıyor olurdu.'::text),
(336159,37351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fodrász nem fonta volna be, a hosszú haj most kiengedve ...'::text,'lógna'::text,'lógott volna'::text,'lógni fog'::text,'Ha a fodrász nem fonta volna be, a hosszú haj most kiengedve lógna.'::text),
(336162,37352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zöpfe dieser Länge ... bekanntermaßen mehrere Stunden Arbeit.'::text,'erfordern'::text,'erfordernd'::text,'erfordern'::text,'Zöpfe dieser Länge erfordern bekanntermaßen mehrere Stunden Arbeit.'::text),
(336166,37352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що коси такої довжини ... кількох годин роботи.'::text,'потребують'::text,'потребуючи'::text,'потребують'::text,'Відомо, що коси такої довжини потребують кількох годин роботи.'::text),
(336165,37352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que las trenzas de esta longitud ... varias horas de trabajo.'::text,'requieren'::text,'requiriendo'::text,'requieren'::text,'Se sabe que las trenzas de esta longitud requieren varias horas de trabajo.'::text),
(336164,37352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tresses de cette longueur sont connues pour ... plusieurs heures de travail.'::text,'nécessiter'::text,'nécessitant'::text,'nécessitent'::text,'Les tresses de cette longueur sont connues pour nécessiter plusieurs heures de travail.'::text),
(336167,37352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu uzunluktaki örgülerin birkaç saatlik emek ... bilinir.'::text,'gerektirdiği'::text,'gerektirerek'::text,'gerektirir'::text,'Bu uzunluktaki örgülerin birkaç saatlik emek gerektirdiği bilinir.'::text),
(336168,37352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ilyen hosszú fonatokról ismert, hogy több órányi munkát ...'::text,'igényelnek'::text,'igényelve'::text,'igényelnek'::text,'Az ilyen hosszú fonatokról ismert, hogy több órányi munkát igényelnek.'::text),
(336171,37353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kundin dankte der Stylistin dafür, den absolut perfektesten Zopf aller Zeiten ...!'::text,'gezaubert zu haben'::text,'zu zaubern'::text,'zaubern'::text,'Die Kundin dankte der Stylistin dafür, den absolut perfektesten Zopf aller Zeiten gezaubert zu haben!'::text),
(336175,37353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнтка подякувала перукарці за ... абсолютно найідеальнішої коси в історії!'::text,'створення'::text,'створити'::text,'створити'::text,'Клієнтка подякувала перукарці за створення абсолютно найідеальнішої коси в історії!'::text),
(336174,37353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La clienta le dio las gracias a la estilista por ... la trenza más absolutamente perfecta de la historia!'::text,'haber creado'::text,'crear'::text,'crear'::text,'¡La clienta le dio las gracias a la estilista por haber creado la trenza más absolutamente perfecta de la historia!'::text),
(336173,37353,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cliente a remercié la coiffeuse ... la tresse la plus absolument parfaite de tous les temps !'::text,'d''avoir créé'::text,'de créer'::text,'créer'::text,'La cliente a remercié la coiffeuse d''avoir créé la tresse la plus absolument parfaite de tous les temps !'::text),
(336176,37353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri, gelmiş geçmiş en kusursuz örgüyü ... için kuaföre teşekkür etti!'::text,'yarattığı'::text,'yaratmak'::text,'yarat'::text,'Müşteri, gelmiş geçmiş en kusursuz örgüyü yarattığı için kuaföre teşekkür etti!'::text),
(336177,37353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyfél megköszönte a fodrásznak, hogy ... minden idők abszolút legtökéletesebb fonatát!'::text,'elkészítette'::text,'elkészíteni'::text,'elkészít'::text,'Az ügyfél megköszönte a fodrásznak, hogy elkészítette minden idők abszolút legtökéletesebb fonatát!'::text),
(336180,37354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stylistin ... jahrelange Übung gebraucht haben, um einen so langen Zopf zu flechten.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Die Stylistin muss jahrelange Übung gebraucht haben, um einen so langen Zopf zu flechten.'::text),
(336184,37354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перукарці ... роки практики, щоб заплести таку довгу косу.'::text,'напевно, знадобилися'::text,'не могли знадобитися'::text,'не мали б знадобитися'::text,'Перукарці напевно, знадобилися роки практики, щоб заплести таку довгу косу.'::text),
(336183,37354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estilista ... años de práctica para hacer una trenza tan larga.'::text,'debe de haber necesitado'::text,'no puede haber necesitado'::text,'no debería haber necesitado'::text,'La estilista debe de haber necesitado años de práctica para hacer una trenza tan larga.'::text),
(336182,37354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coiffeuse ... d''années de pratique pour tresser une natte aussi longue.'::text,'a dû avoir besoin'::text,'n''a pas pu avoir besoin'::text,'n''aurait pas dû avoir besoin'::text,'La coiffeuse a dû avoir besoin d''années de pratique pour tresser une natte aussi longue.'::text),
(336185,37354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaför bu kadar uzun bir örgü örmek için yıllarca pratiğe ...'::text,'ihtiyaç duymuş olmalı'::text,'ihtiyaç duymuş olamaz'::text,'ihtiyaç duymamalıydı'::text,'Kuaför bu kadar uzun bir örgü örmek için yıllarca pratiğe ihtiyaç duymuş olmalı.'::text),
(336186,37354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fodrásznak ... évekig tartó gyakorlásra volt szüksége, hogy ilyen hosszú fonatot fonjon.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kellett volna, hogy'::text,'A fodrásznak biztosan évekig tartó gyakorlásra volt szüksége, hogy ilyen hosszú fonatot fonjon.'::text),
(343083,38121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... einen geräumigeren Flur gesehen. Das Fahrrad passt perfekt rein, natürlich.'::text,'habe ich'::text,'ich habe'::text,'habe ich'::text,'Noch nie habe ich einen geräumigeren Flur gesehen. Das Fahrrad passt perfekt rein, natürlich.'::text),
(343087,38121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... просторішого коридору. Велосипед поміщається ідеально, звісно.'::text,'не бачив я'::text,'я не бачив'::text,'не бачив я'::text,'Ніколи не бачив я просторішого коридору. Велосипед поміщається ідеально, звісно.'::text),
(343086,38121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... un pasillo más espacioso. La bici cabe perfectamente, obviamente.'::text,'he visto'::text,'he visto'::text,'vi'::text,'Nunca he visto un pasillo más espacioso. La bici cabe perfectamente, obviamente.'::text),
(343085,38121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... un couloir plus spacieux. Le vélo rentre parfaitement, évidemment.'::text,'je n''ai vu'::text,'j''ai vu'::text,'je vis'::text,'Jamais je n''ai vu un couloir plus spacieux. Le vélo rentre parfaitement, évidemment.'::text),
(343088,38121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç bu kadar geniş bir koridor ...; bisiklet de mükemmel sığıyor, tabii ki.'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hiç bu kadar geniş bir koridor görmedim; bisiklet de mükemmel sığıyor, tabii ki.'::text),
(343089,38121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... tágasabb folyosót. A bicikli tökéletesen elfér, nyilván.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam tágasabb folyosót. A bicikli tökéletesen elfér, nyilván.'::text),
(343092,38122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie muss jemanden dazu bringen, das Rad aus dem Flur ..., echt jetzt.'::text,'zu schieben'::text,'schieben'::text,'schiebend'::text,'Bro, sie muss jemanden dazu bringen, das Rad aus dem Flur zu schieben, echt jetzt.'::text),
(343096,38122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, їй треба когось підбити ... той велик з коридору, реально.'::text,'винести'::text,'винести'::text,'виносячи'::text,'Бро, їй треба когось підбити винести той велик з коридору, реально.'::text),
(343095,38122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tiene que conseguir que alguien ... esa bici del pasillo, en serio.'::text,'saque'::text,'sacar'::text,'sacando'::text,'Tío, tiene que conseguir que alguien saque esa bici del pasillo, en serio.'::text),
(343094,38122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle doit trouver quelqu''un pour ... ce vélo du couloir, sérieux.'::text,'sortir'::text,'sortir'::text,'sortant'::text,'Frère, elle doit trouver quelqu''un pour sortir ce vélo du couloir, sérieux.'::text),
(343097,38122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bisikleti koridordan birine ... lazım, cidden.'::text,'çıkarttırması'::text,'çıkarması'::text,'çıkarırken'::text,'Kanka, o bisikleti koridordan birine çıkarttırması lazım, cidden.'::text),
(343098,38122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, meg kell kérnie valakit, hogy ... azt a biciklit a folyosóról, komolyan.'::text,'vigye ki'::text,'kivinni'::text,'kivive'::text,'Tesó, meg kell kérnie valakit, hogy vigye ki azt a biciklit a folyosóról, komolyan.'::text),
(343101,38123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mann, sie wünscht sich, der Flur ... breiter, ohne Witz.'::text,'wäre'::text,'ist'::text,'wird'::text,'Mann, sie wünscht sich, der Flur wäre breiter, ohne Witz.'::text),
(343105,38123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона хотіла б, щоб коридор ... ширшим, чесно.'::text,'був'::text,'є'::text,'буде'::text,'Чувак, вона хотіла б, щоб коридор був ширшим, чесно.'::text),
(343104,38123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, a ella le gustaría que el pasillo ... más ancho, sin mentir.'::text,'fuera'::text,'es'::text,'será'::text,'Tío, a ella le gustaría que el pasillo fuera más ancho, sin mentir.'::text),
(343103,38123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle aimerait que le couloir ... plus large, sans mentir.'::text,'soit'::text,'est'::text,'sera'::text,'Mec, elle aimerait que le couloir soit plus large, sans mentir.'::text),
(343106,38123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, koridorun daha geniş ... istiyor, yalan yok.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Kanka, koridorun daha geniş olmasını istiyor, yalan yok.'::text),
(343107,38123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, azt szeretné, ha a folyosó szélesebb ..., nem kamu.'::text,'lenne'::text,NULL::text,'lesz'::text,'Haver, azt szeretné, ha a folyosó szélesebb lenne, nem kamu.'::text),
(343110,38124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Flur, ... Boden 40 Paar Schuhe fasst, braucht ein Stauraum-Budget.'::text,'dessen'::text,'der'::text,'wo'::text,'Der Flur, dessen Boden 40 Paar Schuhe fasst, braucht ein Stauraum-Budget.'::text),
(343114,38124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коридор, ... підлога вміщує 40 пар взуття, потребує бюджету на зберігання.'::text,'чия'::text,'який'::text,'де'::text,'Коридор, чия підлога вміщує 40 пар взуття, потребує бюджету на зберігання.'::text),
(343113,38124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pasillo, ... suelo alberga 40 pares de zapatos, necesita un presupuesto de almacenaje.'::text,'cuyo'::text,'que'::text,'donde'::text,'El pasillo, cuyo suelo alberga 40 pares de zapatos, necesita un presupuesto de almacenaje.'::text),
(343112,38124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le couloir, ... le sol accueille 40 paires de chaussures, a besoin d''un budget rangement.'::text,'dont'::text,'qui'::text,'où'::text,'Le couloir, dont le sol accueille 40 paires de chaussures, a besoin d''un budget rangement.'::text),
(343115,38124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zemini 40 çift ayakkabı ... koridorun bir depolama bütçesine ihtiyacı var.'::text,'alan'::text,'alan'::text,'alan'::text,'Zemini 40 çift ayakkabı alan koridorun bir depolama bütçesine ihtiyacı var.'::text),
(343116,38124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyosónak, ... padlóján 40 pár cipő fér el, tárolási keret kell.'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'A folyosónak, amelynek a padlóján 40 pár cipő fér el, tárolási keret kell.'::text),
(343119,38125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder muss sich in ... dieser Wohnung am Fahrrad vorbeiquetschen.'::text,'dem Flur'::text,'einem Flur'::text,'Flur'::text,'Jeder muss sich in dem Flur dieser Wohnung am Fahrrad vorbeiquetschen.'::text),
(343123,38125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усім доводиться протискатися повз велосипед у ... цієї квартири.'::text,'коридорі'::text,'коридорі'::text,'коридорі'::text,'Усім доводиться протискатися повз велосипед у коридорі цієї квартири.'::text),
(343122,38125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el mundo tiene que pasar apretado junto a la bici en ... de este piso.'::text,'el pasillo'::text,'un pasillo'::text,'pasillo'::text,'Todo el mundo tiene que pasar apretado junto a la bici en el pasillo de este piso.'::text),
(343121,38125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde doit se faufiler devant le vélo dans ... de cet appart.'::text,'le couloir'::text,'un couloir'::text,'couloir'::text,'Tout le monde doit se faufiler devant le vélo dans le couloir de cet appart.'::text),
(343124,38125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes bu dairenin ... bisikletin yanından sıkışarak geçmek zorunda.'::text,'koridorunda'::text,'bir koridorunda'::text,'koridorunda'::text,'Herkes bu dairenin koridorunda bisikletin yanından sıkışarak geçmek zorunda.'::text),
(343125,38125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a lakásnak a ... mindenkinek el kell préselődnie a bicikli mellett.'::text,'folyosóján'::text,'egy folyosóján'::text,'folyosóján'::text,'Ennek a lakásnak a folyosóján mindenkinek el kell préselődnie a bicikli mellett.'::text),
(343128,38126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrrad bleibt ... des offensichtlichen Hindernisses, das es verursacht, im Flur.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Das Fahrrad bleibt trotz des offensichtlichen Hindernisses, das es verursacht, im Flur.'::text),
(343132,38126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипед залишається в коридорі ... перешкоду, яку він очевидно створює.'::text,'попри'::text,'хоча'::text,'через'::text,'Велосипед залишається в коридорі попри перешкоду, яку він очевидно створює.'::text),
(343131,38126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bicicleta permanece en el pasillo ... la obstrucción que evidentemente causa.'::text,'a pesar de'::text,'aunque'::text,'debido a'::text,'La bicicleta permanece en el pasillo a pesar de la obstrucción que evidentemente causa.'::text),
(343130,38126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vélo reste dans le couloir ... l''obstruction qu''il cause manifestement.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'Le vélo reste dans le couloir malgré l''obstruction qu''il cause manifestement.'::text),
(343133,38126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisiklet, açıkça yol açtığı tıkanıklığa ... koridorda kalmaya devam ediyor.'::text,'rağmen'::text,'olsa da'::text,'nedeniyle'::text,'Bisiklet, açıkça yol açtığı tıkanıklığa rağmen koridorda kalmaya devam ediyor.'::text),
(343134,38126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kerékpár a nyilvánvalóan okozott akadály ... a folyosón marad.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A kerékpár a nyilvánvalóan okozott akadály ellenére a folyosón marad.'::text),
(343146,38128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit das Fahrrad da ist, ... niemand ohne Katastrophe durch diesen Flur gekommen!'::text,'ist'::text,'kommt'::text,'kommt gerade'::text,'Seit das Fahrrad da ist, ist niemand ohne Katastrophe durch diesen Flur gekommen!'::text),
(343150,38128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відколи з''явився велосипед, ніхто ... цим коридором без катастрофи!'::text,'не пройшов'::text,'не проходить'::text,'не проходить'::text,'Відколи з''явився велосипед, ніхто не пройшов цим коридором без катастрофи!'::text),
(343149,38128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desde que llegó la bici, nadie ... este pasillo sin un desastre!'::text,'ha cruzado'::text,'cruza'::text,'está cruzando'::text,'¡Desde que llegó la bici, nadie ha cruzado este pasillo sin un desastre!'::text),
(343148,38128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis que le vélo est là, personne ... ce couloir sans catastrophe !'::text,'n''a traversé'::text,'ne traverse'::text,'n''est en train de traverser'::text,'Depuis que le vélo est là, personne n''a traversé ce couloir sans catastrophe !'::text),
(343151,38128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisiklet geldiğinden beri kimse bu koridordan felaketsiz ...!'::text,'geçmedi'::text,'geçmiyor'::text,'geçmiyor'::text,'Bisiklet geldiğinden beri kimse bu koridordan felaketsiz geçmedi!'::text),
(343152,38128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amióta itt a bicikli, senki nem ... át ezen a folyosón katasztrófa nélkül!'::text,'jutott'::text,'jut'::text,'jut éppen'::text,'Amióta itt a bicikli, senki nem jutott át ezen a folyosón katasztrófa nélkül!'::text),
(343155,38129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Männer den Karton reintrugen, ... jemand das Fahrrad im Flur stehen lassen.'::text,'hatte'::text,'hat'::text,'lässt'::text,'Bevor die Männer den Karton reintrugen, hatte jemand das Fahrrad im Flur stehen lassen.'::text),
(343159,38129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж чоловіки занесли коробку, хтось ... велосипед у коридорі.'::text,'залишив'::text,'залишив'::text,'залишає'::text,'Перш ніж чоловіки занесли коробку, хтось залишив велосипед у коридорі.'::text),
(343158,38129,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que los hombres metieran la caja, alguien ... la bici en el pasillo.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Antes de que los hombres metieran la caja, alguien había dejado la bici en el pasillo.'::text),
(343157,38129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que les hommes rentrent le carton, quelqu''un ... le vélo dans le couloir.'::text,'avait laissé'::text,'a laissé'::text,'laisse'::text,'Avant que les hommes rentrent le carton, quelqu''un avait laissé le vélo dans le couloir.'::text),
(343160,38129,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar kutuyu içeri taşımadan önce biri bisikleti koridorda ...'::text,'bırakmıştı'::text,'bıraktı'::text,'bırakıyor'::text,'Adamlar kutuyu içeri taşımadan önce biri bisikleti koridorda bırakmıştı.'::text),
(343161,38129,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a férfiak behozták a dobozt, valaki ... a biciklit a folyosón.'::text,'otthagyta'::text,'otthagyta'::text,'otthagyja'::text,'Mielőtt a férfiak behozták a dobozt, valaki otthagyta a biciklit a folyosón.'::text),
(343164,38130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächste Woche wird die Familie das Fahrrad aus dem Flur ...'::text,'geschafft haben'::text,'schaffen'::text,'schafft'::text,'Bis nächste Woche wird die Familie das Fahrrad aus dem Flur geschafft haben.'::text),
(343168,38130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного тижня родина ... велосипед із коридору.'::text,'прибере'::text,'прибере'::text,'прибирає'::text,'До наступного тижня родина прибере велосипед із коридору.'::text),
(343167,38130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la semana que viene, la familia ... la bici del pasillo.'::text,'habrá sacado'::text,'sacará'::text,'saca'::text,'Para la semana que viene, la familia habrá sacado la bici del pasillo.'::text),
(343166,38130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la semaine prochaine, la famille ... le vélo du couloir.'::text,'aura sorti'::text,'sortira'::text,'sort'::text,'D''ici la semaine prochaine, la famille aura sorti le vélo du couloir.'::text),
(343169,38130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek haftaya kadar aile bisikleti koridordan ...'::text,'çıkarmış olacak'::text,'çıkaracak'::text,'çıkarıyor'::text,'Gelecek haftaya kadar aile bisikleti koridordan çıkarmış olacak.'::text),
(343170,38130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hétre a család ... a biciklit a folyosóról.'::text,'kiviszi'::text,'ki fogja vinni'::text,'viszi ki'::text,'Jövő hétre a család kiviszi a biciklit a folyosóról.'::text),
(375987,41777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um diese Zeit ... er wieder Pfosten in den Boden, ohne Witz.'::text,'haut'::text,'haut'::text,'haut'::text,'Bro, morgen um diese Zeit haut er wieder Pfosten in den Boden, ohne Witz.'::text),
(375991,41777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра в цей час він знову ... стовпчики в землю, без жартів.'::text,'забиватиме'::text,'заб''є'::text,'забиває'::text,'Бро, завтра в цей час він знову забиватиме стовпчики в землю, без жартів.'::text),
(375990,41777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora ... postes en el suelo otra vez, sin mentir.'::text,'estará clavando'::text,'clavará'::text,'clava'::text,'Tío, mañana a esta hora estará clavando postes en el suelo otra vez, sin mentir.'::text),
(375989,41777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, demain à cette heure-ci, il ... des poteaux dans le sol, encore une fois, sans mentir.'::text,'sera en train d''enfoncer'::text,'enfoncera'::text,'enfonce'::text,'Frère, demain à cette heure-ci, il sera en train d''enfoncer des poteaux dans le sol, encore une fois, sans mentir.'::text),
(375992,41777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte yine yere kazık ..., yalan yok.'::text,'çakıyor olacak'::text,'çakacak'::text,'çakar'::text,'Kanka, yarın bu saatte yine yere kazık çakıyor olacak, yalan yok.'::text),
(375993,41777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint cölöpöket ... a földbe, nem kamu.'::text,'fog verni'::text,'ver majd'::text,'ver'::text,'Tesó, holnap ilyenkor megint cölöpöket fog verni a földbe, nem kamu.'::text),
(375996,41778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, ich ... dir den Pfosten, lass mich helfen.'::text,'halte'::text,'halte'::text,'halte gerade'::text,'Nee Bro, ich halte dir den Pfosten, lass mich helfen.'::text),
(376000,41778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, я ... тобі цей стовпчик, дай допоможу.'::text,'потримаю'::text,'триматиму'::text,'тримаю'::text,'Не, бро, я потримаю тобі цей стовпчик, дай допоможу.'::text),
(375999,41778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, tío, yo te ... el poste, déjame ayudar.'::text,'sujeto'::text,'estaré sujetando'::text,'estoy sujetando'::text,'Nah, tío, yo te sujeto el poste, déjame ayudar.'::text),
(375998,41778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, je te ... ce poteau, laisse-moi aider.'::text,'tiens'::text,'tiendrai'::text,'suis en train de tenir'::text,'Nan frère, je te tiens ce poteau, laisse-moi aider.'::text),
(376001,41778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o kazığı ben sana ..., bırak yardım edeyim.'::text,'tutarım'::text,'tutuyor olacağım'::text,'tutuyorum'::text,'Yok kanka, o kazığı ben sana tutarım, bırak yardım edeyim.'::text),
(376002,41778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, tesó, én ... neked azt a cölöpöt, hadd segítsek.'::text,'megtartom'::text,'tartani fogom'::text,'tartom'::text,'Ne már, tesó, én megtartom neked azt a cölöpöt, hadd segítsek.'::text),
(376005,41779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Pfosten 50 Zentimeter tief ..., erreicht der Zaun das Ziel.'::text,'steckt'::text,'steckte'::text,'stecken wird'::text,'Wenn ein Pfosten 50 Zentimeter tief steckt, erreicht der Zaun das Ziel.'::text),
(376009,41779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо стовпчик ... на 50 сантиметрів у глибину, паркан виконує план.'::text,'заходить'::text,'зайшов'::text,'зайде'::text,'Якщо стовпчик заходить на 50 сантиметрів у глибину, паркан виконує план.'::text),
(376008,41779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un poste ... 50 centímetros de profundidad, la valla cumple el objetivo.'::text,'entra'::text,'entró'::text,'entrará'::text,'Si un poste entra 50 centímetros de profundidad, la valla cumple el objetivo.'::text),
(376007,41779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un poteau ... à 50 centimètres de profondeur, la clôture atteint l''objectif.'::text,'descend'::text,'descendait'::text,'descendra'::text,'Si un poteau descend à 50 centimètres de profondeur, la clôture atteint l''objectif.'::text),
(376010,41779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kazık 50 santim derine ..., çit hedefi tutturur.'::text,'girerse'::text,'girdiyse'::text,'girecekse'::text,'Bir kazık 50 santim derine girerse, çit hedefi tutturur.'::text),
(376011,41779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy cölöp 50 centi mélyre ..., a kerítés hozza a célt.'::text,'megy'::text,'ment'::text,'fog menni'::text,'Ha egy cölöp 50 centi mélyre megy, a kerítés hozza a célt.'::text),
(376014,41780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pfosten ist aus Holz, ...? Darum ist er hölzern.'::text,'oder'::text,'oder'::text,'oder'::text,'Der Pfosten ist aus Holz, oder? Darum ist er hölzern.'::text),
(376018,41780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей стовпчик зроблений з дерева, ...? Тому він дерев''яний.'::text,'правда'::text,'правда'::text,'правда'::text,'Цей стовпчик зроблений з дерева, правда? Тому він дерев''яний.'::text),
(376017,41780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese poste está hecho de madera, ¿...? Por eso es de madera.'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Ese poste está hecho de madera, ¿verdad? Por eso es de madera.'::text),
(376016,41780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce poteau est en bois, ... ? C''est pour ça qu''il est en bois.'::text,'non'::text,'non'::text,'non'::text,'Ce poteau est en bois, non ? C''est pour ça qu''il est en bois.'::text),
(376019,41780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kazık tahtadan yapılmış, ...? O yüzden ahşap.'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'O kazık tahtadan yapılmış, değil mi? O yüzden ahşap.'::text),
(376020,41780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a cölöp fából van, ...? Ezért fa.'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Az a cölöp fából van, ugye? Ezért fa.'::text),
(376032,41782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wirst du jeden Pfosten in diesem Zaun ..., ehrlich beeindruckend.'::text,'eingeschlagen haben'::text,'einschlagen'::text,'einschlagen'::text,'Bis Mittag wirst du jeden Pfosten in diesem Zaun eingeschlagen haben, ehrlich beeindruckend.'::text),
(376036,41782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду ти ... кожен стовпчик у цьому паркані, чесно, вражає.'::text,'заб''єш'::text,'заб''єш'::text,'забиваєш'::text,'До обіду ти заб''єш кожен стовпчик у цьому паркані, чесно, вражає.'::text),
(376035,41782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, ... todos los postes de esta valla, sinceramente impresionante.'::text,'habrás clavado'::text,'clavarás'::text,'clavas'::text,'Para la hora de comer, habrás clavado todos los postes de esta valla, sinceramente impresionante.'::text),
(376034,41782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le déjeuner, tu ... chaque poteau de cette clôture, franchement impressionnant.'::text,'auras enfoncé'::text,'enfonceras'::text,'enfonces'::text,'D''ici le déjeuner, tu auras enfoncé chaque poteau de cette clôture, franchement impressionnant.'::text),
(376037,41782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu çitteki her kazığı ..., cidden etkileyici.'::text,'çakmış olacaksın'::text,'çakacaksın'::text,'çakıyorsun'::text,'Öğlene kadar bu çitteki her kazığı çakmış olacaksın, cidden etkileyici.'::text),
(376038,41782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédig ... ennek a kerítésnek minden cölöpét, őszintén lenyűgöző.'::text,'bevered'::text,'be fogod verni'::text,'vered be'::text,'Ebédig bevered ennek a kerítésnek minden cölöpét, őszintén lenyűgöző.'::text),
(376041,41783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du das Loch nicht zuerst gegraben hättest, ... du den Pfosten nicht so glatt reingekriegt, Respekt.'::text,'hättest'::text,'wirst'::text,'hast'::text,'Wenn du das Loch nicht zuerst gegraben hättest, hättest du den Pfosten nicht so glatt reingekriegt, Respekt.'::text),
(376045,41783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти спершу не викопав ту яму, ти ... стовпчик так легко, респект.'::text,'не встромив би'::text,'не встромиш'::text,'не встромив'::text,'Якби ти спершу не викопав ту яму, ти не встромив би стовпчик так легко, респект.'::text),
(376044,41783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieras cavado ese hoyo primero, no ... el poste tan fácil, respeto.'::text,'habrías metido'::text,'meterás'::text,'metiste'::text,'Si no hubieras cavado ese hoyo primero, no habrías metido el poste tan fácil, respeto.'::text),
(376043,41783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu n''avais pas creusé ce trou d''abord, tu ... le poteau aussi facilement, respect.'::text,'n''aurais pas enfoncé'::text,'n''enfonceras pas'::text,'n''as pas enfoncé'::text,'Si tu n''avais pas creusé ce trou d''abord, tu n''aurais pas enfoncé le poteau aussi facilement, respect.'::text),
(376046,41783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çukuru önce kazmasaydın, kazığı bu kadar kolay ..., helal.'::text,'sokamazdın'::text,'sokamayacaksın'::text,'sokamadın'::text,'O çukuru önce kazmasaydın, kazığı bu kadar kolay sokamazdın, helal.'::text),
(376047,41783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem ástad volna ki előbb azt a gödröt, nem ... ilyen simán a cölöpöt, respekt.'::text,'verted volna be'::text,'fogod beverni'::text,'verted be'::text,'Ha nem ástad volna ki előbb azt a gödröt, nem verted volna be ilyen simán a cölöpöt, respekt.'::text),
(376059,41785,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Pfosten zuerst abmessen sollen, denn er ist zu kurz für das Loch.'::text,'hätte'::text,'müsste'::text,'kann nicht'::text,'Er hätte den Pfosten zuerst abmessen sollen, denn er ist zu kurz für das Loch.'::text),
(376063,41785,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... спершу виміряти стовпчик, бо той закороткий для ями.'::text,'мав би'::text,'мусив'::text,'не міг'::text,'Він мав би спершу виміряти стовпчик, бо той закороткий для ями.'::text),
(376062,41785,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... medido el poste primero, porque es demasiado corto para el hoyo.'::text,'Debería haber'::text,'Debe de haber'::text,'No puede haber'::text,'Debería haber medido el poste primero, porque es demasiado corto para el hoyo.'::text),
(376061,41785,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... mesurer le poteau d''abord, parce qu''il est trop court pour le trou.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Il aurait dû mesurer le poteau d''abord, parce qu''il est trop court pour le trou.'::text),
(376064,41785,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce kazığı ..., çünkü çukur için fazla kısa.'::text,'ölçmeliydi'::text,'ölçmüş olmalı'::text,'ölçmüş olamaz'::text,'Önce kazığı ölçmeliydi, çünkü çukur için fazla kısa.'::text),
(376065,41785,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előbb le ... mérnie a cölöpöt, mert túl rövid a gödörhöz.'::text,'kellett volna'::text,'kellett'::text,'nem lehetett'::text,'Előbb le kellett volna mérnie a cölöpöt, mert túl rövid a gödörhöz.'::text),
(376068,41786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte den Pfosten von einer Maschine ... lassen können.'::text,'einschlagen'::text,'einschlagen'::text,'einzuschlagen'::text,'Er hätte den Pfosten von einer Maschine einschlagen lassen können.'::text),
(376072,41786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він міг би зробити так, щоб стовпчик ... машиною.'::text,'забили'::text,'забивати'::text,'забити'::text,'Він міг би зробити так, щоб стовпчик забили машиною.'::text),
(376071,41786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Podría haber mandado ... el poste con una máquina.'::text,'clavar'::text,'clavar'::text,'a clavar'::text,'Podría haber mandado clavar el poste con una máquina.'::text),
(376070,41786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aurait pu faire ... le poteau par une machine.'::text,'enfoncer'::text,'enfoncer'::text,'d''enfoncer'::text,'Il aurait pu faire enfoncer le poteau par une machine.'::text),
(376073,41786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kazığı bir makineye ...'::text,'çaktırabilirdi'::text,'çakabilirdi'::text,'çakmak için'::text,'Kazığı bir makineye çaktırabilirdi.'::text),
(376074,41786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cölöpöt egy géppel is ... volna.'::text,'beverethette'::text,'beverhette'::text,'beverni'::text,'A cölöpöt egy géppel is beverethette volna.'::text),
(376077,41787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, er ... einen längeren Pfosten für den Zaun gekauft.'::text,'hätte'::text,'kaufte'::text,'würde'::text,'Er wünscht sich, er hätte einen längeren Pfosten für den Zaun gekauft.'::text),
(376081,41787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... довший стовпчик для паркану.'::text,'купив'::text,'купив'::text,'купив би'::text,'Він шкодує, що не купив довший стовпчик для паркану.'::text),
(376080,41787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... un poste más largo para la valla.'::text,'haber comprado'::text,'comprar'::text,'comprar'::text,'Él desearía haber comprado un poste más largo para la valla.'::text),
(376079,41787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... un poteau plus long pour la clôture.'::text,'avoir acheté'::text,'acheter'::text,'acheter'::text,'Il aimerait avoir acheté un poteau plus long pour la clôture.'::text),
(376082,41787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke çit için daha uzun bir kazık ... diye düşünüyor.'::text,'alsaydı'::text,'alsa'::text,'alacak olsa'::text,'Keşke çit için daha uzun bir kazık alsaydı diye düşünüyor.'::text),
(376083,41787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... egy hosszabb cölöpöt a kerítéshez.'::text,'vett volna'::text,'venne'::text,'venne majd'::text,'Azt kívánja, bárcsak vett volna egy hosszabb cölöpöt a kerítéshez.'::text),
(395661,43963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Teamkollegen im Kreis ..., legten sie die Hände übereinander, weil ein Kreis eine Mitte hat.'::text,'standen'::text,'standen'::text,'gestanden haben'::text,'Während die Teamkollegen im Kreis standen, legten sie die Hände übereinander, weil ein Kreis eine Mitte hat.'::text),
(395665,43963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки товариші по команді ... колом, вони склали руки одна на одну, бо в кола є середина.'::text,'стояли'::text,'постояли'::text,'постояли'::text,'Поки товариші по команді стояли колом, вони склали руки одна на одну, бо в кола є середина.'::text),
(395664,43963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras los compañeros de equipo ... en círculo, juntaron las manos, porque un círculo tiene un centro.'::text,'estaban'::text,'estuvieron'::text,'han estado'::text,'Mientras los compañeros de equipo estaban en círculo, juntaron las manos, porque un círculo tiene un centro.'::text),
(395663,43963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que les coéquipiers ... en cercle, ils ont empilé leurs mains, parce qu''un cercle a un milieu.'::text,'se tenaient'::text,'se sont tenus'::text,'se sont tenus'::text,'Pendant que les coéquipiers se tenaient en cercle, ils ont empilé leurs mains, parce qu''un cercle a un milieu.'::text),
(395666,43963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım arkadaşları çember halinde ..., ellerini üst üste koydular, çünkü çemberin bir ortası vardır.'::text,'dururken'::text,'durduğunda'::text,'durmuşken'::text,'Takım arkadaşları çember halinde dururken, ellerini üst üste koydular, çünkü çemberin bir ortası vardır.'::text),
(395667,43963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a csapattársak körben ..., egymásra tették a kezüket, mert a körnek van közepe.'::text,'álltak'::text,'álltak'::text,'álltak'::text,'Miközben a csapattársak körben álltak, egymásra tették a kezüket, mert a körnek van közepe.'::text),
(395670,43964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Teamkollegen ... dreimal die Hände übereinandergelegt, was typischerweise auf Teamgeist hinweist.'::text,'haben'::text,'haben'::text,'legen'::text,'Die Teamkollegen haben dreimal die Hände übereinandergelegt, was typischerweise auf Teamgeist hinweist.'::text),
(395674,43964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Товариші по команді ... руки одна на одну тричі, що зазвичай свідчить про командний дух.'::text,'склали'::text,'складали'::text,'складають'::text,'Товариші по команді склали руки одна на одну тричі, що зазвичай свідчить про командний дух.'::text),
(395673,43964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los compañeros de equipo ... las manos tres veces, lo que suele indicar espíritu de equipo.'::text,'han juntado'::text,'han estado juntando'::text,'están juntando'::text,'Los compañeros de equipo han juntado las manos tres veces, lo que suele indicar espíritu de equipo.'::text),
(395672,43964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coéquipiers ... leurs mains trois fois, ce qui indique typiquement un esprit d''équipe.'::text,'ont empilé'::text,'ont empilé'::text,'empilent'::text,'Les coéquipiers ont empilé leurs mains trois fois, ce qui indique typiquement un esprit d''équipe.'::text),
(395675,43964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım arkadaşları üç kez ellerini üst üste ..., bu da genellikle takım ruhuna işaret eder.'::text,'koydu'::text,'koyup duruyor'::text,'koyuyor'::text,'Takım arkadaşları üç kez ellerini üst üste koydu, bu da genellikle takım ruhuna işaret eder.'::text),
(395676,43964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapattársak háromszor ... egymásra a kezüket, ami jellemzően csapatszellemre utal.'::text,'tették'::text,'rakosgatták'::text,'teszik'::text,'A csapattársak háromszor tették egymásra a kezüket, ami jellemzően csapatszellemre utal.'::text),
(395679,43965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Sonne unterging, ... die sechs Teamkollegen geschworen, für immer zu gewinnen!'::text,'hatten'::text,'haben'::text,'schwören'::text,'Als die Sonne unterging, hatten die sechs Teamkollegen geschworen, für immer zu gewinnen!'::text),
(395683,43965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли сонце сіло, шестеро товаришів по команді вже ... клятву вигравати вічно!'::text,'дали'::text,'дали'::text,'дають'::text,'Коли сонце сіло, шестеро товаришів по команді вже дали клятву вигравати вічно!'::text),
(395682,43965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando se puso el sol, los seis compañeros de equipo ... la promesa de ganar para siempre!'::text,'habían hecho'::text,'han hecho'::text,'hacen'::text,'¡Para cuando se puso el sol, los seis compañeros de equipo habían hecho la promesa de ganar para siempre!'::text),
(395681,43965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, les six coéquipiers ... le serment de gagner pour toujours !'::text,'avaient fait'::text,'ont fait'::text,'font'::text,'Au coucher du soleil, les six coéquipiers avaient fait le serment de gagner pour toujours !'::text),
(395684,43965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş battığında altı takım arkadaşı sonsuza dek kazanmaya ...!'::text,'yemin etmişti'::text,'yemin etti'::text,'yemin ediyor'::text,'Güneş battığında altı takım arkadaşı sonsuza dek kazanmaya yemin etmişti!'::text),
(395685,43965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire lement a nap, a hat csapattárs ..., hogy örökké nyernek!'::text,'fogadalmat tett'::text,'fogadalmat tett'::text,'fogadalmat tesz'::text,'Mire lement a nap, a hat csapattárs fogadalmat tett, hogy örökké nyernek!'::text),
(395688,43966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Teamkollege seine Hand sinken lässt, ... der ganze Kreis komplett auseinander!'::text,'fällt'::text,'fiele'::text,'fiel'::text,'Wenn ein Teamkollege seine Hand sinken lässt, fällt der ganze Kreis komplett auseinander!'::text),
(395692,43966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо один товариш по команді опустить руку, усе коло ... повністю!'::text,'розвалиться'::text,'розвалилося б'::text,'розвалилося'::text,'Якщо один товариш по команді опустить руку, усе коло розвалиться повністю!'::text),
(395691,43966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un compañero de equipo baja la mano, todo el círculo ... por completo!'::text,'se derrumbará'::text,'se derrumbaría'::text,'se derrumbó'::text,'¡Si un compañero de equipo baja la mano, todo el círculo se derrumbará por completo!'::text),
(395690,43966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un coéquipier baisse la main, tout le cercle ... complètement !'::text,'s''effondrera'::text,'s''effondrerait'::text,'s''est effondré'::text,'Si un coéquipier baisse la main, tout le cercle s''effondrera complètement !'::text),
(395693,43966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir takım arkadaşı elini indirirse, bütün çember tamamen ...!'::text,'çökecek'::text,'çökerdi'::text,'çöktü'::text,'Bir takım arkadaşı elini indirirse, bütün çember tamamen çökecek!'::text),
(395694,43966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy csapattárs leengedi a kezét, az egész kör teljesen ...!'::text,'szétesik'::text,'szétesne'::text,'szétesett'::text,'Ha egy csapattárs leengedi a kezét, az egész kör teljesen szétesik!'::text),
(395697,43967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich so einen Teamkollegen verlieren würde, ... ich nie wieder spielen! Absolute Tragödie!'::text,'würde'::text,'werde'::text,'spielte'::text,'Wenn ich so einen Teamkollegen verlieren würde, würde ich nie wieder spielen! Absolute Tragödie!'::text),
(395701,43967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я втратив такого товариша по команді, я ...! Повна трагедія!'::text,'більше ніколи не грав би'::text,'більше ніколи не гратиму'::text,'більше ніколи не грав'::text,'Якби я втратив такого товариша по команді, я більше ніколи не грав би! Повна трагедія!'::text),
(395700,43967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si perdiera a un compañero de equipo así, no ... nunca más! ¡Tragedia absoluta!'::text,'volvería a jugar'::text,'volveré a jugar'::text,'volví a jugar'::text,'¡Si perdiera a un compañero de equipo así, no volvería a jugar nunca más! ¡Tragedia absoluta!'::text),
(395699,43967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je perdais un coéquipier comme ça, je ... plus jamais ! Tragédie absolue !'::text,'ne jouerais'::text,'ne jouerai'::text,'n''ai joué'::text,'Si je perdais un coéquipier comme ça, je ne jouerais plus jamais ! Tragédie absolue !'::text),
(395702,43967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle bir takım arkadaşını kaybetsem, bir daha asla ...! Tam bir trajedi!'::text,'oynamazdım'::text,'oynamayacağım'::text,'oynamadım'::text,'Böyle bir takım arkadaşını kaybetsem, bir daha asla oynamazdım! Tam bir trajedi!'::text),
(395703,43967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elveszítenék egy ilyen csapattársat, soha többé ...! Totális tragédia!'::text,'nem játszanék'::text,'nem fogok játszani'::text,'nem játszottam'::text,'Ha elveszítenék egy ilyen csapattársat, soha többé nem játszanék! Totális tragédia!'::text),
(395706,43968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt jetzt, die neue Teamkollegin ... erst letzte Woche ins Team aufgenommen, hat sie gesagt!'::text,'wurde'::text,'wird'::text,'nahm'::text,'Echt jetzt, die neue Teamkollegin wurde erst letzte Woche ins Team aufgenommen, hat sie gesagt!'::text),
(395710,43968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, нову товаришку по команді ... до команди лише минулого тижня, вона сказала!'::text,'додали'::text,'додають'::text,'додала'::text,'Та ну, нову товаришку по команді додали до команди лише минулого тижня, вона сказала!'::text),
(395709,43968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué dices, la nueva compañera ... al equipo solo la semana pasada, lo dijo ella!'::text,'fue añadida'::text,'es añadida'::text,'añadió'::text,'¡Qué dices, la nueva compañera fue añadida al equipo solo la semana pasada, lo dijo ella!'::text),
(395708,43968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, la nouvelle coéquipière ... à l''équipe seulement la semaine dernière, elle l''a dit !'::text,'a été ajoutée'::text,'est ajoutée'::text,'a ajouté'::text,'Sérieux, la nouvelle coéquipière a été ajoutée à l''équipe seulement la semaine dernière, elle l''a dit !'::text),
(395711,43968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, yeni takım arkadaşı takıma daha geçen hafta ..., öyle dedi!'::text,'eklenmiş'::text,'ekleniyor'::text,'eklemiş'::text,'Yok artık, yeni takım arkadaşı takıma daha geçen hafta eklenmiş, öyle dedi!'::text),
(395712,43968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, az új csapattársat csak múlt héten ... a csapatba, ő mondta!'::text,'vették fel'::text,'veszik fel'::text,'vette fel'::text,'Ne már, az új csapattársat csak múlt héten vették fel a csapatba, ő mondta!'::text),
(395715,43969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Teamkollegen ... sich per High Five ab, bevor die anderen dazukamen.'::text,'klatschten'::text,'wurden abgeklatscht'::text,'abklatschend'::text,'Zwei Teamkollegen klatschten sich per High Five ab, bevor die anderen dazukamen.'::text),
(395719,43969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє товаришів по команді ... долонями, перш ніж до них приєдналися інші.'::text,'плеснули'::text,'були плеснуті'::text,'плескаючи'::text,'Двоє товаришів по команді плеснули долонями, перш ніж до них приєдналися інші.'::text),
(395718,43969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos compañeros de equipo ... los cinco antes de que se unieran los demás.'::text,'chocaron'::text,'fueron chocados'::text,'chocando'::text,'Dos compañeros de equipo chocaron los cinco antes de que se unieran los demás.'::text),
(395717,43969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux coéquipiers ... dans les mains avant que les autres les rejoignent.'::text,'se sont tapé'::text,'ont été tapés'::text,'se tapant'::text,'Deux coéquipiers se sont tapé dans les mains avant que les autres les rejoignent.'::text),
(395720,43969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diğerleri onlara katılmadan önce iki takım arkadaşı beşlik ...'::text,'çaktı'::text,'çakıldı'::text,'çakarak'::text,'Diğerleri onlara katılmadan önce iki takım arkadaşı beşlik çaktı.'::text),
(395721,43969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két csapattárs pacsit ..., mielőtt a többiek csatlakoztak hozzájuk.'::text,'adott egymásnak'::text,'lett adva'::text,'adva'::text,'Két csapattárs pacsit adott egymásnak, mielőtt a többiek csatlakoztak hozzájuk.'::text),
(395724,43970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lachen zusammen, also ... sie nicht sauer auf ihre Teamkollegen sein.'::text,'können'::text,'müssen'::text,'sollten'::text,'Sie lachen zusammen, also können sie nicht sauer auf ihre Teamkollegen sein.'::text),
(395728,43970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони разом сміються, тож вони ... сердитися на своїх товаришів по команді.'::text,'не можуть'::text,'мусять'::text,'мають'::text,'Вони разом сміються, тож вони не можуть сердитися на своїх товаришів по команді.'::text),
(395727,43970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se ríen juntos, así que no ... estar enfadados con sus compañeros de equipo.'::text,'pueden'::text,'deben de'::text,'deberían'::text,'Se ríen juntos, así que no pueden estar enfadados con sus compañeros de equipo.'::text),
(395726,43970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils rient ensemble, donc ils ... être fâchés contre leurs coéquipiers.'::text,'ne peuvent pas'::text,'doivent'::text,'devraient'::text,'Ils rient ensemble, donc ils ne peuvent pas être fâchés contre leurs coéquipiers.'::text),
(395729,43970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birlikte gülüyorlar, yani takım arkadaşlarına kızgın ...'::text,'olamazlar'::text,'olmalılar'::text,'olmalılar'::text,'Birlikte gülüyorlar, yani takım arkadaşlarına kızgın olamazlar.'::text),
(395730,43970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Együtt nevetnek, szóval nem ... dühösek a csapattársaikra.'::text,'lehetnek'::text,'kell legyenek'::text,'kellene legyenek'::text,'Együtt nevetnek, szóval nem lehetnek dühösek a csapattársaikra.'::text),
(395733,43971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder Teamkollege, ... Hand in der Mitte liegt, schreit und reißt die Arme hoch.'::text,'dessen'::text,'der'::text,'welche'::text,'Jeder Teamkollege, dessen Hand in der Mitte liegt, schreit und reißt die Arme hoch.'::text),
(395737,43971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен товариш по команді, ... рука посередині, кричить і підкидає руки вгору.'::text,'чия'::text,'який'::text,'що'::text,'Кожен товариш по команді, чия рука посередині, кричить і підкидає руки вгору.'::text),
(395736,43971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada compañero de equipo ... mano está en el centro grita y levanta los brazos.'::text,'cuya'::text,'que'::text,'la cual'::text,'Cada compañero de equipo cuya mano está en el centro grita y levanta los brazos.'::text),
(395735,43971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque coéquipier ... la main est au milieu crie et lève les bras.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Chaque coéquipier dont la main est au milieu crie et lève les bras.'::text),
(395738,43971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eli ortada ... her takım arkadaşı bağırıp kollarını havaya kaldırıyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Eli ortada olan her takım arkadaşı bağırıp kollarını havaya kaldırıyor.'::text),
(395739,43971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden csapattárs, ... a keze középen van, kiabál és feldobja a karját.'::text,'akinek'::text,'aki'::text,'amely'::text,'Minden csapattárs, akinek a keze középen van, kiabál és feldobja a karját.'::text),
(396642,44072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder Hemden an die ordentliche Stange, wie typischerweise beobachtet.'::text,'hängt'::text,'hängt'::text,'hängt'::text,'Morgen um diese Zeit hängt er wieder Hemden an die ordentliche Stange, wie typischerweise beobachtet.'::text),
(396646,44072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... сорочки на охайну штангу, як зазвичай спостерігається.'::text,'вішатиме'::text,'повісить'::text,'вішає'::text,'Завтра в цей час він знову вішатиме сорочки на охайну штангу, як зазвичай спостерігається.'::text),
(396645,44072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ... camisas otra vez en la barra ordenada, como se observa habitualmente.'::text,'estará colgando'::text,'colgará'::text,'cuelga'::text,'Mañana a esta hora, estará colgando camisas otra vez en la barra ordenada, como se observa habitualmente.'::text),
(396644,44072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, il ... des chemises sur la tringle bien rangée, de nouveau, comme on l''observe typiquement.'::text,'sera en train de suspendre'::text,'suspendra'::text,'suspend'::text,'Demain à cette heure-ci, il sera en train de suspendre des chemises sur la tringle bien rangée, de nouveau, comme on l''observe typiquement.'::text),
(396647,44072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte, tipik olarak gözlemlendiği gibi, gömlekleri yine düzenli askılığa ...'::text,'asıyor olacak'::text,'asacak'::text,'asar'::text,'Yarın bu saatte, tipik olarak gözlemlendiği gibi, gömlekleri yine düzenli askılığa asıyor olacak.'::text),
(396648,44072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor, ahogy az jellemzően megfigyelhető, megint ingeket ... a rendezett rúdra.'::text,'fog akasztani'::text,'akaszt majd'::text,'akaszt'::text,'Holnap ilyenkor, ahogy az jellemzően megfigyelhető, megint ingeket fog akasztani a rendezett rúdra.'::text),
(396651,44073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wette, dein Kleiderschrank ... für immer so ordentlich. Stilvoll.'::text,'bleibt'::text,'bleibt'::text,'bleibt'::text,'Ich wette, dein Kleiderschrank bleibt für immer so ordentlich. Stilvoll.'::text),
(396655,44073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Б''юсь об заклад, твоя шафа ... такою охайною назавжди. Стильно.'::text,'залишиться'::text,'залишатиметься'::text,'залишається'::text,'Б''юсь об заклад, твоя шафа залишиться такою охайною назавжди. Стильно.'::text),
(396654,44073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apuesto a que tu armario ... así de ordenado para siempre. Con clase.'::text,'seguirá'::text,'estará quedándose'::text,'sigue'::text,'Apuesto a que tu armario seguirá así de ordenado para siempre. Con clase.'::text),
(396653,44073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je parie que ton armoire ... aussi bien rangée pour toujours. La classe.'::text,'restera'::text,'sera en train de rester'::text,'reste'::text,'Je parie que ton armoire restera aussi bien rangée pour toujours. La classe.'::text),
(396656,44073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahse girerim dolabın sonsuza dek böyle düzenli ...; klas.'::text,'kalacak'::text,'kalıyor olacak'::text,'kalıyor'::text,'Bahse girerim dolabın sonsuza dek böyle düzenli kalacak; klas.'::text),
(396657,44073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fogadok, hogy a szekrényed örökre ... ilyen rendezett. Elegáns.'::text,'marad'::text,'maradni fog'::text,'marad'::text,'Fogadok, hogy a szekrényed örökre marad ilyen rendezett. Elegáns.'::text),
(396660,44074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du ein Hemd aufhängst, ... die ganze Stange ordentlich.'::text,'bleibt'::text,'bleibt'::text,'blieb'::text,'Ehrlich, wenn du ein Hemd aufhängst, bleibt die ganze Stange ordentlich.'::text),
(396664,44074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли ти вішаєш сорочку, уся штанга ... охайною.'::text,'залишається'::text,'залишиться'::text,'залишалася'::text,'Чесно, коли ти вішаєш сорочку, уся штанга залишається охайною.'::text),
(396663,44074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si cuelgas una camisa, toda la barra ... ordenada.'::text,'queda'::text,'quedará'::text,'quedó'::text,'La verdad, si cuelgas una camisa, toda la barra queda ordenada.'::text),
(396662,44074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu suspends une chemise, toute la tringle ... bien rangée.'::text,'reste'::text,'restera'::text,'restait'::text,'Franchement, si tu suspends une chemise, toute la tringle reste bien rangée.'::text),
(396665,44074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir gömlek astığında bütün askılık düzenli ...'::text,'kalır'::text,'kalacak'::text,'kaldı'::text,'Açıkçası, bir gömlek astığında bütün askılık düzenli kalır.'::text),
(396666,44074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha felakasztasz egy inget, az egész rúd rendezett ...'::text,'marad'::text,'marad majd'::text,'maradt'::text,'Őszintén, ha felakasztasz egy inget, az egész rúd rendezett marad.'::text),
(396669,44075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, dein Kleiderschrank ... immer ordentlich, und du hast nicht gelogen. Respekt.'::text,'sei'::text,'ist'::text,'werde'::text,'Du hast gesagt, dein Kleiderschrank sei immer ordentlich, und du hast nicht gelogen. Respekt.'::text),
(396673,44075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казав, що твоя шафа ... завжди охайна, і ти не брехав. Респект.'::text,'була'::text,'є'::text,'буде'::text,'Ти казав, що твоя шафа була завжди охайна, і ти не брехав. Респект.'::text),
(396672,44075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que tu armario ... siempre ordenado, y no mentías. Respeto.'::text,'estaba'::text,'está'::text,'estará'::text,'Dijiste que tu armario estaba siempre ordenado, y no mentías. Respeto.'::text),
(396671,44075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que ton armoire ... toujours bien rangée, et tu ne mentais pas. Respect.'::text,'était'::text,'est'::text,'sera'::text,'Tu as dit que ton armoire était toujours bien rangée, et tu ne mentais pas. Respect.'::text),
(396674,44075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolabının her zaman düzenli ... söyledin ve yalan söylemiyordun. Helal.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Dolabının her zaman düzenli olduğunu söyledin ve yalan söylemiyordun. Helal.'::text),
(396675,44075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy a szekrényed mindig rendezett ..., és nem hazudtál. Respekt.'::text,'volt'::text,NULL::text,'lesz'::text,'Azt mondtad, hogy a szekrényed mindig rendezett volt, és nem hazudtál. Respekt.'::text),
(396678,44076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... überhaupt nicht ordentlich; sein alter Kleiderschrank war ein leicht chaotischer Ort.'::text,'war früher'::text,'wäre'::text,'war es gewohnt'::text,'Er war früher überhaupt nicht ordentlich; sein alter Kleiderschrank war ein leicht chaotischer Ort.'::text),
(396682,44076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше він ... охайним узагалі; його стара шафа була злегка хаотичним місцем.'::text,'не був'::text,'не був би'::text,'не звик бути'::text,'Раніше він не був охайним узагалі; його стара шафа була злегка хаотичним місцем.'::text),
(396681,44076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No ... nada ordenado; su viejo armario era un sitio ligeramente caótico.'::text,'solía ser'::text,'sería'::text,'estaba acostumbrado a ser'::text,'No solía ser nada ordenado; su viejo armario era un sitio ligeramente caótico.'::text),
(396680,44076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... pas du tout ordonné ; sa vieille armoire était un endroit légèrement chaotique.'::text,'n''était'::text,'ne serait'::text,'n''était pas habitué à être'::text,'Avant, il n''était pas du tout ordonné ; sa vieille armoire était un endroit légèrement chaotique.'::text),
(396683,44076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden hiç düzenli ...; eski dolabı birazcık kaotik bir yerdi.'::text,'değildi'::text,'olmazdı'::text,'olmaya alışkın değildi'::text,'Eskiden hiç düzenli değildi; eski dolabı birazcık kaotik bir yerdi.'::text),
(396684,44076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen egyáltalán nem ... rendszerető; a régi szekrénye kissé kaotikus hely volt.'::text,'volt'::text,'lett volna'::text,'volt hozzászokva'::text,'Régen egyáltalán nem volt rendszerető; a régi szekrénye kissé kaotikus hely volt.'::text),
(396687,44077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er vermeidet es, ein Hemd ..., das nicht perfekt ordentlich ist. Eindeutig ein sehr entspannter Typ.'::text,'zu tragen'::text,'zu tragen'::text,'tragen'::text,'Er vermeidet es, ein Hemd zu tragen, das nicht perfekt ordentlich ist. Eindeutig ein sehr entspannter Typ.'::text),
(396691,44077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уникає ... сорочки, яка не ідеально охайна. Явно дуже розслаблений чувак.'::text,'носіння'::text,'носити'::text,'носити'::text,'Він уникає носіння сорочки, яка не ідеально охайна. Явно дуже розслаблений чувак.'::text),
(396690,44077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evita ... una camisa que no esté perfectamente ordenada. Claramente un tío muy relajado.'::text,'ponerse'::text,'ponerse'::text,'ponerse'::text,'Evita ponerse una camisa que no esté perfectamente ordenada. Claramente un tío muy relajado.'::text),
(396689,44077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il évite de ... une chemise qui n''est pas parfaitement nickel. Clairement un mec très détendu.'::text,'porter'::text,'porter'::text,'porter'::text,'Il évite de porter une chemise qui n''est pas parfaitement nickel. Clairement un mec très détendu.'::text),
(396692,44077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz düzgün olmayan bir gömleği ... kaçınıyor. Belli ki çok rahat biri.'::text,'giymekten'::text,'giymek'::text,'giy'::text,'Kusursuz düzgün olmayan bir gömleği giymekten kaçınıyor. Belli ki çok rahat biri.'::text),
(396693,44077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kerüli, hogy olyan inget ..., ami nem tökéletesen rendezett. Egyértelműen nagyon laza srác.'::text,'viseljen'::text,'viselni'::text,'visel'::text,'Kerüli, hogy olyan inget viseljen, ami nem tökéletesen rendezett. Egyértelműen nagyon laza srác.'::text),
(396696,44078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Kleiderschrank ist sehr ordentlich, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Sein Kleiderschrank ist sehr ordentlich, oder?'::text),
(396700,44078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його шафа дуже охайна, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Його шафа дуже охайна, правда?'::text),
(396699,44078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su armario está muy ordenado, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Su armario está muy ordenado, ¿verdad?'::text),
(396698,44078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son armoire est très bien rangée, ... ?'::text,'non'::text,'non'::text,'non'::text,'Son armoire est très bien rangée, non ?'::text),
(396701,44078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolabı çok düzenli, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Dolabı çok düzenli, değil mi?'::text),
(396702,44078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szekrénye nagyon rendezett, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A szekrénye nagyon rendezett, ugye?'::text),
(396714,44080,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird er jedes Hemd in den ordentlichen Kleiderschrank ...'::text,'gehängt haben'::text,'hängen'::text,'hängen'::text,'Bis heute Abend wird er jedes Hemd in den ordentlichen Kleiderschrank gehängt haben.'::text),
(396718,44080,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... кожну сорочку в охайну шафу.'::text,'повісить'::text,'повісить'::text,'вішатиме'::text,'До вечора він повісить кожну сорочку в охайну шафу.'::text),
(396717,44080,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ... todas las camisas en el armario ordenado.'::text,'habrá colgado'::text,'colgará'::text,'estará colgando'::text,'Para esta noche, habrá colgado todas las camisas en el armario ordenado.'::text),
(396716,44080,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... chaque chemise dans l''armoire bien rangée.'::text,'aura suspendu'::text,'suspendra'::text,'sera en train de suspendre'::text,'D''ici ce soir, il aura suspendu chaque chemise dans l''armoire bien rangée.'::text),
(396719,44080,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar her gömleği düzenli dolaba ...'::text,'asmış olacak'::text,'asacak'::text,'asıyor olacak'::text,'Bu akşama kadar her gömleği düzenli dolaba asmış olacak.'::text),
(396720,44080,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ... minden inget a rendezett szekrénybe.'::text,'felakaszt'::text,'fel fog akasztani'::text,'akasztani fog'::text,'Estére felakaszt minden inget a rendezett szekrénybe.'::text),
(396732,44082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Hemd glatt gestrichen, bevor er es an die ordentliche Stange hängte.'::text,'hatte'::text,'hat'::text,'streicht'::text,'Er hatte das Hemd glatt gestrichen, bevor er es an die ordentliche Stange hängte.'::text),
(396736,44082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... сорочку, перш ніж повісити її на охайну штангу.'::text,'розгладив'::text,'розгладив'::text,'розгладжує'::text,'Він розгладив сорочку, перш ніж повісити її на охайну штангу.'::text),
(396735,44082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la camisa antes de colgarla en la barra ordenada.'::text,'Había alisado'::text,'Ha alisado'::text,'Alisa'::text,'Había alisado la camisa antes de colgarla en la barra ordenada.'::text),
(396734,44082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la chemise avant de la suspendre sur la tringle bien rangée.'::text,'avait lissé'::text,'a lissé'::text,'lisse'::text,'Il avait lissé la chemise avant de la suspendre sur la tringle bien rangée.'::text),
(396737,44082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gömleği düzenli askılığa asmadan önce ...'::text,'düzleştirmişti'::text,'düzleştirdi'::text,'düzleştiriyor'::text,'Gömleği düzenli askılığa asmadan önce düzleştirmişti.'::text),
(396738,44082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az inget, mielőtt felakasztotta a rendezett rúdra.'::text,'Kisimította'::text,'Kisimította'::text,'Kisimítja'::text,'Kisimította az inget, mielőtt felakasztotta a rendezett rúdra.'::text),
(359373,39931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... am Hafen entlang, als die Möwen vorbeiflogen, ehrlich so lässig.'::text,'liefst'::text,'liefst'::text,'bist gelaufen'::text,'Du liefst am Hafen entlang, als die Möwen vorbeiflogen, ehrlich so lässig.'::text),
(359377,39931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... вздовж гавані, коли повз пролетіли чайки, чесно, так стильно.'::text,'ішов'::text,'пройшов'::text,'пройшов'::text,'Ти ішов вздовж гавані, коли повз пролетіли чайки, чесно, так стильно.'::text),
(359376,39931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por el puerto cuando pasaron volando las gaviotas, sinceramente con muchísimo estilo.'::text,'Caminabas'::text,'Caminaste'::text,'Has caminado'::text,'Caminabas por el puerto cuando pasaron volando las gaviotas, sinceramente con muchísimo estilo.'::text),
(359375,39931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le long du port quand les mouettes sont passées, franchement trop classe.'::text,'marchais'::text,'as marché'::text,'as marché'::text,'Tu marchais le long du port quand les mouettes sont passées, franchement trop classe.'::text),
(359378,39931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martılar geçip giderken limanda ..., cidden çok havalı.'::text,'yürüyordun'::text,'yürüdün'::text,'yürümüşsün'::text,'Martılar geçip giderken limanda yürüyordun, cidden çok havalı.'::text),
(359379,39931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a kikötő mentén ..., amikor elrepültek a sirályok, őszintén, olyan laza voltál.'::text,'sétáltál'::text,'sétáltál'::text,'sétáltál'::text,'Épp a kikötő mentén sétáltál, amikor elrepültek a sirályok, őszintén, olyan laza voltál.'::text),
(359382,39932,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... seit Sonnenaufgang durch diesen Hafen, und ehrlich, Respekt.'::text,'läufst'::text,'läufst'::text,'läufst'::text,'Du läufst seit Sonnenaufgang durch diesen Hafen, und ehrlich, Respekt.'::text),
(359386,39932,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... цією гаванню від світанку, і чесно, респект.'::text,'гуляєш'::text,'гуляєш'::text,'гуляєш'::text,'Ти гуляєш цією гаванню від світанку, і чесно, респект.'::text),
(359385,39932,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por este puerto desde el amanecer, y la verdad, respeto.'::text,'Has estado caminando'::text,'Estás caminando'::text,'Caminas'::text,'Has estado caminando por este puerto desde el amanecer, y la verdad, respeto.'::text),
(359384,39932,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... dans ce port depuis le lever du soleil, et franchement, respect.'::text,'te balades'::text,'te balades'::text,'te balades'::text,'Tu te balades dans ce port depuis le lever du soleil, et franchement, respect.'::text),
(359387,39932,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün doğumundan beri bu limanda ...; açıkçası, helal.'::text,'yürüyorsun'::text,'yürüyorsun'::text,'yürürsün'::text,'Gün doğumundan beri bu limanda yürüyorsun; açıkçası, helal.'::text),
(359388,39932,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napkelte óta ... ebben a kikötőben, és őszintén, respekt.'::text,'sétálsz'::text,'sétálsz'::text,'sétálsz'::text,'Napkelte óta sétálsz ebben a kikötőben, és őszintén, respekt.'::text),
(359391,39933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Kräne das Schiff im Hafen ..., lehnte er an einem Poller, offensichtlich sehr beschäftigt.'::text,'beluden'::text,'beluden'::text,'beladen haben'::text,'Während die Kräne das Schiff im Hafen beluden, lehnte er an einem Poller, offensichtlich sehr beschäftigt.'::text),
(359395,39933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки крани ... корабель у гавані, він спирався на швартову тумбу, очевидно, дуже зайнятий.'::text,'вантажили'::text,'завантажили'::text,'завантажили'::text,'Поки крани вантажили корабель у гавані, він спирався на швартову тумбу, очевидно, дуже зайнятий.'::text),
(359394,39933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras las grúas ... el barco en el puerto, él se apoyaba en un bolardo, obviamente muy ocupado.'::text,'cargaban'::text,'cargaron'::text,'han cargado'::text,'Mientras las grúas cargaban el barco en el puerto, él se apoyaba en un bolardo, obviamente muy ocupado.'::text),
(359393,39933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que les grues ... le navire dans le port, il s''appuyait sur une bitte d''amarrage, visiblement très occupé.'::text,'chargeaient'::text,'ont chargé'::text,'ont chargé'::text,'Pendant que les grues chargeaient le navire dans le port, il s''appuyait sur une bitte d''amarrage, visiblement très occupé.'::text),
(359396,39933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vinçler limanda gemiyi ..., o bir babaya yaslanıyordu, belli ki çok meşguldü.'::text,'yüklerken'::text,'yüklediğinde'::text,'yüklemişken'::text,'Vinçler limanda gemiyi yüklerken, o bir babaya yaslanıyordu, belli ki çok meşguldü.'::text),
(359397,39933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a daruk a hajót ... a kikötőben, ő egy kikötőbakra támaszkodott, nyilván nagyon elfoglaltan.'::text,'rakodták'::text,'megrakodták'::text,'megrakodták'::text,'Miközben a daruk a hajót rakodták a kikötőben, ő egy kikötőbakra támaszkodott, nyilván nagyon elfoglaltan.'::text),
(359409,39935,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Schlepper den Hafen durchquert hatte, ... er genau ein Seil berührt, makellose Arbeit.'::text,'hatte'::text,'hat'::text,'berührt'::text,'Als der Schlepper den Hafen durchquert hatte, hatte er genau ein Seil berührt, makellose Arbeit.'::text),
(359413,39935,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки буксир перетнув гавань, він ... рівно однієї мотузки, бездоганна робота.'::text,'торкнувся'::text,'торкнувся'::text,'торкається'::text,'Поки буксир перетнув гавань, він торкнувся рівно однієї мотузки, бездоганна робота.'::text),
(359412,39935,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el remolcador cruzó el puerto, ... exactamente una cuerda, trabajo impecable.'::text,'había tocado'::text,'ha tocado'::text,'toca'::text,'Para cuando el remolcador cruzó el puerto, había tocado exactamente una cuerda, trabajo impecable.'::text),
(359411,39935,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que le remorqueur traverse le port, il ... exactement une corde, travail impeccable.'::text,'avait touché'::text,'a touché'::text,'touche'::text,'Le temps que le remorqueur traverse le port, il avait touché exactement une corde, travail impeccable.'::text),
(359414,39935,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Römorkör limanı geçtiğinde tam olarak bir halata ..., kusursuz iş.'::text,'dokunmuştu'::text,'dokundu'::text,'dokunuyor'::text,'Römorkör limanı geçtiğinde tam olarak bir halata dokunmuştu, kusursuz iş.'::text),
(359415,39935,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a vontatóhajó átkelt a kikötőn, pontosan egy kötélhez ..., hibátlan munka.'::text,'ért hozzá'::text,'ért hozzá'::text,'ér hozzá'::text,'Mire a vontatóhajó átkelt a kikötőn, pontosan egy kötélhez ért hozzá, hibátlan munka.'::text),
(359418,39936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Meer ruhig bleibt, ... die Boote im Hafen heute Nacht sicher.'::text,'sind'::text,'wären'::text,'waren'::text,'Wenn das Meer ruhig bleibt, sind die Boote im Hafen heute Nacht sicher.'::text),
(359422,39936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо море залишиться спокійним, човни в гавані ... в безпеці цієї ночі.'::text,'будуть'::text,'були б'::text,'були'::text,'Якщо море залишиться спокійним, човни в гавані будуть в безпеці цієї ночі.'::text),
(359421,39936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el mar sigue en calma, los barcos del puerto ... a salvo esta noche.'::text,'estarán'::text,'estarían'::text,'estaban'::text,'Si el mar sigue en calma, los barcos del puerto estarán a salvo esta noche.'::text),
(359420,39936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la mer reste calme, les bateaux du port ... en sécurité cette nuit.'::text,'seront'::text,'seraient'::text,'étaient'::text,'Si la mer reste calme, les bateaux du port seront en sécurité cette nuit.'::text),
(359423,39936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz sakin kalırsa, limandaki tekneler bu gece güvende ...'::text,'olacak'::text,'olurdu'::text,'idi'::text,'Deniz sakin kalırsa, limandaki tekneler bu gece güvende olacak.'::text),
(359424,39936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tenger nyugodt marad, a kikötőben lévő hajók ma éjjel biztonságban ...'::text,'lesznek'::text,'lennének'::text,'voltak'::text,'Ha a tenger nyugodt marad, a kikötőben lévő hajók ma éjjel biztonságban lesznek.'::text),
(359427,39937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Hafen keinen Kai hätte, ... die Jachten keinen Platz zum Festmachen.'::text,'hätten'::text,'haben werden'::text,'haben'::text,'Wenn der Hafen keinen Kai hätte, hätten die Jachten keinen Platz zum Festmachen.'::text),
(359431,39937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в гавані не було причалу, яхтам ... де пришвартуватися.'::text,'не було б'::text,'не буде'::text,'немає'::text,'Якби в гавані не було причалу, яхтам не було б де пришвартуватися.'::text),
(359430,39937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el puerto no tuviera muelle, los yates no ... dónde amarrar.'::text,'tendrían'::text,'tendrán'::text,'tienen'::text,'Si el puerto no tuviera muelle, los yates no tendrían dónde amarrar.'::text),
(359429,39937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le port n''avait pas de quai, les yachts ... nulle part où s''amarrer.'::text,'n''auraient'::text,'n''auront'::text,'n''ont'::text,'Si le port n''avait pas de quai, les yachts n''auraient nulle part où s''amarrer.'::text),
(359432,39937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Limanın rıhtımı olmasa, yatların bağlanacak hiçbir yeri ...'::text,'olmazdı'::text,'olmayacak'::text,'yok'::text,'Limanın rıhtımı olmasa, yatların bağlanacak hiçbir yeri olmazdı.'::text),
(359433,39937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kikötőnek nem lenne rakpartja, a jachtoknak nem ... hol kikötniük.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha a kikötőnek nem lenne rakpartja, a jachtoknak nem lenne hol kikötniük.'::text),
(359436,39938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hafen, ... Kräne riesige Containerschiffe beladen, ist schon bei Sonnenaufgang belebt.'::text,'wo'::text,'der'::text,'dessen'::text,'Der Hafen, wo Kräne riesige Containerschiffe beladen, ist schon bei Sonnenaufgang belebt.'::text),
(359440,39938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гавань, ... крани вантажать величезні контейнеровози, жвава навіть на світанку.'::text,'де'::text,'яка'::text,'чия'::text,'Гавань, де крани вантажать величезні контейнеровози, жвава навіть на світанку.'::text),
(359439,39938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El puerto, ... las grúas cargan enormes portacontenedores, tiene movimiento incluso al amanecer.'::text,'donde'::text,'que'::text,'cuyo'::text,'El puerto, donde las grúas cargan enormes portacontenedores, tiene movimiento incluso al amanecer.'::text),
(359438,39938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le port, ... des grues chargent d''énormes porte-conteneurs, est animé même au lever du soleil.'::text,'où'::text,'qui'::text,'dont'::text,'Le port, où des grues chargent d''énormes porte-conteneurs, est animé même au lever du soleil.'::text),
(359441,39938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vinçlerin dev konteyner gemilerini ... liman, gün doğumunda bile hareketli.'::text,'yüklediği'::text,'yüklediği'::text,'yüklediği'::text,'Vinçlerin dev konteyner gemilerini yüklediği liman, gün doğumunda bile hareketli.'::text),
(359442,39938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kikötő, ... daruk hatalmas konténerhajókat rakodnak, napkeltekor is nyüzsög.'::text,'ahol'::text,'amely'::text,'amelynek'::text,'A kikötő, ahol daruk hatalmas konténerhajókat rakodnak, napkeltekor is nyüzsög.'::text),
(359445,39939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Hafen in dieser Stadt ist der einzige mit Containerschiffen.'::text,'Der'::text,'Ein'::text,NULL::text,'Der Hafen in dieser Stadt ist der einzige mit Containerschiffen.'::text),
(359449,39939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... гавань у цьому місті — єдина з контейнеровозами.'::text,''::text,NULL::text,NULL::text,'Гавань у цьому місті — єдина з контейнеровозами.'::text),
(359448,39939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... puerto de esta ciudad es el único con portacontenedores.'::text,'El'::text,'Un'::text,NULL::text,'El puerto de esta ciudad es el único con portacontenedores.'::text),
(359447,39939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... port de cette ville est le seul avec des porte-conteneurs.'::text,'Le'::text,'Un'::text,NULL::text,'Le port de cette ville est le seul avec des porte-conteneurs.'::text),
(359450,39939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu şehirdeki ... liman, konteyner gemisi olan tek liman.'::text,''::text,'bir'::text,NULL::text,'Bu şehirdeki liman, konteyner gemisi olan tek liman.'::text),
(359451,39939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kikötő ebben a városban az egyetlen konténerhajókkal.'::text,'A'::text,'Egy'::text,NULL::text,'A kikötő ebben a városban az egyetlen konténerhajókkal.'::text),
(359463,39941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wirst du jedes Boot in diesem Hafen ..., irgendwie ikonisch.'::text,'gesehen haben'::text,'sehen'::text,'sehen'::text,'Bis Sonnenuntergang wirst du jedes Boot in diesem Hafen gesehen haben, irgendwie ikonisch.'::text),
(359467,39941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця ти ... кожен човен у цій гавані, трохи культово.'::text,'побачиш'::text,'побачиш'::text,'бачиш'::text,'До заходу сонця ти побачиш кожен човен у цій гавані, трохи культово.'::text),
(359466,39941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ... todos los barcos de este puerto, un poco icónico.'::text,'habrás visto'::text,'verás'::text,'ves'::text,'Para el atardecer, habrás visto todos los barcos de este puerto, un poco icónico.'::text),
(359465,39941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, tu ... chaque bateau de ce port, un peu iconique.'::text,'auras vu'::text,'verras'::text,'vois'::text,'D''ici le coucher du soleil, tu auras vu chaque bateau de ce port, un peu iconique.'::text),
(359468,39941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu limandaki her tekneyi ..., biraz ikonik.'::text,'görmüş olacaksın'::text,'göreceksin'::text,'görüyorsun'::text,'Gün batımına kadar bu limandaki her tekneyi görmüş olacaksın, biraz ikonik.'::text),
(359469,39941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére ... ennek a kikötőnek minden hajóját, kicsit ikonikus.'::text,'látod majd'::text,'látni fogod'::text,'látod'::text,'Naplementére látod majd ennek a kikötőnek minden hajóját, kicsit ikonikus.'::text),
(382521,42503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie sich die Schläfen, als der Chef an ihrem Tisch vorbeiging.'::text,'rieb'::text,'rieb'::text,'hat gerieben'::text,'Mädel, angeblich rieb sie sich die Schläfen, als der Chef an ihrem Tisch vorbeiging.'::text),
(382525,42503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... скроні, коли бос проходив повз її стіл.'::text,'терла'::text,'потерла'::text,'потерла'::text,'Подруго, кажуть, вона терла скроні, коли бос проходив повз її стіл.'::text),
(382524,42503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que ... las sienes cuando el jefe pasó junto a su mesa.'::text,'se estaba frotando'::text,'se frotó'::text,'se ha frotado'::text,'Tía, parece que se estaba frotando las sienes cuando el jefe pasó junto a su mesa.'::text),
(382523,42503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... les tempes quand le boss est passé devant son bureau.'::text,'se frottait'::text,'s''est frotté'::text,'s''est frotté'::text,'Meuf, apparemment elle se frottait les tempes quand le boss est passé devant son bureau.'::text),
(382526,42503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya patron masasının önünden geçerken şakaklarını ...'::text,'ovuyormuş'::text,'ovmuş'::text,'ovmuş'::text,'Kızım, güya patron masasının önünden geçerken şakaklarını ovuyormuş.'::text),
(382527,42503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag épp ... a halántékát, amikor a főnök elment az asztala mellett.'::text,'dörzsölte'::text,'megdörzsölte'::text,'megdörzsölte'::text,'Csajszi, állítólag épp dörzsölte a halántékát, amikor a főnök elment az asztala mellett.'::text),
(382530,42504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... dir seit einer Stunde den Stress weg und hast immer noch nicht aufgegeben.'::text,'reibst'::text,'reibst'::text,'reibst'::text,'Respekt, du reibst dir seit einer Stunde den Stress weg und hast immer noch nicht aufgegeben.'::text),
(382534,42504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти вже годину ... з себе стрес і досі не здалася.'::text,'розтираєш'::text,'розтираєш'::text,'розтираєш'::text,'Респект, ти вже годину розтираєш з себе стрес і досі не здалася.'::text),
(382533,42504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ... el estrés desde hace una hora y aún no te has rendido.'::text,'has estado frotándote para quitarte'::text,'estás frotándote para quitarte'::text,'te frotas para quitarte'::text,'Respeto, has estado frotándote para quitarte el estrés desde hace una hora y aún no te has rendido.'::text),
(382532,42504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, ça fait une heure que tu ... pour chasser le stress et t''as toujours pas lâché.'::text,'frottes'::text,'frottes'::text,'frottes'::text,'Respect, ça fait une heure que tu frottes pour chasser le stress et t''as toujours pas lâché.'::text),
(382535,42504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, bir saattir ovarak stresi ... ve hâlâ bırakmadın.'::text,'atıyorsun'::text,'atıyorsun'::text,'atarsın'::text,'Helal, bir saattir ovarak stresi atıyorsun ve hâlâ bırakmadın.'::text),
(382536,42504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, már egy órája ... ki magadból a stresszt, és még mindig nem adtad fel.'::text,'dörzsölöd'::text,'dörzsölöd'::text,'dörzsölöd'::text,'Respekt, már egy órája dörzsölöd ki magadból a stresszt, és még mindig nem adtad fel.'::text),
(382548,42506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie mehr geschlafen hätte, ... sie sich nicht den ganzen Vormittag am Schreibtisch die Schläfen gerieben.'::text,'hätte'::text,'wird'::text,'rieb'::text,'Wenn sie mehr geschlafen hätte, hätte sie sich nicht den ganzen Vormittag am Schreibtisch die Schläfen gerieben.'::text),
(382552,42506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона більше спала, то ... скроні за столом увесь ранок.'::text,'не терла б'::text,'не тертиме'::text,'не терла'::text,'Якби вона більше спала, то не терла б скроні за столом увесь ранок.'::text),
(382551,42506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera dormido más, no ... las sienes en su mesa toda la mañana.'::text,'se habría frotado'::text,'se frotará'::text,'se frotó'::text,'Si hubiera dormido más, no se habría frotado las sienes en su mesa toda la mañana.'::text),
(382550,42506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait dormi plus, elle ... les tempes à son bureau toute la matinée.'::text,'ne se serait pas frotté'::text,'ne se frottera pas'::text,'ne s''est pas frotté'::text,'Si elle avait dormi plus, elle ne se serait pas frotté les tempes à son bureau toute la matinée.'::text),
(382553,42506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha çok uyusaydı, bütün sabah masasında şakaklarını ...'::text,'ovmazdı'::text,'ovmayacak'::text,'ovmadı'::text,'Daha çok uyusaydı, bütün sabah masasında şakaklarını ovmazdı.'::text),
(382554,42506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha többet aludt volna, nem ... egész délelőtt a halántékát az asztalánál.'::text,'dörzsölte volna'::text,'fogja dörzsölni'::text,'dörzsölte'::text,'Ha többet aludt volna, nem dörzsölte volna egész délelőtt a halántékát az asztalánál.'::text),
(382557,42507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gab zu, sich die Schläfen ..., weil ihr der Bildschirm Kopfschmerzen machte.'::text,'gerieben zu haben'::text,'zu reiben'::text,'gerieben'::text,'Sie gab zu, sich die Schläfen gerieben zu haben, weil ihr der Bildschirm Kopfschmerzen machte.'::text),
(382561,42507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зізналася, що ... скроні, бо від екрана в неї боліла голова.'::text,'терла'::text,'терти'::text,'терла'::text,'Вона зізналася, що терла скроні, бо від екрана в неї боліла голова.'::text),
(382560,42507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... las sienes porque la pantalla le daba dolor de cabeza.'::text,'haberse frotado'::text,'frotarse'::text,'se frotó'::text,'Admitió haberse frotado las sienes porque la pantalla le daba dolor de cabeza.'::text),
(382559,42507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a admis ... les tempes parce que l''écran lui donnait mal à la tête.'::text,'s''être frotté'::text,'de se frotter'::text,'frotté'::text,'Elle a admis s''être frotté les tempes parce que l''écran lui donnait mal à la tête.'::text),
(382562,42507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekran başını ağrıttığı için şakaklarını ... itiraf etti.'::text,'ovduğunu'::text,'ovmayı'::text,'ovdu'::text,'Ekran başını ağrıttığı için şakaklarını ovduğunu itiraf etti.'::text),
(382563,42507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallotta, hogy ... a halántékát, mert a képernyőtől megfájdult a feje.'::text,'dörzsölte'::text,'dörzsölni'::text,'dörzsölte'::text,'Bevallotta, hogy dörzsölte a halántékát, mert a képernyőtől megfájdult a feje.'::text),
(382566,42508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich nicht eine Stunde lang die Schläfen gerieben haben; sie hat sich erst vor fünf Minuten hingesetzt.'::text,'kann'::text,'darf'::text,'sollte'::text,'Sie kann sich nicht eine Stunde lang die Schläfen gerieben haben; sie hat sich erst vor fünf Minuten hingesetzt.'::text),
(382570,42508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... терти скроні цілу годину; вона сіла лише п''ять хвилин тому.'::text,'не могла'::text,'не мусила'::text,'не мала б'::text,'Вона не могла терти скроні цілу годину; вона сіла лише п''ять хвилин тому.'::text),
(382569,42508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No ... frotado las sienes durante una hora; se sentó hace solo cinco minutos.'::text,'puede haberse'::text,'debe de haberse'::text,'debería haberse'::text,'No puede haberse frotado las sienes durante una hora; se sentó hace solo cinco minutos.'::text),
(382568,42508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... frotter les tempes pendant une heure ; elle s''est assise il y a seulement cinq minutes.'::text,'n''a pas pu se'::text,'n''a pas dû se'::text,'n''aurait pas dû se'::text,'Elle n''a pas pu se frotter les tempes pendant une heure ; elle s''est assise il y a seulement cinq minutes.'::text),
(382571,42508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saat boyunca şakaklarını ...; daha beş dakika önce oturdu.'::text,'ovmuş olamaz'::text,'ovmamış olmalı'::text,'ovmamalıydı'::text,'Bir saat boyunca şakaklarını ovmuş olamaz; daha beş dakika önce oturdu.'::text),
(382572,42508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... egy órán át a halántékát; csak öt perce ült le.'::text,'dörzsölhette'::text,'dörzsölte biztosan'::text,'kellett volna dörzsölnie'::text,'Nem dörzsölhette egy órán át a halántékát; csak öt perce ült le.'::text),
(382584,42510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, sie ... sich nicht den ganzen Tag die Schläfen reiben! Dieser Job ist ein totaler Albtraum!'::text,'müsste'::text,'muss'::text,'wird müssen'::text,'Sie wünscht sich, sie müsste sich nicht den ganzen Tag die Schläfen reiben! Dieser Job ist ein totaler Albtraum!'::text),
(382588,42510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хотіла б, щоб їй не ... терти скроні цілий день! Ця робота — повний жах!'::text,'доводилося'::text,'доводиться'::text,'доведеться'::text,'Вона хотіла б, щоб їй не доводилося терти скроні цілий день! Ця робота — повний жах!'::text),
(382587,42510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá no ... que frotarse las sienes todo el día! ¡Este trabajo es una pesadilla total!'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'¡Ojalá no tuviera que frotarse las sienes todo el día! ¡Este trabajo es una pesadilla total!'::text),
(382586,42510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ne pas ... se frotter les tempes toute la journée ! Ce job est un vrai cauchemar !'::text,'devoir'::text,'doit'::text,'devra'::text,'Elle aimerait ne pas devoir se frotter les tempes toute la journée ! Ce job est un vrai cauchemar !'::text),
(382589,42510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bütün gün şakaklarını ...! Bu iş tam bir kâbus!'::text,'ovmak zorunda olmasa'::text,'ovmak zorunda değil'::text,'ovmak zorunda olmayacak'::text,'Keşke bütün gün şakaklarını ovmak zorunda olmasa! Bu iş tam bir kâbus!'::text),
(382590,42510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ne ... egész nap a halántékát dörzsölnie! Ez a meló egy totális rémálom!'::text,'kellene'::text,'kell'::text,'kell majd'::text,'Bárcsak ne kellene egész nap a halántékát dörzsölnie! Ez a meló egy totális rémálom!'::text),
(382593,42511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bericht, ... Zahlen sie dazu brachten, sich die Schläfen zu reiben, ist eine komplette Katastrophe!'::text,'dessen'::text,'der'::text,'den'::text,'Der Bericht, dessen Zahlen sie dazu brachten, sich die Schläfen zu reiben, ist eine komplette Katastrophe!'::text),
(382597,42511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт, ... цифри змусили її терти скроні, — повна катастрофа!'::text,'чиї'::text,'який'::text,'що'::text,'Звіт, чиї цифри змусили її терти скроні, — повна катастрофа!'::text),
(382596,42511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El informe, ... cifras la hicieron frotarse las sienes, es un desastre total!'::text,'cuyas'::text,'que'::text,'el cual'::text,'¡El informe, cuyas cifras la hicieron frotarse las sienes, es un desastre total!'::text),
(382595,42511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rapport, ... les chiffres lui ont fait frotter les tempes, est un désastre complet !'::text,'dont'::text,'qui'::text,'que'::text,'Le rapport, dont les chiffres lui ont fait frotter les tempes, est un désastre complet !'::text),
(382598,42511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakamları ona şakaklarını ... rapor tam bir felaket!'::text,'ovduran'::text,'ovduran'::text,'ovduran'::text,'Rakamları ona şakaklarını ovduran rapor tam bir felaket!'::text),
(382599,42511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentés, ... számai miatt a halántékát dörzsölte, teljes katasztrófa!'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A jelentés, amelynek a számai miatt a halántékát dörzsölte, teljes katasztrófa!'::text),
(382602,42512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie reibt sich ständig die Schläfen ... des Lärms im vollen Büro.'::text,'wegen'::text,'trotz'::text,'obwohl'::text,'Sie reibt sich ständig die Schläfen wegen des Lärms im vollen Büro.'::text),
(382606,42512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона весь час тре скроні ... шум у галасливому офісі.'::text,'через'::text,'попри'::text,'хоча'::text,'Вона весь час тре скроні через шум у галасливому офісі.'::text),
(382605,42512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No deja de frotarse las sienes ... el ruido de la oficina llena de gente.'::text,'debido a'::text,'a pesar de'::text,'aunque'::text,'No deja de frotarse las sienes debido a el ruido de la oficina llena de gente.'::text),
(382604,42512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrête pas de se frotter les tempes ... bruit du bureau bondé.'::text,'à cause du'::text,'malgré le'::text,'même si le'::text,'Elle n''arrête pas de se frotter les tempes à cause du bruit du bureau bondé.'::text),
(382607,42512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık ofisteki gürültü ... sürekli şakaklarını ovuyor.'::text,'yüzünden'::text,'rağmen'::text,'olsa da'::text,'Kalabalık ofisteki gürültü yüzünden sürekli şakaklarını ovuyor.'::text),
(382608,42512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zsúfolt iroda zaja ... folyton a halántékát dörzsöli.'::text,'miatt'::text,'ellenére'::text,'bár'::text,'A zsúfolt iroda zaja miatt folyton a halántékát dörzsöli.'::text),
(382611,42513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... sie sich bis Mittag schon drei Stunden am Stück die Schläfen.'::text,'reibt'::text,'reibt'::text,'reibt'::text,'Hör zu, angeblich reibt sie sich bis Mittag schon drei Stunden am Stück die Schläfen.'::text),
(382615,42513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, до обіду вона ... скроні вже три години поспіль.'::text,'тертиме'::text,'тертиме'::text,'тре'::text,'Слухай, кажуть, до обіду вона тертиме скроні вже три години поспіль.'::text),
(382614,42513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, parece que a la hora de comer ... tres horas seguidas frotándose las sienes.'::text,'habrá estado'::text,'estará'::text,'ha estado'::text,'Escucha, parece que a la hora de comer habrá estado tres horas seguidas frotándose las sienes.'::text),
(382613,42513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment à midi, ça fera trois heures d''affilée qu''elle se ... les tempes.'::text,'frotte'::text,'frotte'::text,'frotte'::text,'Écoute, apparemment à midi, ça fera trois heures d''affilée qu''elle se frotte les tempes.'::text),
(382616,42513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya öğlene kadar üç saattir aralıksız şakaklarını ...'::text,'ovuyor olacak'::text,'ovuyor olacak'::text,'ovuyor'::text,'Dinle, güya öğlene kadar üç saattir aralıksız şakaklarını ovuyor olacak.'::text),
(382617,42513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ebédre már három órája ... egyfolytában a halántékát.'::text,'dörzsöli'::text,'dörzsöli majd'::text,'dörzsöli'::text,'Figyelj, állítólag ebédre már három órája dörzsöli egyfolytában a halántékát.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
